(window.GIM_TS=window.GIM_TS||{})["Ketubot.1"]={"from":24,"a":[["\u0003אין, מינאי\u0004 \u0005[כן, ממני]\u0006 היא מעוברת. \u0003אמר רב יוסף: למאי ניחוש\u0004 \u0005[למה נחשוש]\u0006 \u0003לה\u0004 לאשה זו? \u0003חדא, דהא קא מודה\u0004 \u0005[אחת, שהרי\u0006 הוא \u0005מודה]\u0006 שהולד הוא שלו, \u0003ועוד, הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב יהודה אמר שמואל: הלכה כרבן גמליאל,\u0004 ואפילו כשאינו מודה היא נאמנת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ובהא\u0004 \u0005[וב\u0006כגון \u0005זה]\u0006 מאחר שאתה סבור שיש כאן שני טעמים להתיר את הולד, האם כוונתך לומר \u0003כי\u0004 \u0005[כאשר]\u0006 האיש \u0003לא מודה\u0004 גם \u0003מכשר\u0004 \u0005[מכשיר]\u0006 \u0003רבן גמליאל? והאמר ליה\u0004 \u0005[והרי אמר לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 \u0005[גדול השיניים],\u0006 \u0003הלכה\u0004 אמנם \u0003כרבן גמליאל\u0004 שהיא נאמנת, \u0003ואת\u0004 \u0005[ו\u0006אולם \u0005אתה]\u0006 \u0003לא תעביד עובדא\u0004 \u0005[תעשה מעשה]\u0006 להכשיר \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003רוב כשרין אצלה,\u0004 כלומר, שרוב החשודים בבעילה זו הם כשרים לגביה, שאפשר לסמוך גם על הרוב ולא רק על עדותה. \u0003והכא\u0004 \u0005[וכאן]\u0006 כיון שהיתה ארוסה — נמצא ש\u0003רוב\u0004 האנשים הם \u0003פסולין אצלה,\u0004 שאם נבעלה לכל אדם מלבד הארוס — הוולד ממזר. וכיון שאין רוב כשרים אצלה — לא היה צריך שמואל לפסוק כרבן גמליאל!","ענה רב יוסף לאביי: \u0003וליטעמיך תקשי לך היא גופא\u0004 \u0005[ולטעמך,\u0006 לשיטתך, \u0005תקשה לך\u0006 הלכה \u0005זו עצמה],\u0006 שהלא מצד אחד פוסק שמואל \u0003הלכה,\u0004 ומוסיף ואומר \u0003ואת\u0004 \u0005[ואתה]\u0006 \u0003לא תעביד עובדא\u0004 \u0005[תעשה מעשה]!\u0006 ותמוה: שאם פוסק הלכה כרבן גמליאל — מדוע אמר לרב יהודה שלא יעשה מעשה בהתאם לשיטה זו? \u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 כדי להסביר סתירה זו — \u0003הא\u0004 \u0005[זו]\u0006 לסמוך על עדות כזו — \u0003לכתחלה,\u0004 ו\u0003הא\u0004 \u0005[זו]\u0006 — ב\u0003דיעבד,\u0004 שמאחר והיא כבר מעוברת מביאה זו ואין עדות מסייעת אחרת — אפשר לסמוך בדיעבד על דברי האשה אפילו ברוב פסולים. \u0003והא נמי\u0004 \u0005[וזו גם כן\u0006 הארוסה\u0005],\u0006 \u0003כדיעבד דמי\u0004 \u0005[נחשב],\u0006 שהרי בסופו של דבר אם לא נסמוך על דבריה נצטרך לפסול את הולד כממזר. ולכן יש לסמוך על דברי רבן גמליאל לענין הזה אף לדעת שמואל.","\u0003רמי ליה\u0004 \u0005[השליך,\u0006 הראה \u0005לו\u0006 סתירה\u0005]\u0006 \u0003אביי לרבא: ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יהושע\u0004 שהאשה \u0003אינה נאמנת\u0004 בעדותה בענין כגון זה? \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממקום אחר: \u0003העיד ר' יהושע ור' יהודה בן בתירא על אלמנת עיסה\u0004 (אשה אלמנה, שהיה ספק לגבי בעלה אם היה חלל, ופסלה מן הכהונה) \u0003שהיא כשרה לכהונה.\u0004 שכיון שאין ודאות בדבר — מעמידים אותה על חזקתה, ואף כאן נעמיד את האשה על חזקתה שנבעלה לכשר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003הכי השתא\u0004 \u0005[איך אתה משווה]\u0006 את הדברים?! \u0003התם\u0004 \u0005[שם]\u0006 באלמנה אפשר לומר: \u0003אשה\u0004 ש\u0003נישאת,\u0004 מן הסתם \u0003בודקת\u0004 לפני נישואיה \u0003ונישאת,\u0004 וחזקה שבדקה ומצאה שלא היה צד פסול בנישואיה, ולכן אפשר לסמוך על חזקתה. אבל \u0003הכא\u0004 \u0005[כאן],\u0006 וכי \u0003אשה מזנה בודקת\u0004 את האיש שמזנה אתו אם כשר הוא לכל דבר \u0003ו\u0004אחר כך \u0003מזנה?!\u0004","\u0003אמר רבא:\u0004 תירוץ זה אינו פותר את כל הקשיים שיש בדבר, וכי רק מדברי \u0003ר' יהושע\u0004 על דברי \u0003ר' יהושע קשיא\u0004 \u0005[קשה],\u0006 אך מדברי \u0003רבן גמליאל\u0004 על דברי \u0003רבן גמליאל לא קשיא\u0004 \u0005[קשה]?\u0006 \u0003והא קתני סיפא\u0004 \u0005[והרי שנה\u0006 ב\u0005סופה]\u0006 של אותה משנה באלמנת עיסה: \u0003אמר להן רבן גמליאל: קבלנו עדותכם\u0004 שכך היא ההלכה, \u0003אבל מה נעשה שהרי גזר רבן יוחנן בן זכאי שלא להושיב בית דין על כך\u0004 להתיר במקרה כזה, \u0003שהכהנים שומעין לכם לרחק אבל לא לקרב.\u0004 כלומר, הם יצייתו לדיינים רק אם יפסלו אותה, אבל לא יצייתו להם לראותה ככשירה. ואם כן, הרי שלא קיבל רבן גמליאל את ההיתר לאלמנת עיסה, ובניגוד לדבריו האמורים כאן!","\u0003אלא אמר רבא,\u0004 כך יש לומר: מדברי \u0003רבן גמליאל\u0004 על דברי \u0003רבן גמליאל לא קשיא\u0004 \u0005[קשה];\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בטענת האשה שנבעלה — \u0003ברי\u0004 \u0005[ברור]\u0006 לה שלכשר נבעלה, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 באלמנת עיסה — טענת \u0003שמא\u0004 היא, גם מצד האשה, שהרי היא אינה יכולה לדעת בבירור אם בעלה היה חלל, כיון שהספק הוא ספק לכל.","וכן מדברי \u0003ר' יהושע\u0004 על דברי \u0003ר' יהושע נמי לא קשיא\u0004 \u0005[גם כן אינו קשה]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בטענת האשה לכשרותה — \u0003חד ספיקא\u0004 \u0005[ספק אחד]\u0006 הוא, אם נבעלה לכשר או לפסול, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 באלמנת עיסה — \u0003תרי ספיקי\u0004 \u0005[שני ספקות]\u0006 הם, שיש כאן ספק ספיקא של פסול, שהרי אין בידינו ידיעה ברורה אם היה מישהו ממשפחת הבעל פסול כל עיקר.","\u0003הלכך\u0004 (על כן) יש להסביר את השיטות כך: \u0003לרבן גמליאל אלים ליה\u0004 \u0005[תקיפה לו\u0006 חזקה בעיניו\u0005]\u0006 טענת \u0003ברי,\u0004 ש\u0003אפילו בחד ספיקא נמי\u0004 \u0005[בספק אחד גם כן]\u0006 \u0003מכשיר,\u0004 שכיון שהיא טוענת ברי, אף שיש פה ספק אחד ולא ספק ספיקא — מכשיר אותה. \u0003וקיל ליה\u0004 \u0005[וקל לו\u0006 בעיניו\u0005]\u0006 הטוען טענת \u0003שמא,\u0004 ש\u0003אפילו בספק ספיקא נמי פסיל\u0004 \u0005[גם כן פוסל],\u0006 כגון באלמנת עיסה. ולהיפך, \u0003לר' יהושע אלים ליה חד ספיקא\u0004 \u0005[תקיף לו,\u0006 בעיניו, \u0005ספק אחד],\u0006 ש\u0003אפילו בברי נמי פסיל\u0004 \u0005[ב\u0006שטוענת טענה \u0005ברורה גם כן פוסל],\u0006 \u0003וקיל ליה\u0004 \u0005[וקל לו\u0006 בעיניו\u0005]\u0006 \u0003ספק ספיקא,\u0004 ש\u0003אפילו בשמא נמי\u0004 \u0005[גם כן]\u0006 \u0003מכשיר\u0004 את האשה.","כיון שהזכרנו אלמנת עיסה, מביאים דברים שנאמרו בנושא זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזוהי אלמנת עיסה\u0004 שאמרו שהיא כשירה \u0003— כל שאין בה לא משום\u0004 ספק \u0003ממזרות, ולא משום\u0004 ספק \u0003נתינות\u0004 (בני גבעונים), \u0003ולא משום עבדי מלכים\u0004 שהיו תקיפים, ויש שהיו נושאים בכוח הזרוע נשים מישראל, ואף מבנות הכהנים. והספק היחיד שיש באלמנת עיסה, היא ספק חלל. \u0003אמר ר' מאיר:\u0004"],["\u0003שמעתי כל שאין בה אחד מכל\u0004 ספקות \u0003אלו,\u0004 אלא רק ספק חללות בלבד — \u0003משיאין לכהונה.\u0004","\u0003ר' שמעון בן אלעזר אומר משום ר' מאיר, וכן היה ר' שמעון בן מנסיא אומר כדבריו: איזוהי אלמנת עיסה — כל שנטמע\u0004 (נתערב) \u0003בה\u0004 במשפחה \u0003ספק חלל,\u0004 ולכן קוראים לה \"אלמנת עיסה\", שהיא כעיסה שנתערב בה דבר מה, ואף במשפחה זו נתערב ספק חלל.","והטעם בדבר כי אמנם \u0003מכירין ישראל ממזרים שביניהם,\u0004 ואין לחשוש שמא נתערבו במשפחות כשרות, \u0003ו\u0004אולם \u0003אין מכירין חללין שביניהם,\u0004 ולכן יש לחשוש שמא נתערב חלל במשפחה.","ומבררים את הברייתא, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003איזוהי אלמנת עיסה? כל שאין בה לא משום\u0004 ספק \u0003ממזרות, ולא משום\u0004 ספק \u0003נתינות, ולא משום עבדי מלכים. הא\u0004 \u0005[הרי],\u0006 מכאן משמע, אם היה במשפחה רק ספק \u0003חלל\u0004 — הרי זה \u0003כשר.\u0004","ויש לשאול: \u0003מאי שנא הנך\u0004 \u0005[\u0006ב\u0005מה שונים\u0006 פסולים \u0005אלה]\u0006 שפוסלים אותה אף בספק— משום שכשהם פסולים וודאים, הם פוסלים אותה \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003חלל נמי דאורייתא\u0004 \u0005[גם כן\u0006 פוסל \u0005מן התורה]\u0006 לכהונה! \u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול, כי בהמשך הדברים \u0003אמר ר' מאיר: שמעתי,\u0004 כי \u0003כל\u0004 אשה \u0003שאין בה אחד מכל אלו — משיאין\u0004 אותה \u0003לכהונה,\u0004 אם כן \u0003היינו\u0004 \u0005[הרי זו]\u0006 בדיוק שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 שאלמנת עיסה כשירה לכהונה, ומה חידוש יש איפוא בדברי ר' מאיר?!","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול: נאמר שם ש\u0003ר' שמעון בן אלעזר אומר משום ר' מאיר, וכן היה ר' שמעון בן מנסיא אומר כדבריו: איזוהי אלמנת עיסה — כל שנטמע בה ספק חלל,\u0004 כי \u0003מכירין ישראל ממזרים שביניהן ואין מכירין חללין שביניהן,\u0004 ויש לחשוש שמא נתערב במשפחה זו חלל, ומשמע שבשל ספק זה יש לדבריו לפוסלה. \u0003והא אמרת רישא\u0004 \u0005[והרי אמרת,\u0006 ב\u0005תחילת\u0006 דברי ר' שמעון בן אלעזר\u0005]\u0006 איזוהי אלמנת עיסה האמורה שהכשירוה להינשא לכהונה, ומשמע מזה שספק \u0003חלל כשר,\u0004 ואם כן יש סתירה פנימית בדבריו!","\u0003אמר ר' יוחנן:\u0004 כאן מדובר במקרה של אדם שכאשר קוראים לו \u0003\"ממזר\"\u0004 הוא \u0003צווח\u0004 ומוחה שמעלילים עליו עלילת שוא, \u0003ו\u0004כשקוראים לו \u0003\"חלל\"\u0004 הוא \u0003שותק.\u0004 ובענין זה \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]:\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 של הברייתא \u0003סבר: כל פסול דקרו ליה ושתיק\u0004 \u0005[שקוראים לו\u0006 לאדם \u0005ו\u0006הוא \u0005שותק\u0006 ואינו מוחה בו\u0005]\u0006 הרי זה \u0003פסול,\u0004 שיש להניח שבאמת יש בו פסול זה. \u0003והכי קאמר\u0004 \u0005[וכך אמר]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 כך יש להבין את דבריו: \u0003איזוהי אלמנת עיסה\u0004 שכשירה — \u0003כל שאין בה לא שתוק ממזרות,\u0004 כלומר, שכאשר מאשימים את האיש או את המשפחה בממזרות, הרי הם צווחים. \u0003ולא שתוק נתינות ולא שתוק עבדי מלכים, ולא שתוק חלל.\u0004 כלומר, שבכל מקרה שאומרים עליהם שהם פסולים, הם מוחים.","\u0003וקאמר ליה\u0004 \u0005[ואמר לו]\u0006 \u0003ר' מאיר:\u0004 דווקא \u0003הנך הוא\u0004 \u0005[אלה הם]\u0006 שקוראים להם \"ממזר\", \"נתין\" או \"עבד\", שיש לומר משום \u0003דקא פסיל ליה\u0004 \u0005[שפוסל אותו]\u0006 מלבוא \u0003בקהל\u0004 ולכן כשאומרים לו שהוא ממזר — הרי הוא צווח, משום שחושש שיבואו לפסול אותו מלבוא בקהל, וכשהוא שותק הריהו מודה בכך. \u0003אבל שתוק חלל,\u0004 אפילו אם אינו מוחה כשאומרים לו שהוא חלל — הרי זה \u0003כשר,\u0004 ואין חוששים שמא הוא חלל. \u0003והא דשתיק\u0004 \u0005[וזה ש\u0006הוא \u0005שותק] —\u0006 \u0003משום\u0004 ש\u0003לא איכפת ליה\u0004 \u0005[לו],\u0006 שכיון שאין חללות פוסלת אלא לענין נישואין לכהנים, אינו מוצא ענין למחות בדבר.","\u0003וקאמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון בן אלעזר לתנא קמא\u0004 \u0005[הראשון]\u0006 שמסר בשם \u0003ר' מאיר: אי שמיע לך דמכשר\u0004 \u0005[אם שמעת שמכשיר]\u0006 \u0003ר' מאיר ב\u0004מקרה של \u0003שתיקה\u0004 — הכוונה היא \u0003לא\u0004 במקרה \u0003דקרו ליה\u0004 \u0005[שקוראים לו]\u0006 \u0003\"חלל\" ושתיק\u0004 \u0005[ו\u0006הוא \u0005שותק],\u0006 \u0003אלא דקרו ליה\u0004 \u0005[שקוראים לו]\u0006 \u0003\"ממזר\" ושתיק\u0004 \u0005[ו\u0006הוא \u0005שותק]\u0006 \u0003ו\u0004הטעם הוא: \u0003האי דשתיק, סבר\u0004 \u0005[וזה ש\u0006הוא \u0005שותק\u0006 משום שהוא \u0005סבור]\u0006 כי \u0003ממזר קלא אית ליה\u0004 \u0005[קול יש לו]\u0006 והוא מפורסם ברבים, וכיון שהוא אינו מפורסם כממזר — שותק ואינו חושש למחות באופן נמרץ על הענין. \u0003אבל\u0004 כשקוראים לו \u0003\"ממזר\" וצווח,\u0004 וכשקוראים לו \u0003\"חלל\" ושותק — פסול. ו\u0004טעמו של דבר — \u0003האי דאשתיק סבר\u0004 \u0005[זה ש\u0006הוא \u0005שותק\u0006 ואינו מוחה על כך, הרי זה משום שהוא \u0005סבור]\u0006 \u0003מיסתייה דלא מפקי ליה\u0004 \u0005[די לו שאין מוציאים אותו]\u0006 \u0003מ\u0004כלל כשרות ל\u0003קהל\u0004 ולכן אינו צווח, ואם כן יש לשער שבאמת היה בו פגם זה.","ומעירים: \u0003תני חדא\u0004 \u0005[שנוייה\u0006 ברייתא \u0005אחת],\u0006 \u0003ר' יוסי אומר: שתוק ממזר — כשר, שתוק חלל — פסול. ותניא אידך\u0004 \u0005[ושנוייה\u0006 ברייתא \u0005אחרת]\u0006 להיפך: \u0003שתוק חלל — כשר, שתוק ממזר — פסול.\u0004","ומסבירים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 כי יש כאן שתי שיטות, \u0003הא\u0004 \u0005[זו] —\u0006 הברייתא השניה היא שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003ר' מאיר\u0004 הסבור שמי שאומרים עליו שהוא חלל ושותק — אין ראיה בכך שהוא מודה לדבר. ו\u0003הא\u0004 \u0005[\u0006ו\u0005זו]\u0006 הברייתא הראשונה היא שיטת \u0003ר' שמעון בן אלעזר אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003ר' מאיר\u0004 האומר שאם הוא שותק בממזרות — הרי זה משום שלא איכפת לו, ואם הוא שותק בחללות — הרי זה משום שהדבר הוא אמת.","\u0003אמר ר' יוסי: מעשה\u0004 היה \u0003בתינוקת\u0004 (ילדה) \u0003שירדה למלאות מים מן העין\u0004 (המעין) שליד העיר \u0003ונאנסה,\u0004 ולא ידעו מי אנסה. \u0003אמר ר' יוחנן בן נורי: אם רוב אנשי העיר משיאין\u0004 בנותיהם \u0003לכהונה — הרי זו תינשא לכהונה,\u0004 שיש לתלות שהאנס היה אחד מאנשי העיר הכשרים. ואף על פי שאנסה — לא פסלה מן הכהונה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: ר' יוחנן בן נורי\u0004 ש\u0003אמר כמאן\u0004 \u0005[כמי]\u0006 כלומר, לפי איזו שיטה הוא הולך? \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא סבור \u0003כ\u0004שיטת \u0003רבן גמליאל\u0004 — אם כן \u0003אפילו ברוב\u0004 אנשי העיר \u0003פסולין נמי מכשר\u0004 \u0005[גם כן מכשיר]\u0006 רבן גמליאל. משום שסבור כי האשה היא בחזקת כשרות. ו\u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 \u0003כ\u0004שיטת \u0003ר' יהושע\u0004 הוא סבור — אם כן \u0003אפילו ברוב כשרים נמי פסיל\u0004 \u0005[גם כן פוסל],\u0006 שהרי הוא סבור שעד שאינה מוכיחה אחרת, יש לחשוש שנבעלה לפסול, אפילו כשאין הפסולים רוב. ולכאורה ר' יוחנן בן נורי חולק על שניהם! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה אמר רב:\u0004"],["\u0003בקרונות של ציפורי היה מעשה,\u0004 כלומר, מעשה זה אירע ביום השוק, ובאו שיירות וקרונות לעיר ציפורי ליום השוק, \u0003וכ\u0004דברי \u0003ר' אמי.\u0004 ש\u0003אמר ר' אמי: והוא ש\u0004בתוך כל אותן שיירות וקרונות \u0003היתה סיעה של בני אדם כשרין עוברת לשם,\u0004 ומשום שגם רוב אנשי העיר שבה קרה המעשה היו כשרים וגם רוב האורחים שבאו מבחוץ היו כשרים — יש איפוא לתלות בכשר. \u0003וכ\u0004דברי \u0003ר' ינאי,\u0004 ש\u0003אמר ר' ינאי: נבעלת בקרונות — כשרה לכהונה.\u0004","ותוהים על הלשון: \u0003בקרונות סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר שאשה נבעלת בקרונות שעושים בהם מסחר ברשות הרבים? \u0003אלא\u0004 הכוונה היא ל\u0003נבעלת בשעת קרונות,\u0004 כלומר, בשעה שבאות השיירות, וזו היא ה\u0003כשרה לכהונה. אבל\u0004 אם \u0003פירש אחד מציפורי\u0004 שהיה אדם אחד שברור לנו שהיה מן העיר ציפורי ואין אנו יודעים אם היה זה כשר או פסול, אף על פי שידוע שרוב אנשי העיר כשרים לכהונה, \u0003ובעל\u0004 אשה — \u0003הולד שתוקי\u0004 ופסול מספק, ואין הולכים אחר רוב אנשי העיר.","\u0003כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003זעירי,\u0004 ש\u0003אמר\u0004 בשם \u0003ר' חנינא, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 את השמועה במישרין, \u0003אמר זעירי אמר ר' חנינא: הולכין אחר רוב העיר, ואין הולכין אחר רוב סיעה.\u0004 שאפילו היו רוב אנשי סיעה הנודדת ממקום למקום כשרים, אין מכשירים את האשה שנבעלה לאחד מהם.","על הלכה זו תוהים: \u0003כלפי לייא\u0004 \u0005[לאן אתה פונה]?!\u0006 כלומר, הדבר הוא היפוכה של הסברה, כי הלוא \u0003הני\u0004 \u0005[אלה],\u0006 אנשי השיירה \u0005—\u0006 \u0003ניידי\u0004 \u0005[נודדים],\u0006 וכלל בידינו שבניידים הולכים אחר הרוב ולא אחר המיעוט, \u0003והני\u0004 \u0005[ואלה],\u0006 אנשי העיר — \u0003קביעי וקיימי\u0004 \u0005[קבועים ועומדים],\u0006 ולפי הכלל דנים אותם כמחצה על מחצה וכספק שקול!","\u0003אלא,\u0004 כך יש לפרש: \u0003הולכין אחר רוב העיר, והוא\u0004 דווקא במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003רוב סיעה\u0004 של הזרים \u0003בהדה\u0004 \u0005[עמה,\u0006 עם אנשי העיר\u0005]\u0006 שגם הם כשרים, שאז יש לתלות בכשרים משני הצדדים, \u0003ואין הולכין אחר רוב העיר גרידתא\u0004 \u0005[בלבד]\u0006 \u0003ולא אחר רוב סיעה גרידתא\u0004 \u0005[בלבד],\u0006 וכגון כשהם רחוקים מן העיר\u0005.\u0006 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003גזרה רוב סיעה אטו\u0004 \u0005[משום]\u0006 \u0003רוב העיר.\u0004","ותוהים: \u0003ורוב העיר נמי\u0004 \u0005[גם כן]\u0006 \u0003אי דקא אזלי אינהו לגבה\u0004 \u0005[אם\u0006 כ\u0005שהם הולכים אליה],\u0006 שהיא היתה מחוץ לעיר, ומישהו מאנשי העיר פרש והלך — הלוא יש ללכת לפי הכלל: \u0003כל דפריש\u0004 \u0005[שפורש] —\u0006 \u0003מרובא פריש\u0004 \u0005[מן הרוב\u0006 הוא \u0005פורש],\u0006 שיש לתלות שהוא מן הרוב ולא מן המיעוט, ומדוע נאמר שרוב אנשי העיר נחשב כספק שקול? \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דקא אזלא איהי לגבייהו\u0004 \u0005[שהלכה היא אליהם],\u0006 כגון שהלכה אל תוך העיר, \u0003דהוה ליה\u0004 \u0005[שהיה לו,\u0006 שנעשה\u0005]\u0006 הספק בגדר \u0003קבוע\u0004 במקומו, \u0003ואמר ר' זירא: כל\u0004 ספק בדבר \u0003קבוע — כמחצה על מחצה דמי\u0004 \u0005[נחשב]\u0006 ואין הולכים אחר הרוב.","לעצם ההלכה שואלים: \u0003ומי בעינן תרי רובי\u0004 \u0005[והאם צריכים אנו שני \"רוב\"ים,\u0006 פעמיים רוב\u0005]\u0006 כדי להכריע כנגד המיעוט? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 היו בשוק אחד \u0003תשע חנויות, כולן מוכרות בשר שחוטה\u0004 (כשר), \u0003ו\u0004עוד חנות \u0003אחת מוכרת בשר נבלה, ולקח\u0004 (קנה) בשר \u0003מאחת מהן ואינו יודע מאי זה מהן לקח — ספיקו אסור.\u0004 ולפי הכלל שאמרנו, שאף על פי שיש רוב כשרים, כיון שהם קבועים הרי הספק נדון כמחצה על מחצה. \u0003ובנמצא,\u0004 אם נמצא בשר בשוק ואין יודעים אם כשר הוא — \u0003הלך אחר הרוב,\u0004 וכיון שרוב החנויות מוכרות בשר כשר, אף בשר זה כשר.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שמדובר כאן \u0003ב\u0004מקרה \u0003שאין דלתות מדינה\u0004 (העיר) \u0003נעולות,\u0004 וייתכן גם \u0003דקא אתי\u0004 \u0005[שבא]\u0006 \u0003לה רובא\u0004 \u0005[רוב]\u0006 של בשר כשר \u0003מעלמא\u0004 \u0005[מן העולם,\u0006 מן החוץ\u0005],\u0006 וכגון שרוב החנויות מחוץ לעיר זו מוכרות בשר כשר, ומפני שמצרפים רוב חנויות שבעיר זו עם רוב הבשר שמבחוץ, שמא משום כך הכל כשר, והרי שאין להכשיר אלא כשיש פעמיים רוב — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' זירא: אף על פי שדלתות מדינה נעולות,\u0004 הולכים אחר הרוב בנמצא. משמע שאין צריכים פעמיים רוב, ודי ברוב אחד! ומשיבים: \u0003מעלה עשו ביוחסין,\u0004 שבשאר דברים, כגון בהלכות איסור והיתר ובדיני טריפות, די ברוב אחד, אבל בענייני יוחסין צריכים שיהיה רוב יותר גדול כדי לסמוך על כך שאשה שנבעלה על ידי איש כשר, מן הרוב נבעלה ולא מן המיעוט.","\u0003גופא\u0004 \u0005[\u0006ל\u0005גופה]\u0006 של הלכה זו, \u0003אמר ר' זירא: כל קבוע — כמחצה על מחצה דמי\u0004 \u0005[נחשב]\u0006 \u0003בין לקולא\u0004 \u0005[להקל]\u0006 \u0003בין לחומרא\u0004 \u0005[להחמיר],\u0006 שגם אם הדבר הוא להקל, כגון שהרוב הוא לאיסור ורק מיעוט הוא להיתר, כיון שהוא קבוע — הרי זה נחשב כספק שקול.","ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לר' זירא הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מ\u0004מה ששנינו: \u0003תשע חנויות כולן מוכרות בשר שחוטה\u0004 (כשר), \u0003ואחת\u0004 מוכרת \u0003בשר נבלה, ולקח\u0004 (קנה) \u0003מאחת מהן ואינו יודע מאיזה מהן לקח — ספיקו אסור,\u0004 משום קבוע, שהחתיכה היתה קבועה במקומה כשהתחיל הספק. \u0003וב\u0004בשר ה\u0003נמצא\u0004 בשוק — \u0003הלך אחר הרוב\u0004 — אולם \u0003התם לחומרא\u0004 \u0005[שם\u0006 הקבוע נחשב כמחצה \u0005להחמיר]\u0006 ולא להקל!","\u0003אלא\u0004 תאמר שראייתו \u0003מ\u0004ברייתא אחרת: אם היו \u0003תשעה צפרדעים\u0004 שהם שקצים שאינם מטמאים לא בחייהם ולא במותם, \u0003ושרץ אחד\u0004 טמא \u0003ביניהם,\u0004 שנבלתו מטמאה, \u0003ונגע באחד מהן,\u0004 באחד מעשרה אלה, \u0003ואינו יודע באיזה מהן נגע,\u0004 הרי במקרה כזה \u0003ספיקו טמא.\u0004 שאף שהשרץ הטמא הוא רק אחד מבין עשרה, מכל מקום דנים אנו אותו כאילו היה כאן ספק שקול. אולם \u0003התם נמי לחומרא\u0004 \u0005[שם גם כן\u0006 הקבוע נחשב כמחצה \u0005להחמיר]\u0006 ולא להקל!","\u0003אלא\u0004 ראייתו היא \u0003מ\u0004מה ששנינו בהמשך: \u0003תשעה שרצים וצפרדע אחד ביניהם ונגע באחד מהן, ואינו יודע באיזה מהן נגע,\u0004 אם היה הדבר \u0003ברשות היחיד — ספיקו טמא.\u0004 שאנו למדים ממדרש המקראות שברשות היחיד כל ספק טומאה, טמא, ו\u0003ברשות הרבים — ספיקו טהור.\u0004 ואם כן, אף שרוב השקצים היו טמאים, מכל מקום כיון שהיה זה קבוע — אומרים שקבוע הוא רק כמחצה, ורואים את הדבר כספק ולא כוודאי ומקילים, שכלל בידינו כי ספק טומאה ברשות הרבים טהור. אם כן הוכחנו את דברי ר' זירא שהקבוע כמחצה בין להקל בין להחמיר מהלכה זו.","ולעצם הלכה זו של קבוע שואלים: \u0003ומדאורייתא מנא לן\u0004 \u0005[ומן התורה מניין לנו]\u0006 ראיה שכך הוא הדבר, שקבוע נחשב כמחצה על מחצה? — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין רוצח: \u0003\"וארב לו וקם עליו\"\u0004 (דברים יט, יא), והכוונה היא: \u0003עד שיתכוין לו,\u0004 כלומר, לא שגרם שייהרג אדם במקרה, אלא שהתכוון להריגתו (\"וארב לו\"). \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 כיצד הם דורשים? — \u0003אמרי דבי\u0004 \u0005[אומרים\u0006 משם \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 שהוא \u0003פרט לזורק אבן לגו\u0004 \u0005[לתוך]\u0006 קהל, בלי שיתכוון לפגוע באדם מסויים.","ונברר \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]\u0006 כשזרק אבן זו? \u0003אילימא דאיכא\u0004 \u0005[אם תאמר שיש]\u0006 בקהל זה \u0003תשעה גויים ואחד ישראל ביניהם,\u0004 וכיון שרובם היו גויים, שאינו חייב על רציחתם באופן זה, והרי הוא פטור אפילו אם פגע בישראל והרגו — אולם \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו לא מטעם הספק שיש בקבוע, אלא מן הטעם \u0003דרובא\u0004 \u0005[שרובם]\u0006 של האנשים \u0003גויים נינהו\u0004 \u0005[הם]\u0006 והולכים אחר הרוב. \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 אפילו אם תאמר שהם נחשבים כ\u0003פלגא ופלגא\u0004 \u0005[מחצה ומחצה]\u0006 — הלוא \u0003ספק נפשות להקל,\u0004 וכיון שיש פה ספק לגבי חיוב בנפשו של הרוצח — אנחנו מקילים בדינו ואין הורגים אותו מפני הספק.","אלא \u0003לא צריכא\u0004 \u0005[נצרך]\u0006 הכתוב אלא במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003תשעה ישראלים וגוי אחד ביניהם,\u0004 שבכל זאת, כיון \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 ה\u0003גוי קבוע, וכל קבוע\u0004 דינו \u0003כמחצה על מחצה דמי\u0004 \u0005[נחשב]\u0006 ואין זורק האבן חייב מיתה, וכיון שהוא ספק שקול, הרי ספק נפשות להקל, ומכאן שאפילו בדין תורה ולענין חיוב חמור כרציחה, קבוע (אפילו הוא מיעוט) נחשב כמחצה. ואין הולכים אחר הרוב.","לגופה של ההלכה שעסקנו בה לענין הליכה אחר הרוב ביוחסין, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר, \u0003רב חייא בר אשי אמר\u0004 בשם \u0003רב: הלכה כר' יוסי\u0004 במשנתנו, ואותה תינוקת שנאנסה מותרת. \u0003ורב חנן בר רבא אמר\u0004 בשם \u0003רב: הוראת שעה היתה.\u0004 שאף שכך הורו בשעתו — הרי היתה זו הוראת שעה, אבל בדרך כלל אנחנו צריכים שיהיו פעמיים רוב.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' ירמיה\u0004 על סברה ראשונה שהלכה כר' יוסי, שמשמע מכאן שדי רק ברוב אחד, ברוב אנשי העיר — \u0003ו\u0004האם \u0003ל\u0004ענין \u0003יוחסין לא בעינן תרי רובי\u0004 \u0005[אין אנו צריכים שני \"רוב\"ים],\u0006 גם רוב העיר וגם רוב האנשים שמחוץ העיר? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003מצא בה תינוק מושלך\u0004 ואין ידוע מיהו, \u0003אם רוב\u0004 תושבי העיר הם \u0003גויים\u0004 — דנים אותו כאילו הוא \u0003גוי. אם רוב\u0004 בני העיר הם \u0003ישראל\u0004 — הוא נחשב \u0003ישראל.\u0004 אם הם \u0003מחצה על מחצה\u0004 — דינו כ\u0003ישראל.\u0004","\u0003ואמר רב: לא שנו\u0004 דין זה שאם רוב אנשי העיר הם ישראל דינו של התינוק הנמצא כישראל, \u0003אלא\u0004 לענין \u0003להחיותו.\u0004 כלומר, שצריך לדאוג לו ולפרנסו מתוך הנחה שהוא ישראל. \u0003אבל ל\u0004ענין \u0003יוחסין,\u0004 כגון להשיאו אשה — \u0003לא,\u0004 שאין סומכים על כך וצריך לגיירו. \u0003ושמואל אמר:\u0004 לא נאמר הדבר אלא \u0003לפקח עליו את הגל.\u0004 כלומר, שאם הילד הזה יהיה בסכנת נפשות בשבת, ויהיה צורך לחלל עליו שבת — הרי אנו מניחים שהוא ישראל לענין זה שמחללים עליו את השבת. ועל כל פנים, מדברי רב אנחנו למדים שלא די ברוב אחד (\"רוב ישראל\" שבעיר) כדי להכשיר ליוחסין!","ומשיבים: \u0003אשתמיטתיה\u0004 \u0005[נשמט ממנו,\u0006 שכח\u0005]\u0006 ר' ירמיה \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב יהודה אמר רב\u0004 לגבי משנתנו: \u0003בקרונות של צפורי הוה\u0004 \u0005[היה]\u0006 \u0003מעשה\u0004 זה בתינוקת, וכפי שהסברנו היו שם שני רוב; רוב אנשי העיר הכשרים, ורוב האנשים הכשרים הבאים אל העיר.","ושואלים: \u0003ולרב חנן בר רבא\u0004 ש\u0003אמר\u0004 בשם רב ש\u0003הוראת שעה היתה\u0004 זו, להצריך שני רוב, ואולם אין נוהגים כן לדורות, אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 באמת הלכה זו, שהרי כאן אמר רב שלענין יוחסין לא מספיק רוב אחד, ומדוע אמר רב חנן שזו רק \"הוראת שעה\"? ומשיבים: \u0003מאן דמתני הא, לא מתני הא\u0004 \u0005[מי ששונה\u0006 את \u0005זו\u0006 שהיתה זו הוראת שעה, \u0005אינו שונה\u0006 את \u0005זו],\u0006 שנאמר בשם רב שהיה זה בשעת קרונות של צפורי, ושם היה באמת רק רוב אחד, והיתה זו הוראת שעה שהתירה את התינוקת, שכן כרגיל צריך פעמיים רוב ביוחסין.","כיון שהזכרנו את ענין התינוק שנמצא בעיר דנים בהלכה זו \u0003גופא\u0004 \u0005[\u0006ל\u0005גופה]:\u0006 \u0003מצא בה תינוק מושלך, אם רוב\u0004 אנשי העיר \u0003גויים\u0004 — הרי הוא \u0003גוי, אם רוב ישראל — ישראל, מחצה על מחצה\u0004 — הריהו כ\u0003ישראל.\u0004 ו\u0003אמר רב: לא שנו\u0004 שהריהו כישראל \u0003אלא\u0004 כשיש צורך \u0003להחיותו\u0004 ולפרנסו, \u0003אבל ל\u0004ענין \u0003יוחסין — לא. ושמואל אמר:\u0004 שהדבר נאמר לענין \u0003לפקח עליו את הגל\u0004 בשבת.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יוסף אמר רב יהודה אמר שמואל: אין הולכין בפיקוח נפש אחר הרוב,\u0004 אלא אפילו אם יש מקום כלשהו להניח שהאיש המצוי בסכנה הוא ישראל, עושים כל מה שצריך כדי להצילו אפילו בשבת! \u0003אלא כי איתמר\u0004 \u0005[כאשר נאמרו\u0006 דבריו\u0005]\u0006 של \u0003שמואל\u0004 בענין פיקוח נפש — \u0003ארישא אתמר\u0004 \u0005[על תחילתה\u0006 של המשנה \u0005נאמרו].\u0006 וכך יש להבין, שנינו: \u0003אם רוב גויים\u0004 — הרי הילד כ\u0003גוי, אמר שמואל: ולפקח עליו את הגל אינו כן,\u0004 שאפילו אם רוב גויים בעיר, מכל מקום במקום ספק נפשות אין הולכים אחר הרוב. שנינו שם ש\u0003אם רוב גויים — הריהו גוי,\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 בנוגע לאיזו \u0005הלכה]\u0006 נאמר הדבר? \u0003אמר רב פפא:\u0004 לענין שמותר אפילו \u0003להאכילו נבילות,\u0004 לפי שמחשיבים אותו כגוי לכל דבר.","","\u0003אם רוב ישראל ישראל למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]?\u0006 \u0003אמר רב פפא: להחזיר לו אבידה,\u0004 שאנחנו מניחים שהוא ישראל וצריך לנהוג בו כבישראל, אפילו להחזיר לו אבידה.","עוד שנינו: אם \u0003מחצה על מחצה\u0004 — הריהו כ\u0003ישראל. למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]?\u0006 \u0003אמר ריש לקיש: לנזקין,\u0004 שדנים אותו בדיני נזיקין כאילו היה ישראל. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי נימא דנגחיה תורא דידן לתורא דידיה\u0004 \u0005[אם נאמר שנגח שור שלנו,\u0006 של אחד שהוא ודאי ישראל, \u0005את השור שלו,\u0006 של הספק\u0005]\u0006 ובא אותו ספק, ותובע שידונו בו כבדיני ישראל וישלמו לו — \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 הנתבע: \u0003אייתי ראיה\u0004 \u0005[הבא]\u0006 ש\u0003ישראל את\u0004 \u0005[אתה]\u0006 \u0003ושקול\u0004 \u0005[וקח],\u0006 והרי אינו יכול להביא ראיה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא לאופן \u0003דנגחיה תורא דידיה לתורא דידן\u0004 \u0005[שנגח שור שלו לשור שלנו],\u0006 של אדם מישראל, שבמקרה כזה \u0003פלגא\u0004 \u0005[חצי]\u0006 הוא ודאי \u0003משלם,\u0004 כדין שור תם שנגח, שבדיני ישראל משלם רק חצי נזק. \u0003ואידך פלגא\u0004 \u0005[ו\u0006לגבי \u0005החצי האחר]\u0006 שרוצים לחייבו גם ביתרת הנזק, כדין שור תם של גוי שהזיק לישראל שחייב בנזק שלם — על כך \u0003אמר להו\u0004 \u0005[אומר להם]\u0006 לתובעים: \u0003אייתי\u0004 \u0005[הביאו]\u0006 לי \u0003ראיה דלאו\u0004 \u0005[שלא]\u0006 \u0003ישראל אנא\u0004 \u0005[אני]\u0006 \u0003ואתן לכון\u0004 \u0005[לכם]\u0006 את יתרת סכום הנזק, ולענין זה יש לו חזקת ישראל, שהם הצריכים להביא ראיה להוציא אותו מחזקה זו.","","\u0003האשה שנתארמלה\u0004 \u0005[נתאלמנה],\u0006 \u0003או שנתגרשה\u0004 ועכשיו היא תובעת את כתובתה, והכתובה אינה מצויה לפניהם, \u0003היא אומרת: בתולה נשאתני,\u0004 ולכן מגיע לי מאתים זוז, \u0003והוא אומר: לא כי, אלא אלמנה נשאתיך,\u0004 ומגיע לך רק מנה אחד, מאה זוז. \u0003אם יש עדים שיצאת בהינומא\u0004 (כפי שמפרשת הגמרא להלן — אופן יציאתן של כלות בתולות בלכתן לחופה) \u0003וראשה פרוע\u0004 (גם זה אופן שבו היו כלות בתולות מופיעות בחתונתן) — הרי זו ראיה לדבריה ו\u0003כתובתה מאתים\u0004 כבתולה. \u0003ר' יוחנן בן ברוקה אומר: אף חילוק קליות\u0004 (חיטים קלויות) בחתונה הרי זו \u0003ראיה\u0004 לכך שנישאה בתולה, שבחתונה של בתולה היו מחלקים לאורחים קליות (חיטים קלויות). כיון שהוזכרו כמה מחלוקות של רבן גמליאל ור' יהושע בשאלה עד כמה סומכים אנו על טענתו של צד אחד, מוסיפים: \u0003ומודה ר' יהושע באומר לחבירו: שדה זו\u0004 שאני מחזיק בה \u0003של אביך היתה\u0004 מתחילה, \u0003ולקחתיה\u0004 (קניתי אותה, את השדה) \u0003הימנו\u0004 \u0005[ממנו]\u0006 \u0003שהוא נאמן,\u0004 ואין אומרים שההודאה שהשדה היתה של האב — מתקבלת, אבל טענתו שקנה את השדה אינה מתקבלת.",""],["\u0003שהפה שאסר,\u0004 הוא עצמו שהודה שהשדה לא היתה שלו מתחילה — \u0003הוא הפה שהתיר,\u0004 שטוען שקנה את השדה, ושלו הוא. \u0003ואם יש עדים שהיא,\u0004 השדה, היתה \u0003של אביו, והוא\u0004 המחזיק בשדה \u0003אומר: \"לקחתיה הימנו\" — אינו נאמן\u0004 באמירה זו בלבד.","לענין ההלכה הראשונה, שהאשה טוענת שהיתה בתולה כשנישאה והוא אומר שהיתה אלמנה, מעירים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדים\u0004 שיצאה בהינומה, \u0003הא ליכא\u0004 \u0005[הרי\u0006 כש\u0005אין]\u0006 \u0003עדים — בעל מהימן\u0004 (נאמן), אם כן \u0003לימא תנן סתמא\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005שנינו סתם\u0006 משנה\u0005]\u0006 ש\u0003לא כ\u0004שיטת \u0003רבן גמליאל? דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003רבן גמליאל, הא\u0004 \u0005[הרי]\u0006 הוא \u0003אמר\u0004 כי \u0003איהי מהימנא\u0004 \u0005[היא נאמנת]\u0006 בטענה כגון זו (וכגון במקרה שהיא אומרת \"משארסתני נאנסתי\" והוא אומר \"לא כי עד שלא ארסתיך נאנסת\")!","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבן גמליאל,\u0004 ואולם \u0003עד כאן לא קאמר\u0004 \u0005[אמר]\u0006 \u0003רבן גמליאל התם\u0004 \u0005[שם]\u0006 \u0003אלא ב\u0004מקרה שטענות האיש והאשה הן טענות \u0003ברי\u0004 (ודאי) \u0003ושמא\u0004 (ספק). שהרי האשה טוענת טענת ברי שנאנסה משנתארסה לו, ובטוחה היא במה שהיא אומרת. והבעל טוען כנגדה טענת שמא, שהרי אינו יודע בודאות מה אירע בה, אלא שמביע חשש שמא נאנסה טרם אירוסיה לו. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 שיש כאן טענות \u0003בברי וברי,\u0004 שהרי הוא אומר בודאות שנשא אותה כשהיא אלמנה — \u0003לא אמר\u0004 רבן גמליאל ואף לדבריו אינה נאמנת.","מכיון שתירוץ זה פשוט ומשכנע כל כך, שואלים: \u0003ודקארי לה מאי קארי לה\u0004 \u0005[ו\u0006זה \u0005שהקשה אותה\u0006 קושיה מתחילה \u0005מה הקשה אותה],\u0006 ואיך השוה את הדברים? \u0003הא\u0004 \u0005[הרי]\u0006 כאן טענת \u0003ברי וברי הוא!\u0004 ומשיבים: היתה סברה בדבר, \u0003כיון\u0004 ש\u0003רוב\u0004 ה\u0003נשים\u0004 כשהן \u0003בתולות\u0004 הן \u0003נישאות,\u0004 היינו יכולים לומר \u0003כי\u0004 \u0005[כמו]\u0006 \u0003ברי ושמא דמי\u0004 \u0005[נחשב]\u0006 הדבר שהרי הרוב מסייע לטענתה.","\u0003ו\u0004מעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר שהמשנה גם לשיטת רבן גמליאל, ואף הוא מודה שהבעל הוא שנאמן, למרות שיש בסיס (של רוב) לטענת האשה, והרי זה דומה לטענת ברי ושמא. ומדוע? \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 בהמשך המשנה: \u0003\"ומודה ר' יהושע\", אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 \u0003איירי\u0004 \u0005[עוסק]\u0006 \u0003רבן גמליאל במודה,\u0004 כלומר, שבדין הראשון, בטענת ברי וברי, מודה רבן גמליאל לר' יהושע שהבעל הוא שנאמן, אף שבברי ושמא חולק הוא עליו \u0003— שפיר\u0004 \u0005[יפה],\u0006 ומובן מדוע במקביל לכך מובא המשך מענין אחר שבו מודה ר' יהושע לרבן גמליאל. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003לא איירי\u0004 \u0005[עוסק]\u0006 \u0003רבן גמליאל\u0004 ברישא \u0003במודה,\u0004 ומשנה זו אינה כדעתו — אם כן \u0003ר' יהושע למאן\u0004 \u0005[למי\u0006 הוא\u0005]\u0006 \u0003מודה\u0004 בסיפא? הרי אין כאן כל התייחסות לנושא שנחלקו בו!","ודוחים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003ר' יהושע אהאי פירקין קאי\u0004 \u0005[על פרקנו זה\u0006 הוא \u0005עומד,\u0006 מתייחס\u0005]?\u0006 — אין הדבר כן, אלא על ענין \u0003מגו קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 מתייחס\u0005]\u0006 \u0003ואפירקין קמא קאי\u0004 \u0005[ועל פרקנו הראשון\u0006 הוא \u0005עומד,\u0006 מתייחס\u0005],\u0006 שאפשר לומר שהנאמנות של \"הפה שאסר הוא הפה שהתיר\" היא מעין מיגו, שכיון שהיה יכול לטעון שהשדה היתה שלו מתחילה, ואז לא היה מקום להתדיינות כלל, והוא במקום זה אמר שקנה את השדה — הריהו נאמן, שמוכח שאינו רוצה לשקר.","ושואלים: \u0003אהייא\u0004 \u0005[על איזו]\u0006 מן ההלכות שבפרק הראשון מתייחסים דברי ר' יהושע? \u0003אילימא אהא\u0004 \u0005[אם תאמר על זאת]\u0006 שנחלקו באשה ש\u0003היתה מעוברת ואמרו לה: \"מה טיבו של עובר זה?\"\u0004 ואמרה: \u0003\"מאיש פלוני וכהן הוא\",\u0004 ש\u0003רבן גמליאל ור' אליעזר אומרים: נאמנת,\u0004 ו\u0003ר' יהושע אומר: לא מפיה אנו חיין,\u0004 ואינה נאמנת — אולם \u0003התם\u0004 \u0005[שם]\u0006 לדעת ר' יהושע \u0003מאי\u0004 \u0005[מה],\u0006 איזה \u0003מגו איכא\u0004 \u0005[יש]\u0006 להאמינה? \u0003הרי\u0004 רואים כי \u0003כריסה בין שיניה\u0004 ובודאי אינה יכולה לטעון שלא נבעלה (אף שהיא טענה טובה יותר), והרי זה כטענת מיגו נגד עדות עדים שאין בטענה זו כלום.","\u0003אלא אהא\u0004 \u0005[על זו]\u0006 ששנינו שם: \u0003ראוה מדברת עם אחד, ואמרו לה: \"מה טיבו של איש זה?\"\u0004ואמרה להם: \u0003\"איש פלוני וכהן הוא\"\u0004 ש\u0003רבן גמליאל ור' אליעזר אומרים: נאמנת,\u0004 ו\u0003ר' יהושע אומר: לא מפיה אנו חיין.\u0004 ויש לשאול: \u0003התם מאי\u0004 \u0005[שם, מה\u0006 איזה\u0005]\u0006 \u0003מגו איכא\u0004 \u0005[יש]?\u0006 \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003זעירי\u0004 ש\u0003אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מדברת\" — נסתרה,\u0004 ולכן אפשר לומר כך: \u0003מגו דאי בעיא אמרה\u0004 \u0005[מתוך שאם היתה רוצה\u0006 לשקר \u0005היתה אומרת]:\u0006 \u0003\"לא נבעלתי\u0004 כלל \u0003\", וקאמרה\u0004 \u0005[ו\u0006היא \u0005אומרת]:\u0006 \u0003\"נבעלתי\u0004 לכשר \u0003\"\u0004— לכן \u0003מהימנא\u0004 \u0005[נאמנת]\u0006 לדעת רבן גמליאל. \u0003אלא לרב אסי,\u0004 ש\u0003אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מדברת\" — נבעלת,\u0004 אם כן \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מגו איכא\u0004 \u0005[יש\u0006 פה\u0005]?\u0006 הלא אין לה טענה טובה יותר!","\u0003ואלא\u0004 יש לומר שמתייחסים הדברים \u0003אהא\u0004 \u0005[על זו]\u0006 ששנינו בפרק ראשון: \u0003היא אומרת: \"\u0004אכן איני בתולה, אלא שלא נבעלתי לאיש וזה שלא נמצאו לי בתולים, משום ש\u0003מוכת עץ אני\", והוא אומר: \"לא כי, אלא דרוסת איש את\u0004 (שנבעלת לאיש) \u0003\". רבן גמליאל ור' אליעזר אומרים: נאמנת, ור' יהושע אומר: לא מפיה אנו חיין\u0004 — גם כאן יש לשאול: \u0003התם מאי\u0004 \u0005[שם מה,\u0006 איזה\u0005]\u0006 \u0003מגו איכא\u0004 \u0005[יש]?\u0006","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' אלעזר\u0004 ש\u0003אמר\u0004 שהם מתדיינים \u0003במנה ולא כלום,\u0004 שהיא תובעת מנה בכתובתה והוא איננו רוצה לתת לה ולא כלום, ניתן לומר כך: \u0003מגו דאי בעיא אמרה\u0004 \u0005[מתוך שאם היתה רוצה\u0006 לשקר \u0005היתה אומרת]:\u0006 \u0003\"מוכת עץ אני תחתיך\",\u0004 שאירע הדבר לאחר שנתארסה לו, \u0003ואית\u0004 \u0005[ויש]\u0006 \u0003לה מאתים,\u0004 שהרי בזמן הקידושין היתה בתולה, \u0003וקאמרה\u0004 \u0005[והיא אומרת]\u0006 עכשיו שהיתה מוכת עץ \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 לפני שהתארסה, \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003לה אלא מנה,\u0004 על כן \u0003מהימנא\u0004 \u0005[נאמנת]\u0006 במיגו. \u0003אלא ל\u0004שיטת \u0003ר' יוחנן\u0004 ש\u0003אמר: במאתים ומנה\u0004 הם מתדיינים, שהיא תובעת מאתים ולטענתו לא מגיע לה כי אם מנה. אם כן \u0003מאי מגו איכא\u0004 \u0005[מה,\u0006 איזה \u0005\"מתוך\" יש\u0006 בכך\u0005]?\u0006 הלא היא טוענת גם עכשיו את הטענה הטובה ביותר שיש בידה!","\u0003אלא אהא\u0004 \u0005[על זו]\u0006 אנו מתייחסים, ששנינו: \u0003הנושא את האשה ולא מצא לה בתולים, היא אומרת: \"משארסתני נאנסתי, ונסתחפה שדהו\",\u0004 כלומר, ההפסד הוא שלך, כי ברשותך אירע לי הדבר, והרי זה כאילו שטפון סחף את שדך, \u0003והוא אומר: \"לא כי, אלא עד שלא אירסתיך\u0004 נאנסת\u0003\",\u0004","\u0003רבן גמליאל ור' אליעזר אומרים: נאמנת, ור' יהושע אומר: לא מפיה אנו חיין. דמגו דאי בעיא אמרה\u0004 \u0005[שמתוך שאם היתה רוצה\u0006 לשקר \u0005היתה אומרת]\u0006 \u0003\"מוכת עץ אני תחתיך\",\u0004 שהיא טענה טובה יותר, \u0003דלא קא פסלה נפשה\u0004 \u0005[שאינה פוסלת\u0006 את \u0005עצמה]\u0006 \u0003מכהונה\u0004 שאם היא מוכת עץ כשירה לכל, אף לכהן. \u0003וקאמרה\u0004 \u0005[ו\u0006היא עכשיו \u0005אומרת]:\u0006 \u0003\"נאנסתי\u0004 בהיותי ארוסה \u0003\", דקא פסלה נפשה\u0004 \u0005[שפוסלת\u0006 את \u0005עצמה]\u0006 \u0003מכהונה\u0004 כי אשת איש שנבעלה, אפילו באונס, אסורה לכהן, \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבן גמליאל דמהימנא\u0004 \u0005[שנאמנת].\u0006 \u0003וקאמר\u0004 \u0005[ואומר]\u0006 \u0003ר' יהושע לרבן גמליאל\u0004 במשנתנו: \u0003בהאי מגו דהכא, מודינא לך\u0004 \u0005[במיגו זה של כאן,\u0006 באומר לחבירו \"שדה זו של אביך\", \u0005מודה אני לך]\u0006 שהוא נאמן, ואולם \u0003בההוא מגו דהתם, פליגנא עילווך\u0004 \u0005[באותו מיגו של שם, חולק אני עליך].\u0006","ושואלים: \u0003מכדי האי\u0004 \u0005[הרי זה]\u0006 \u0003מגו והאי\u0004 \u0005[וזה]\u0006 \u0003מגו, מאי שנא האי מגו מהאי מגו\u0004 \u0005[מה שונה מיגו זה ממיגו זה]?\u0006 ומשיבים: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003אין שור שחוט לפניך,\u0004 כלומר, כאן אין לנו עובדות המוכיחות לכאורה טענה הפוכה, כי בפועל השדה נמצא ביד המחזיק אותו. אבל \u0003התם\u0004 \u0005[שם]\u0006 באשה שלא מצא לה בתולים — \u0003הרי שור שחוט לפניך,\u0004 שהרי היא בעולה, וכיון שהעובדות מוכיחות כנגדה — סבור ר' יהושע שאין תוקף למיגו שלה.","ושוב חוזרים לבעיה שהתחלנו בה ופירשנו שכאן יש בסיס של רוב לטענת האשה. \u0003ו\u0004שואלים: \u0003כיון\u0004 ש\u0003רוב\u0004 ה\u0003נשים\u0004 כשהן \u0003בתולות\u0004 הן \u0003נישאות,\u0004 אם כן, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא אתו\u0004 \u0005[באים]\u0006 \u0003עדים מאי הוי\u0004 \u0005[מה יש\u0006 בכך\u0005],\u0006 מדוע לא נסמוך על הרוב, ויצטרך הוא להביא ראיה! \u0003אמר רבינא: משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 אמנם \u0003רוב נשים בתולות נישאות, ומיעוט\u0004 נשים נישאות כשהן \u0003אלמנות\u0004 או גרושות, \u0003ו\u0004אולם יש גם חזקה אחרת: \u0003כל הנשאת בתולה יש לה קול,\u0004 שהדבר מפורסם ברבים, שכן יש בחופת בתולה סימנים מיוחדים, שהיא יוצאת לחופה בהינומא וראשה פרוע,"],["\u0003וזו, הואיל ואין לה קול,\u0004 שאין עדים המעידים שנישאה בתולה — \u0003איתרע לה רובא\u0004 \u0005[נשבר לה,\u0006 נהרס, כוחו של \u0005הרוב].\u0006","ותוהים: \u0003אי\u0004 \u0005[אם]\u0006 אומר אתה ככלל ש\u0003כל הנשאת\u0004 כשהיא \u0003בתולה יש לה קול — כי אתו\u0004 \u0005[כאשר באים]\u0006 \u0003עדים\u0004 המעידים על כך שנישאה בתולה, ומאידך לא יצא קול המאשר עובדה זו, \u0003מאי הוי\u0004 \u0005[מה יש]?\u0006 \u0003הנך סהדי שקרי נינהו\u0004 \u0005[אלה, עדי שקר הם],\u0006 שהרי הם עומדים כנגד חזקה! \u0003אלא אמר רבינא,\u0004 כך יש לומר: לא כל, אלא \u0003רוב הנשאת בתולה יש לה קול, וזו הואיל ואין לה קול איתרע לה רובא\u0004 \u0005[נשבר לה הרוב]\u0006 ועדים המעידים שיצאה בהינומה, שהוא סימן המעיד על כך שהיא בתולה, עדיפים מרוב זה.","שנינו במשנה ש\u0003אם יש עדים שיצתה\u0004 לחופה \u0003בהינומא\u0004 וראשה פרוע — כתובתה מאתים. ושואלים: \u0003וליחוש דלמא מפקא\u0004 \u0005[ונחשוש שמא מוציאה,\u0006 מביאה\u0005]\u0006 היא \u0003עדים\u0004 שראוה הולכת לחופה בהינומה וראשה פרוע, \u0003בהאי בי דינא\u0004 \u0005[בבית דין זה],\u0006 \u0003וגביא\u0004 \u0005[וגובה]\u0006 על פי העדים את סכום כתובתה, \u0003והדר מפקא לה לכתובה בהאי בי דינא\u0004 \u0005[וחוזרת\u0006 ושוב \u0005מוציאה את הכתובה\u0006 עצמה \u0005בבית דין זה,\u0006 אחר\u0005]\u0006, \u0003וגביא\u0004 \u0005[וגובה]\u0006 \u0003בה\u0004 על ידה פעם שניה? שהרי כאן מדובר כשלא היתה כתובה בידה כשבאה לגבות ולכן הביאה עדים, ויש לחשוש שמא החביאה את הכתובה, ותגבה פעמיים! \u0003אמר ר' אבהו: זאת אומרת\u0004 ש\u0003כותבין שובר.\u0004 שכאשר האשה מקבלת את סכום הכתובה היא כותבת לו שובר (קבלה), שקיבלה את הסכום הזה. ואם תבוא לתובעו שנית — יוציא הבעל את השובר. \u0003רב פפא אמר:\u0004 אין כותבים שובר, ואולם כאן \u0003במקום שאין כותבין כתובה\u0004 אלא סומכים על תנאי בית דין הקובע לבתולה מאתים ולאלמנה מנה \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ומשום כך אין לחשוש שתוציא את כתובתה.","\u0003ואיכא דמתני לה אברייתא\u0004 \u0005[ויש ששונים אותה,\u0006 את המחלוקת שבין ר' אבהו לרב פפא, \u0005על ברייתא].\u0006 ששנינו: \u0003איבדה\u0004 אשה את \u0003כתובתה,\u0004 או \u0003הטמינה\u0004 (החביאה) את \u0003כתובתה\u0004 ואומרת שאינה זוכרת היכן היא, או ש\u0003נשרפה כתובתה\u0004 ואין הוכחה ביחס לגובה סכום הכתובה המגיע לה, אם \u0003רקדו לפניה\u0004 בשעת החתונה, או \u0003שחקו לפניה,\u0004 או \u0003העבירו לפניה כוס של בשורה, או מפה של בתולים,\u0004 שכל אלה היו מנהגים שהיו נהוגים רק בחתונה של בתולה, \u0003אם יש לה עדים באחד מכל\u0004 המעשים ה\u0003אלו\u0004 שנעשו בנישואיה — \u0003כתובתה מאתים.\u0004","ושאלו: \u0003וליחוש דלמא מפקא\u0004 \u0005[ונחשוש שמא מוציאה,\u0006 מביאה\u0005]\u0006 היא \u0003עדים\u0004 המעידים על סימנים אלה \u0003בהאי בי דינא\u0004 \u0005[בבית דין זה]\u0006 \u0003וגביא\u0004 \u0005[וגובה]\u0006 כתובה מאתים, \u0003והדר מפקא לכתובתה בהאי בי דינא\u0004 \u0005[ותחזור\u0006 ו\u0005תוציא את כתובתה,\u0006 שהחביאה אותה, \u0005בבית דין זה,\u0006 אחר\u0005]\u0006 \u0003וגביא\u0004 \u0005[ותגבה]\u0006 \u0003בה\u0004 פעם שניה! על כך \u0003אמר ר' אבהו: זאת אומרת כותבין שובר. רב פפא אמר:\u0004 אין כותבים שובר, ואולם כאן \u0003במקום שאין כותבין כתובה עסקינן\u0004 \u0005[עוסקים אנו].\u0006","ושואלים על דברי רב פפא: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"איבדה כתובתה\" קתני\u0004 \u0005[שנה]\u0006 בברייתא, משמע שמדובר כאן במקום שכותבים כתובה! ומשיבים: צריך לומר ש\u0003כתב לה איהו\u0004 \u0005[הוא]\u0006 כתובה שלא כמנהג הרגיל באותו מקום. ומקשים: כיון שמדובר כאן שכתב לה כתובה, \u0003סוף סוף\u0004 יש לחשוש שמא \u0003מפקא לה\u0004 \u0005[מוציאה אותה]\u0006 \u0003וגביא\u0004 \u0005[וגובה]\u0006 \u0003בה!\u0004 ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"איבדה\"\u0004 ששנינו — \u0003איבדה באור\u0004 (באש), כלומר, אבידה של כליון, וכגון שהיו עדים שראו שנשרפה הכתובה, כך שאין לחשוש יותר.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 ששנינו בהמשך: \u0003\"נשרפה\",\u0004 ויש כאן איפוא כפל דברים? \u0003ועוד:\u0004 מה ששנינו בין השאר גם \u0003הטמינה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי כאן בודאי יש מקום לחשוש! \u0003ותו\u0004 \u0005[ועוד]:\u0006 המקרה ששנינו ש\u0003איבדה\u0004 כתובתה \u0003למה לי\u0004 לשנותו? שלפי פירוש זה אין בכך כל חידוש בהלכה! \u0003אלא,\u0004 כך צריך לומר שהמקרים המפורטים בברייתא זו מבארים זה את זה, ובצורה זו: \u0003כל\u0004 טענה של אשה ש\u0003איבדה\u0004 כתובתה — \u0003כי\u0004 \u0005[כמו]\u0006 ש\u0003הטמינה בפנינו דמי\u0004 \u0005[נחשבת],\u0006 \u0003ולא יהבינן\u0004 \u0005[ואין אנו נותנים]\u0006 \u0003לה\u0004 את דמי הכתובה, אפילו תביא עדים שרקדו לפניה, שחוששים אנו שמא תוציא לאחר מכן את כתובתה בבית דין אחר, \u0003עד דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003עדים\u0004 ש\u0003נשרפה כתובתה.\u0004","ומעירים: \u0003מאן דמתני לה\u0004 \u0005[מי ששונה אותה],\u0006 את מחלוקת אמוראים זו על ה\u0003ברייתא — כל שכן\u0004 ששונה אותה \u0003אמתניתין\u0004 \u0005[על משנתנו],\u0006 כי דברי רב פפא מבארים יפה את המשנה. \u0003ומאן דמתני לה אמתניתין\u0004 \u0005[ומי ששונה אותה על משנתנו] —\u0006 \u0003אבל\u0004 על ה\u0003ברייתא לא\u0004 שנה את דברי רב פפא, \u0003כי קושיא\u0004 \u0005[כמו הקושיה]\u0006 שהזכרנו למעלה, שיש קושיה מלשון הברייתא על דברי רב פפא האומר שמדובר פה במקום שלא נוהגים לכתוב כתובה, ואי אפשר לתרץ קושיה זו אלא בדוחק.","שנינו במשנה: \u0003אם יש עדים\u0004 שיצאה בהינומא — גובה כתובה מאתים. ושואלים: \u0003וליחוש דלמא מפקא\u0004 \u0005[ונחשוש שמא מוציאה,\u0006 מביאה\u0005]\u0006 היא את \u0003עדי הינומא\u0004 שיעידו לטובתה \u0003בהאי בי דינא\u0004 \u0005[בבית דין זה]\u0006 \u0003וגביא\u0004 \u0005[וגובה]\u0006 כתובה מאתים, \u0003והדר מפקא\u0004 \u0005[וחוזרת ומוציאה]\u0006 בשנית את \u0003עדי הינומא בבי דינא אחרינא\u0004 \u0005[בבית דין אחר]\u0006 \u0003וגביא\u0004 \u0005[וגובה]\u0006 שוב. שהרי היא גובה על פי העדים, ויכולה להביא עדים כאלה כמה פעמים! ומשיבים: \u0003במקום\u0004 ש\u0003לא אפשר\u0004 באופן אחר \u0003ודאי כתבינן\u0004 \u0005[כותבים אנו]\u0006 \u0003שובר,\u0004 אפילו לדעת מי שסובר שבדרך כלל אין כותבים שובר.","באותה ברייתא שנינו: \u0003העבירו לפניה כוס של בשורה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003\"כוס של בשורה\"\u0004 זו? \u0003אמר רב אדא בר אהבה: כוס יין של תרומה מעבירין לפניה,\u0004 לפני הכלה הבתולה. \u0003כלומר: ראויה היתה זו לאכול בתרומה\u0004 אם נישאת לכהן. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על טעם זה \u0003רב פפא: אטו\u0004 \u0005[וכי]\u0006 \u0003אלמנה מי לא אכלה\u0004 \u0005[אינה אוכלת]\u0006 \u0003בתרומה\u0004 כשנישאת פעם שניה לכהן הדיוט, ואם כן מה ראיה היא מענין התרומה שבתולה היא? \u0003אלא אמר רב פפא:\u0004 מעבירים כוס זו, לא כדי לרמוז שהיא ראויה לתרומה, אלא לומר: כלה \u0003זו\u0004 בבחינת \u0003ראשית,\u0004 שעדיין לא נבעלה, \u0003כ\u0004פי ש\u0003תרומה\u0004 היא \u0003ראשית\u0004 ההפרשה מן התבואה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 המנהג הוא ש\u0003חבית של יין מעבירין לפניה. אמר רב אדא בר אהבה:\u0004 אם היתה בנישואיה \u0003בתולה\u0004 — \u0003מעבירין לפניה\u0004 חבית \u0003סתומה\u0004 של יין, ואם היתה \u0003בעולה\u0004 — \u0003מעבירין לפניה\u0004 חבית \u0003פתוחה.\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 נעשה כן? \u0003ניעבר קמי\u0004 \u0005[נעביר\u0006 את החבית הסתומה רק \u0005לפני]\u0006 \u0003בתולה וקמי\u0004 \u0005[ולפני]\u0006 \u0003בעולה לא ניעבר\u0004 \u0005[נעביר]\u0006 חבית \u0003כלל!\u0004 ומדוע מפרסמים ברבים שהיא בעולה? ומסבירים: יש צורך בדבר, כי \u0003זימנין דתפסה\u0004 \u0005[פעמים שתופסת]\u0006 הבעולה \u0003מאתים\u0004 לכתובתה, \u0003ואמרה\u0004 \u0005[ואומרת]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003בתולה הואי\u0004 \u0005[הייתי],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא עברו קמאי\u0004 \u0005[העבירו לפני]\u0006 את החבית הזו — \u0003אתנוסי הוא דאתניסו\u0004 \u0005[\u0006משום \u0005שנאנסו]\u0006 מאיזושהי סיבה ולא יכלו לעשות זאת. ולכן מעבירים לפניה חבית פתוחה, כדי שיזכרו אנשים שלא היתה בתולה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד מרקדין לפני הכלה,\u0004 מה אומרים לפניה בזמן הריקוד? \u0003בית שמאי אומרים:\u0004"],["\u0003כלה כמות שהיא.\u0004 כלומר, משבחים את הכלה לפי מעלותיה. \u0003ובית הלל אומרים:\u0004 לכבודה של כל כלה שרים: \u0003\"כלה נאה וחסודה\". אמרו להן בית שמאי לבית הלל: הרי שהיתה\u0004 הכלה \u0003חיגרת או סומא\u0004 (עוורת), \u0003אומרים לה: \"כלה נאה וחסודה\"? ו\u0004הרי \u0003התורה אמרה: \"מדבר שקר תרחק\"\u0004 (שמות כג, ז)! \u0003אמרו להם בית הלל לבית שמאי: לדבריכם, מי שלקח\u0004 (קנה) \u0003מקח רע מן השוק,\u0004 האם אדם אחר הרואה אותו לאחר שקנה \u0003ישבחנו בעיניו או יגננו בעיניו? הוי אומר — ישבחנו בעיניו\u0004 ולא יגרום לו עוגמת נפש. \u0003מכאן אמרו חכמים: לעולם תהא דעתו של אדם מעורבת עם הבריות,\u0004 וינהג עמם בנימוס. ואף כאן, כיון שבחר בכלה זו, משבחים אותה שהיא נאה וחסודה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: הכי משרו קמי כלתא במערבא\u0004 \u0005[כך שרים לפני הכלות בארץ ישראל]:\u0006 \u0003\"לא כחל\u0004 (צבע לעינים) \u0003ולא שרק\u0004 (צבע לפנים) \u0003ולא פירכוס\u0004 (קליעת שיער) \u0003ו\u0004בכל זאת \u0003יעלת חן\".\u0004 ומספרים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003סמכו רבנן\u0004 \u0005[חכמים]\u0006 \u0003לר' זירא\u0004 ומינוהו בתואר \"רבי\", \u0003שרו ליה הכי\u0004 \u0005[לו כך],\u0006 כפי ששרים לכלה: \u0003\"לא כחל ולא שרק ולא פירכוס ויעלת חן\".\u0004","אגב כך מספרים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003סמכו רבנן\u0004 \u0005[חכמים]\u0006 את \u0003ר' אמי ולר' אסי שרו להו הכי\u0004 \u0005[להם כך]:\u0006 \u0003\"כל מן דין וכל מן דין סמוכו לנא\u0004 \u0005[הכל\u0006 כמו \u0005מזה והכל\u0006 כמו \u0005מזה סמכו לנו],\u0006 \u0003לא\u0004 \u0005[אל]\u0006 \u0003תסמכו לנא\u0004 \u0005[לנו]\u0006 \u0003לא מן סרמיסין ולא מן סרמיטין\u0004 (אנשים חסרי ערך וריקנים)\u0003\". ואמרי לה\u0004 \u0005[ויש אומרים\u0006 שאמרו\u0005]:\u0006 \u0003\"לא מן חמיסין ולא מן טורמיסין\".\u0004","ועוד בענין שירות של שבח, מסופר: \u0003ר' אבהו כי הוה אתי ממתיבתא לבי\u0004 \u0005[כאשר היה בא מהישיבה לבית]\u0006 ה\u0003קיסר, נפקן אמהתא דבי\u0004 \u0005[\u0006היו \u0005יוצאות השפחות של בית]\u0006 ה\u0003קיסר לאפיה\u0004 \u0005[לפניו]\u0006 \u0003ומשרין ליה הכי\u0004 \u0005[ו\u0006היו \u0005שרות לו כך]:\u0006 \u0003\"רבא דעמיה ומדברנא דאומתיה, בוצינא דנהורא, בריך מתייך לשלם\u0004 \u0005[גדול עמו ומנהיג אומתו, נר המאיר, ברוך בואך לשלום]\u0006\u0003\".\u0004","ושוב לענין המצוה לשמח חתן וכלה: \u0003אמרו עליו על ר' יהודה בר אילעאי שהיה נוטל בד\u0004 (ענף) \u0003של הדס, ומרקד לפני הכלה, ואומר: \"כלה נאה וחסודה\".\u0004 מספרים: \u0003רב שמואל בר רב יצחק\u0004 היה \u0003מרקד אתלת\u0004 \u0005[על שלושה\u0006 ענפים כאלה\u0005].\u0006 \u0003אמר ר' זירא: קא מכסיף לן סבא\u0004 \u0005[\u0006הרי \u0005מבייש אותנו הזקן],\u0006 שעל ידי ריקודים אלה הוא מזלזל בכבוד תורתו וגורם בושה לתלמידי חכמים. ומסופר: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 רב שמואל בר רב יצחק, \u0003איפסיק עמודא דנורא בין דידיה לכולי עלמא\u0004 \u0005[הפסיק,\u0006 חצץ, \u0005עמוד של אש בינו\u0006 ובין \u0005כל העולם],\u0006 \u0003וגמירי דלא אפסיק עמודא דנורא\u0004 \u0005[ו\u0006אנו \u0005למודים\u0006 במסורת \u0005שאין מפסיק עמוד אש\u0006 כזה\u0005]\u0006 \u0003אלא אי לחד בדרא, אי לתרי בדרא\u0004 \u0005[או לאחד בדור, או לשניים בדור].\u0006","\u0003אמר ר' זירא: אהנייה ליה שוטיתיה לסבא\u0004 \u0005[הועיל לו הבד שלו לזקן],\u0006 שבזכות מצוה זו שדקדק בה, זכה לשכר מרובה זה. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר בלשון אחרת קצת: שהועילה לו \u0003שטותיה לסבא\u0004 \u0005[שטותו לזקן],\u0006 שהתנהג כשוטה כשרקד לפני הכלה. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר: הועילה לו \u0003שיטתיה לסבא\u0004 \u0005[שיטתו,\u0006 מנהגו, \u0005לזקן].\u0006","ועוד מסופר: \u0003רב אחא\u0004 היה \u0003מרכיב לה\u0004 \u0005[אותה],\u0006 את הכלה \u0003אכתפיה\u0004 \u0005[על כתיפו]\u0006 \u0003ו\u0004היה \u0003מרקד\u0004 עימה. \u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]:\u0006 \u0003אנן\u0004 \u0005[אנחנו]\u0006 \u0003מהו למיעבד הכי\u0004 \u0005[שנעשה כך,\u0006 כמוך\u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי דמיין עלייכו ככשורא\u0004 \u0005[אם דומות\u0006 הן הכלות \u0005עליכם כקורה\u0006 בלבד\u0005]\u0006 שאין אתם מהרהרים אודותיה — \u0003לחיי\u0004 \u0005[בסדר],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — לא\u0004 תעשו כן.","ועוד בענין זה, \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מותר להסתכל בפני כלה כל שבעה\u0004 ימי המשתה של החתונה, \u0003כדי לחבבה על בעלה,\u0004 שיראה שהכל מסתכלים ביופיה. ומעירים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו],\u0006 כלומר, שאסור להסתכל באשת איש אפילו היא כלה.","ועוד בכבוד הכלה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעבירין את המת מלפני כלה,\u0004 שאם יש הלוויית המת ויש שיירה המלווה את הכלה — שיירת הלוויית המת ממתינה עד שתעבור שיירת הכלה. \u0003וזה וזה\u0004 ממתינות \u0003מלפני מלך ישראל. אמרו עליו על אגריפס המלך שעבר מלפני כלה,\u0004 למרות שלא היה חייב לעשות כן, \u0003ושבחוהו חכמים\u0004 על כך.","ושואלים: \u0003שבחוהו\u0004 — \u0003מכלל\u0004 הדברים אתה למד \u0003דשפיר עבד\u0004 \u0005[שיפה עשה]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב אשי: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003נשיא שמחל על כבודו — כבודו מחול,\u0004 ורשאי לעשות כן, אבל \u0003מלך שמחל על כבודו — אין כבודו מחול,\u0004 שאין הדבר תלוי בו. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 מה שאמר הכתוב \u0003\"שום תשים עליך מלך\"\u0004 (דברים יז, טו), כוונתו — \u0003שתהא אימתו עליך.\u0004 שמצוה מן התורה היא שיהא מורא של מלכות על הבריות, ואף המלך אינו רשאי למחול על כבודו! ומשיבים: \u0003פרשת דרכים הואי\u0004 \u0005[היתה],\u0006 והוא פנה לדרך אחרת, ולא היה ניכר שהוא מוחל על כבודו, ואין בכך מיעוט מורא של מלכות ומשום כך שיבחוהו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מבטלין\u0004 אפילו \u0003תלמוד תורה ל\u0004צורך \u0003הוצאת המת\u0004 לקבורה \u0003ולהכנסת כלה. אמרו עליו על ר' יהודה בר' אלעאי שהיה מבטל תלמוד תורה להוצאת המת ולהכנסת כלה. במה דברים אמורים\u0004 שעושים כן — \u0003כשאין עמו\u0004 עם המת או עם הכלה אנשים \u0003כל צרכו. אבל\u0004 אם \u0003יש עמו כל צרכו,\u0004 שיש לו מלווים כדי כבודו — \u0003אין מבטלין.\u0004","ושואלים: \u0003וכמה\u0004 הוא \u0003כל צרכו\u0004 של מת? \u0003אמר רב שמואל בר איני משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: תריסר אלפי גברי ושיתא אלפי שיפורי\u0004 \u0005[שנים עשר אלף אנשים ו\u0006עוד \u0005ששת אלפים\u0006 אנשים התוקעים ב\u0005שופרות]\u0006 כדי להודיע שיבואו ללוותו. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003תליסר אלפי גברי ומינייהו שיתא אלפי שיפורי\u0004 \u0005[שלושה עשר אלף איש ומהם ששת אלפים שופרות].\u0006 \u0003עולא אמר:\u0004 מהו כדי כבודו — \u0003כגון דחייצי גברי\u0004 \u0005[שחוצצים אנשים\u0006 של שיירת ההלוויה\u0005]\u0006 \u0003מאבולא\u0004 (שער העיר) \u0003ועד סיכרא\u0004 (מקום הקבר), מספר אנשים כזה צריכים ללוותו. \u0003רב ששת ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003ר' יוחנן אמר\u0004 זאת: \u0003נטילתה\u0004 של תורה, במותו של תלמיד חכם — \u0003כנתינתה, מה נתינתה\u0004 היתה \u0003בששים רבוא,\u0004 מספר בני ישראל במתן תורה — \u0003אף נטילתה\u0004 כשמלווים אותו, \u0003בששים רבוא.\u0004 ומעירים: \u0003והני מילי למאן דקרי ותני\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא ביחס \u0005למי שקרא\u0006 מקרא \u0005ושנה\u0006 משנה\u0005]\u0006 שהוא בן תורה, שצריך לכבדו כך,"],["\u0003אבל למאן דמתני, לית ליה שיעורא\u0004 \u0005[למי שמשנה,\u0006 מלמד אחרים, \u0005אין לו שיעור].\u0006 ומרבים במלווים ככל האפשר.","שנינו במשנה: \u0003ואם יש עדים שיצתה בהינומא\u0004 וראשה פרוע — כתובתה מאתים. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003הינומא\u0004 זאת? \u0003סורחב בר פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003זעירי אמר: תנורא דאסא\u0004 \u0005[חופה עגולה של הדסים]\u0006 ששמים לכלה על ראשה. \u0003ר' יוחנן אמר: קריתא דמנמנה בה כלתא\u0004 \u0005[צעיף\u0006 שמכסים בו את פני הכלה \u0005שבו הכלה\u0006 יכולה \u0005לנמנם],\u0006 משום שאין רואים את פניה, ו\"הינומה\" הוא מלשון תנומה.","שנינו במשנה ש\u0003ר' יוחנן בן ברוקא אומר\u0004 שאף חילוק קליות בחתונה הוא ראיה לכך שנישאה בתולה. מעירים: \u0003תנא\u0004 \u0005[שנה]\u0006 התנא במשנה \u0003ביהודה\u0004 מה היא ה\u0003ראיה,\u0004 כלומר, תיארו את המנהגים שהיו נוהגים בנישואי בתולה ביהודה, \u0003בבבל מאי\u0004 \u0005[מה]\u0006 המנהג? \u0003אמר רב: דרדוגי דמשחא ארישא דרבנן\u0004 \u0005[משיחת שמן\u0006 ריחני \u0005על ראשם של חכמים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: משחא דחפיפותא קאמר מר\u0004 \u0005[שמן של חפיפת\u0006 ראש \u0005אמר אדוני]?\u0006 שלא ידע בדיוק מהו מנהג זה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יתמא\u0004 \u0005[יתום],\u0006 כלומר, הרי אתה כיתום ומנותק ממנהג הנהוג במקומך, שאינך בקי במנהגים אלה, וכי \u0003לא עבדא\u0004 \u0005[עשתה]\u0006 \u0003לך אמך דרדוגי משחא ארישא דרבנן\u0004 \u0005[משיחת שמן על ראש חכמים]\u0006 \u0003בשעת מעשה\u0004 של חתונה? \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 \u0003דההוא מרבנן דאיעסק ליה לבריה\u0004 \u0005[שאחד החכמים שעסק לו\u0006 בנישואי \u0005בנו]\u0006 \u0003בי\u0004 \u0005[בבית]\u0006 \u0003רבה בר עולא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה להיפך, \u0003רבה בר עולא איעסק ליה לבריה\u0004 \u0005[היה עוסק\u0006 בחתונת \u0005בנו]\u0006 \u0003בי ההוא מרבנן\u0004 \u0005[בבית אחד החכמים],\u0006 \u0003ודרדיג משחא ארישא דרבנן\u0004 \u0005[ומשח שמן על ראשי חכמים]\u0006 \u0003בשעת מעשה.\u0004","ושואלים: \u0003ארמלתא מאי\u0004 \u0005[אלמנה מה]\u0006 סימנה? \u0003תאני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: ארמלתא לית לה כיסני\u0004 \u0005[\u0006בחתונת \u0005אלמנה אין\u0006 מחלקים \u0005קליות]\u0006 וזה סימנה.","שנינו במשנה: \u0003ומודה ר' יהושע באומר לחבירו:\u0004 \"שדה זו של אביך היתה ולקחתיה ממנו\", שהוא נאמן. ושואלים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003מודה ר' יהושע באומר לחבירו\u0004 עצמו: \u0003שדה זו שלך היתה ולקחתיה ממך?\u0004","ומסבירים: אמנם מודה ר' יהושע אף בזה, אלא \u0003משום דקא בעי למיתני סיפא\u0004 \u0005[שרצה לשנות\u0006 ב\u0005סוף]:\u0006 \u0003אם יש עדים שהיא שלו,\u0004 של האב, \u0003והוא אומר: \"לקחתיה ממנו\" — אינו נאמן,\u0004 ודבר זה יכול להיאמר רק לגבי שדה שהיתה שייכת לאב, ולא לשדה ששייכת לבעל הדבר עצמו. כי באם נניח שמדובר בשדה שלקח מחבירו, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006","\u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן שהמחזיק \u0003אכלה,\u0004 את פירות השדה, שלוש \u0003שני\u0004 \u0005[שנים]\u0006 כדי שתיחשב \u0003חזקה — אמאי לא מהימן\u0004 \u0005[מדוע אינו נאמן]\u0006 בטענתו זו שקנה אותה, הרי בכל מקרה לאחר שלוש שנים של חזקה די לקונה בטענה בלבד, ואינו צריך להביא שטר לראיה. \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר ש\u0003לא אכלה שני\u0004 \u0005[שנות]\u0006 \u0003חזקה — פשיטא דלא מהימן\u0004 \u0005[פשוט שאיננו נאמן].\u0006 וכיון שלא יכול להוסיף הלכה זו של עדים לגבי שדה של התובע עצמו — לא שנה כלל ענין זה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 ל\u0003גבי אביו נמי\u0004 \u0005[גם כן]\u0006 אפשר להקשות אותה קושיה עצמה: \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003אכלה\u0004 הקונה \u0003שני\u0004 \u0005[שנות]\u0006 \u0003חזקה\u0004 — \u0003אמאי לא מהימן\u0004 \u0005[מדוע אינו נאמן]?\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר באופן ש\u0003לא אכלה שני\u0004 \u0005[שנות]\u0006 \u0003חזקה — פשיטא דלא מהימן\u0004 \u0005[פשוט שאינו נאמן],\u0006 ואם כן מדוע שנה מקרה זה?","ומשיבים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ל\u0003גבי אביו משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות של ספק ביחס לחזקה, והמשנה באה ללמדנו כיצד הדין, \u0003כגון שאכלה\u0004 המחזיק מפירות השדה \u0003שתים,\u0004 שנתיים \u0003בחיי האב, ו\u0004שנה \u0003אחת בחיי בנו, וכ\u0004שיטת \u0003רב הונא.\u0004 ש\u0003אמר רב הונא: אין מחזיקין בנכסי קטן אפילו הגדיל.\u0004 שאין חזקה מועילה בנכסי קטן, גם אם גדל במשך הזמן ולא מיחה שמחזיקים בשדהו שלא כדין. משום שאין הקטן יודע מה היה רכושו של אביו, ומשום כך אינו יודע למחות כאשר מחזיקים בנכסיו ואין שנה זו מצטרפת לשנות חזקה.","ושואלים: אם כך, שנוסחה של משנתנו אפשר לפרשו רק לשיטת רב הונא, \u0003ו\u0004כי \u0003רב הונא מתניתין אתא לאשמועינן\u0004 \u0005[משנתנו בא להשמיע לנו]?\u0006 הרי כפי שהסברנו זהו דיוקה של משנתנו! ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003רב הונא דיוקא דמתניתין קאמר\u0004 \u0005[\u0006את \u0005דיוקה של המשנה אמר]\u0006 שאם כי ההלכה נובעת מן המשנה, אבל אינה מפורשת בה, והוא לימדנו לדייק מן המשנה כפי שדייקנו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אפילו הגדיל קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 שמן המשנה אפשר ללמוד שאין חזקה מועילה בנכסי יתום קטן, ורב הונא הוסיף חידוש, שאפילו כאשר גדל היתום, אין חזקה זו מועילה.","וחוזרים ושואלים: אם זה הוא החידוש במשנה, ומשום כך שנה במשנה את המקרה שמודה המחזיק שלקח מן האב, \u0003וליתנייה בדידיה\u0004 \u0005[ושישנה\u0006 את המשנה \u0005בו עצמו]\u0006 בטוען שקנה את השדה ממנו, \u0003ולוקמה\u0004 \u0005[ונעמיד אותה]\u0006 במקרה כזה, \u0003כגון שאכלה שתים בפניו\u0004 בפני בעל השדה הראשון \u0003ואחת שלא בפניו. ו\u0004כיצד — \u0003כגון שברח\u0004 אותו אדם ממקומו בשנה השלישית, ואין שנה זו מצטרפת לשנות החזקה.","ומשיבים: במקרה שברח יש לברר, \u0003ברח מחמת מאי\u0004 \u0005[מה]\u0006 מאיזו סיבה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ברח מחמת\u0004 האשמה שיש בה דיני \u0003נפשות — פשיטא דלא מהימן\u0004 \u0005[פשוט שאינו נאמן]\u0006 המחזיק בטענתו, כיון \u0003דלא מצי מחי\u0004 \u0005[שאין\u0006 בעל השדה \u0005יכול למחות],\u0006 שהרי הוא מעלים את עצמו מפני סכנת נפשות ואינו יכול לבוא ולמחות. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ברח מחמת\u0004 האשה שאין בה אלא חיוב \u0003ממון,\u0004 שהוא חייב כסף ואינו רוצה לשוב למקומו, \u0003איבעי ליה למחויי\u0004 \u0005[היה צריך לו למחות]\u0006 במקום שהוא מצוי בו. \u0003דקיימא לן\u0004 \u0005[ש\u0006הרי \u0005מוחזק בידינו]:\u0006 \u0003מחאה שלא בפניו\u0004 של המחזיק — \u0003הויא\u0004 \u0005[הרי היא]\u0006 \u0003מחאה,\u0004 ויכול להודיע בבית דין שבמקום אחר שהוא מוחה על החזקת השדה ביד אחר.","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שלש ארצות\u0004 נבדלות הן \u0003ל\u0004ענין \u0003חזקה\u0004 בארץ ישראל, והן: \u0003יהודה ועבר הירדן, והגליל. היה\u0004 האיש בעל השדה \u0003ביהודה והחזיק\u0004 אדם בשדהו \u0003בגליל,\u0004 או שהיה \u0003בגליל והחזיק ביהודה — אינה חזקה, עד שיהא עמו ב\u0004אותה \u0003מדינה.\u0004","\u0003והוינן בה\u0004 \u0005[והיינו עוסקים\u0006 ומתקשים \u0005בה\u0006 במשנה זו\u0005]\u0006 \u0003מאי קסבר\u0004 \u0005[מה סבור]\u0006 תנא זה? \u0003אי קסבר\u0004 \u0005[אם סבור\u0006 הוא\u0005]\u0006 ש\u0003מחאה שלא בפניו הויא\u0004 \u0005[הרי היא]\u0006 \u0003מחאה — אפילו\u0004 כשמדובר \u0003ביהודה וגליל נמי\u0004 \u0005[גם כן]\u0006 יכול למחות במקום שנמצא בו, שכן השומע ודאי יספר לחבירו אודות המחאה, וחבירו לחבירו, עד שדבר המחאה יגיע לאזני המחזיק וישמור על שטרו. \u0003ואי קסבר\u0004 \u0005[ואם סבור]\u0006 ש\u0003מחאה שלא בפניו לא הויא\u0004 \u0005[אינה\u0006 נחשבת\u0005]\u0006 \u0003מחאה — אפילו\u0004 כשמדובר \u0003ביהודה ויהודה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 תהיה חזקה אם אינו מצוי באותו מקום עצמו למחות בפניו!","\u0003אמר ר' אבא בר ממל: לעולם קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 ש\u0003מחאה שלא בפניו הויא\u0004 \u0005[הרי היא]\u0006 \u0003מחאה, ומתניתין\u0004 \u0005[ומשנה זו]\u0006 \u0003בשעת חירום שנו,\u0004 שאין הדרכים בטוחות ואי אפשר להעביר ידיעות מיהודה לגליל. ולכן, כשבעל השדה נמצא במדינה אחרת שאין קשר איתה, כיון שאינו יכול למחות — אף אין זו חזקה.","ושואלים: אם הטעם הוא מפני שעת חירום \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003יהודה וגליל דנקט\u0004 \u0005[שלקח\u0006 אותן כדוגמא\u0005]?\u0006 שהרי אין הדבר תלוי במרחק בין הארצות, אלא בשעת החירום בלבד!"],["\u0003סתם יהודה וגליל כשעת חירום דמו\u0004 \u0005[נחשבים],\u0006 משום שמלחמות תדירות באיזור זה ורצועה בה יושבים שומרונים מפסיקה באמצע, והקשרים בין שני המקומות אינם תקינים.","ושואלים עוד: מדוע שנה במשנה דין זה בענין מכירת קרקע ובאביו של התובע, \u0003וליתני\u0004 \u0005[ושישנה]:\u0006 \u0003מודה ר' יהושע\u0004 בענין מטלטלין ובתובע עצמו, וכגון \u0003באומר לחבירו \"מנה לויתי ממך ופרעתיו לך\" — שהוא נאמן!\u0004 ומשיבים: דבר זה לא שנה \u0003משום דקא בעי למיתני סיפא\u0004 \u0005[שרצה לשנות\u0006 ב\u0005סוף]\u0006 את ההלכה הנוספת: \u0003אם יש עדים שהוא לוה ממנו, והוא אומר: \"פרעתיו\" — אינו נאמן,\u0004 ודבר זה לא יכול לומר במודה שלוה וטוען שפרע, שכן \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 שאף \u0003המלוה את חבירו בעדים אינו צריך לפרעו בעדים.\u0004 ולכן, גם אם יש עדים שלווה ממנו והוא טוען: \"פרעתי\" — הרי הוא נאמן.","ושואלים עוד: \u0003וליתני\u0004 \u0005[ושישנה]:\u0006 \u0003מודה ר' יהושע באומר לחבירו: \"מנה לאביך בידי\",\u0004 כלומר, אביך הלווה לי מנה \u0003והאכלתיו פרס\u0004 (והחזרתי לו חצי מנה) \u0003\"\u0004\u0003שהוא נאמן!\u0004 ומשיבים: אי אפשר לומר כן, שכן דבר זה שנוי במחלוקת, ואי אפשר לומר הלכה זו לדעת אף אחד מן החולקים.","כי \u0003אליבא דמאן\u0004 \u0005[לפי שיטת\u0006 \u0005מי]\u0006 אמורים הדברים? \u0003אי אליבא דרבנן\u0004 \u0005[אם לפי שיטת חכמים] —\u0006 \u0003הא אמרי\u0004 \u0005[הרי אומרים\u0006 הם\u0005]\u0006 שבמקרה כזה \u0003משיב אבידה הוי\u0004 \u0005[הוא],\u0006 כי מאחר שהבן לא ידע כלל שאותו אדם חייב היה כסף לאביו, והוא מודה מעצמו — הריהו כאדם הבא ומשיב אבידה לחבירו, שפשוט שאינו צריך להישבע לחבירו ונאמן בטענתו. ו\u0003אי אליבא\u0004 \u0005[\u0006ו\u0005אם לפי שיטת]\u0006 \u0003ר' אליעזר בן יעקב — הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 שבמקרה כזה \u0003שבועה בעי\u0004 \u0005[\u0006הוא \u0005צריך]\u0006 ואינו נאמן סתם.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: פעמים שאדם נשבע על טענת עצמו.\u0004 שאף שלא תבעו ממנו מאומה, הרי מתוך הדברים שהוא עצמו אומר, חייב להישבע כדי לאמת את דבריו. \u0003כיצד?\u0004 כשאומר לחבירו \u0003\"מנה לאביך בידי והאכלתיו פרס\"\u0004 (חצי ממנו) — \u0003הרי זה נשבע\u0004 שפרע חצי זה, \u0003וזהו\u0004 המקרה \u0003שנשבע על טענת עצמו. וחכמים אומרים:\u0004 במקרה כגון זה \u0003אינו אלא כמשיב אבידה, ופטור\u0004 משבועה.","ושואלים: \u0003ו\u0004האם \u0003ר' אליעזר בן יעקב לית ליה\u0004 \u0005[אין לו],\u0006 אינו מקבל את ההלכה ש\u0003משיב אבידה פטור\u0004 מלהישבע שלא לקח לעצמו חלק ממנה, אלא משיב מה שבידו ואינו נשבע על השאר? \u0003אמר רב:\u0004 כאן מדובר \u0003בטוענו קטן.\u0004 כלומר, שהיה בן קטן למלוה, והבן הזה טוען שלא פרע הלווה לאביו כלל, וכיון שיש טוען כנגד הלווה, אין זה כמשיב אבידה. ומקשים: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003אין נשבעין על טענת חרש שוטה וקטן!\u0004 שכיון שאינם בני דעת, אינם מזקיקים את הנתבע להישבע!","ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קטן\"\u0004 שאמרנו — הכוונה היא ל\u0003גדול.\u0004 כלומר, שהטוען אינו קטן אלא גדול ובר דעת, \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 \u0003\"קטן\" —ש\u0004\u0003לגבי מילי\u0004 \u0005[דברים]\u0006 של \u0003אביו, קטן הוא,\u0004 לפי שאינו יודע בוודאות מה היו עסקי אביו. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש שמדובר במקרה שהבן טוען כנגדו ובשל כך עליו להשבע, אם כן הלשון אינה מדוייקת, שאין היא \u0003טענת עצמו\u0004 אלא \u0003טענת אחרים היא!\u0004 ומשיבים: אכן, \u0003טענת אחרים\u0004 היא, אבל \u0003הודאת עצמו.\u0004 ואדם זה נשבע על הודאת עצמו, שהרי הוא מודה במקצת.","ומקשים: \u0003כולהי טענתא\u0004 \u0005[כל הטענות]\u0006 שנשבעים עליהן, הלא בכלל \u0003טענת אחרים והודאת עצמו נינהו\u0004 \u0005[הן],\u0006 ולפי מה שמובן מכאן, יש כאן מקרה מיוחד (\"פעמים\") שנשבע על טענת עצמו!","\u0003אלא\u0004 צריך לחזור מפירוש זה ולומר כי \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004סברת \u0003רבה קמיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים]\u0006 ש\u0003אמר רבה: מפני מה אמרה תורה\u0004 ש\u0003מודה מקצת הטענה ישבע\u0004 — יש סברה בדבר: \u0003חזקה\u0004 היא ש\u0003אין אדם מעיז פניו בפני בעל חובו,\u0004 להכחיש לגמרי את חובו. \u0003ו\u0004משום כך יש להניח ש\u0003האי בכולה בעי דלכפריה\u0004 \u0005[\u0006שאדם \u0005זה,\u0006 המודה במקצת, בעצם \u0005בכל היה רוצה לכפור\u0006 ולהכחיש\u0005],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא כפר ליה\u0004 \u0005[לו]\u0006 הכל — \u0003משום\u0004 ש\u0003אין אדם מעיז פניו הוא,\u0004 ולא היתה בו עזות מצח להכחיש ולומר שאינו חייב כלל."],["\u0003ו\u0004משום טעם זה \u0003בכולה בעי דלודי ליה\u0004 \u0005[בכל רצה להודות לו]\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא אודי ליה\u0004 \u0005[הודה לו]\u0006 בכל — \u0003כי היכי דלישתמיט ליה\u0004 \u0005[כדי להשתמט ממנו]\u0006 לפי שעה, \u0003וסבר\u0004 \u0005[וחושב]:\u0006 \u0003עד דהוה\u0004 \u0005[שיהיו]\u0006 \u0003לי זוזי\u0004 \u0005[מעות]\u0006 \u0003ופרענא ליה\u0004 \u0005[ואפרע לו].\u0006 \u0003ו\u0004מפני שקיים שיקול זה לגבי המודה במקצת, \u0003רחמנא אמר\u0004 \u0005[אמרה תורה]:\u0006 \u0003רמי\u0004 \u0005[הטל]\u0006 \u0003שבועה עליה\u0004 \u0005[עליו]\u0006 \u0003כי היכי דלודי ליה בכוליה\u0004 \u0005[כדי שיודה לו בכל],\u0006 שיש מקום להניח שהטענה של התובע אמיתית היא.","ולענייננו, \u0003ר' אליעזר בן יעקב סבר: לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003בו\u0004 במלוה עצמו \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003בבנו, אינו מעיז\u0004 פנים כנגדם לכפור בכל, \u0003והלכך\u0004 \u0005[ומשום כך]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003משיב אבידה הוי\u0004 \u0005[הוא]\u0006 אינו נחשב למשיב אבידה, אלא כמודה במקצת הטענה, ולכן צריך להישבע. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003בו\u0004 עצמו \u0003הוא\u0004 ש\u0003אינו מעיז\u0004 פנים, \u0003אבל בבנו\u0004 שלא הוא הלווהו — \u0003מעיז\u0004 פנים. ואם היה רוצה לכפור — היה כופר בכול. \u0003ומ\u0004כיון ש\u0003לא העיז,\u0004 והודה שחייב מקצת — אם כן \u0003משיב אבידה הוי\u0004 \u0005[היא],\u0006 ונאמן.","\u0003העדים שאמרו\u0004 בעדותם על חתימות ידיהם שהיו בשטר: \u0003\"כתב ידינו הוא זה,\u0004 ואכן חתמנו עליו — \u0003אבל אנוסים היינו\u0004 לחתום \u0003\",\u0004 או \u0003\"קטנים היינו\u0004 בשעת מעשה \u0003\",\u0004 או \u0003\"פסולי עדות היינו\",\u0004 וכגון שאומרים שהיו קרובי משפחה לאחד הצדדים, או שהיו משחקים בקוביא שפסולים לעדות מדברי סופרים — \u0003הרי אלו נאמנים.\u0004 כי מאחר שעל פי עדותם אנו מקיימים את החתימה — יש גם לפסול על פיהם את תוקפה. \u0003ו\u0004אולם \u0003אם יש עדים\u0004 אחרים המעידים \u0003שהוא כתב ידם, או שהיה כתב ידם\u0004 של החתומים בשטר \u0003יוצא ממקום אחר,\u0004 שהיתה חתימה ודאית של עדים אלה על שטר אחר, ויכולים להשוות את כתב ידם ולהוכיח שחתימת ידם היא — \u0003אינן נאמנין\u0004 לפסול את תוקף חתימתם, שאינם יכולים לבטל בדבריהם בלבד את עדותם שהעידו בשטר.","על מה שאמרו במשנה שאם היה כתב ידם מקויים ממקום אחר אין נאמנים לפסול עדותם, \u0003אמר רמי בר חמא: לא שנו\u0004 כן \u0003אלא\u0004 כ\u0003שאמרו \"אנוסים היינו מחמת ממון\".\u0004 כלומר, שאיימו עליהם שיקחו מהם ממון, ולכן חתמו בשקר. וכיון שהם מעידים בכך על עצמם שעברו עבירה בגלל ממון, הריהם אומרים על עצמם שרשעים היו. וכלל בידינו שאין אדם נאמן על עצמו להשים עצמו רשע. \u0003אבל\u0004 אם אמרו \u0003\"אנוסים היינו מחמת נפשות\",\u0004 שאיימו עליהם להרגם אם לא יחתמו — \u0003הרי אלו נאמנין,\u0004 משום שבזה אינם מרשיעים את עצמם, שמפני אונס נפשות מותר היה להם לעשות זאת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: כל כמיניה\u0004 \u0005[וכי זה בכוחו]\u0006 להכחיש את עדותו הראשונה?! הרי כלל הוא: \u0003כיון שהגיד\u0004 העד דבר עדות בבית־דין — \u0003שוב אינו חוזר ומגיד,\u0004 ואין העד יכול להכחיש את עדותו הקודמת כשחתם על השטר. \u0003וכי תימא הני מילי\u0004 \u0005[ואם תאמר\u0006 ש\u0005דברים אלה]\u0006 שאין העד יכול לחזור בו מעדותו הם דווקא בעדות \u0003על פה. אבל\u0004 עדות \u0003בשטר — לא,\u0004 שמה שחתמו בשטר איננו נחשב כהגדה בבית דין ויוכלו לחזור בהם, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ריש לקיש: עדים החתומים על השטר — נעשה כמי ש\u0004העידו בעל פה ו\u0003נחקרה עדותן בבית דין,\u0004 ואם כן חתימה זו דינה כהגדת עדות, שאין יכולים לחזור ממנה!","\u0003אלא, כי אתמר\u0004 \u0005[כאשר נאמר]\u0006 בשם רמי בר חמא — \u0003ארישא אתמר\u0004 \u0005[על ראשה\u0006 של המשנה \u0005נאמר],\u0006 ששנינו שם שכשאין כתב ידם יוצא ממקום אחר \u0003הרי אלו נאמנין,\u0004 ועל כך \u0003אמר רמי בר חמא: לא שנו\u0004 שהם נאמנים לפסול עדותם \u0003אלא\u0004 כ\u0003שאמרו: \"אנוסין היינו מחמת נפשות\", אבל אמרו: \"אנוסין היינו מחמת ממון\" — אין נאמנין. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003אין אדם משים עצמו רשע.\u0004 וכיון שטוענים שהעידו שקר מפני ממון — אינם נאמנים, משום שבכך מרשיעים הם את עצמם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 עדים שאמרו שחתימת ידם על שטר אין בה תוקף מפני סיבה כלשהי — \u0003אין נאמנים לפוסלו,\u0004 אלו \u0003דברי ר' מאיר, וחכמים אומרים: נאמנים.\u0004 ושואלים: \u0003בשלמא לרבנן\u0004 \u0005[נניח ל\u0006דעת \u0005חכמים]\u0006 \u0003כי טעמייהו\u0004 \u0005[לפי טעמם]\u0006 שכבר אמרנו — \u0003שהפה שאסר\u0004 ואמר שהוא כתב ידו \u0003הוא\u0004 גם \u0003הפה שהתיר. אלא לר' מאיר מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שאין נאמנים לפסול את השטר? \u0003בשלמא\u0004 \u0005[נניח]\u0006 במקרה שטוענים שהיו \u0003פסולי עדות,\u0004 אפשר לומר שאין הדבר מסתבר, כי ה\u0003מלוה גופיה\u0004 \u0005[עצמו]\u0006 \u0003מעיקרא מידק דייק ומחתם\u0004 \u0005[מתחילה מדייק\u0006 היטב בכשרות העדים \u0005ו\u0006אחר \u0005מחתים\u0006 אותם\u0005]\u0006 ואין זה מסתבר שלקח פסולי עדות. וכן כשטוענים העדים שהיו \u0003קטנים נמי\u0004 \u0005[גם כן]\u0006 אינו מסתבר, ו\u0003כ\u0004דברי \u0003ר' שמעון בן לקיש.\u0004 ש\u0003אמר ריש לקיש:\u0004"],["\u0003חזקה\u0004 היא ש\u0003אין העדים חותמין על השטר אלא אם כן נעשה בגדול,\u0004 כלומר, ששני הצדדים היו מבוגרים, וכיוצא בזה חזקה היא שאין הצדדים מביאים עדים לחתום אלא אם כן היו העדים מבוגרים. ולכן סבור ר' מאיר שאין לסמוך על דבריהם שאומרים שקטנים היו. \u0003אלא\u0004 אם טוענים שהיו \u0003אנוסין\u0004 לחתום, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 סבור ר' מאיר שאין סומכים עליהם?","\u0003אמר רב חסדא, קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' מאיר: עדים שאמרו להם \"חתמו שקר ואל תהרגו\" — יהרגו ואל יחתמו שקר.\u0004 ולכן, אפילו כשטוענים \"אנוסים היינו מחמת נפשות\" — הרי הם מרשיעים את עצמם שחתמו שקר, ואין להאמין להם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 אי אפשר לומר כך, \u0003השתא אילו אתו לקמן לאמלוכי\u0004 \u0005[עכשיו,\u0006 הרי \u0005אילו היו באים\u0006 העדים \u0005לפנינו,\u0006 לפני חכמים \u0005להתייעץ]\u0006 איך לנהוג בכגון זה, הלא ודאי \u0003אמרינן להו\u0004 \u0005[\u0006היינו \u0005אומרים להם]:\u0006 \u0003זילו חתומו ולא תתקטלון\u0004 \u0005[לכו חתמו\u0006 על השטר \u0005ואל תיהרגו],\u0006 שהרי \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אין לך דבר שעומד בפני פיקוח נפש\u0004 ודוחה הצלת נפשות \u0003אלא\u0004 שלוש עבירות בלבד: \u0003עבודה זרה, וגלוי עריות, ושפיכות דמים בלבד.\u0004 וחתימת שקר איננה חמורה כל כך, ויעבור ואל יהרג. \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003חתמו\u0004 כבר, \u0003אמרינן להו\u0004 \u0005[אומרים אנו להם]:\u0006 \u0003אמאי חתמיתו\u0004 \u0005[מדוע חתמתם],\u0006 הלא כדין עשו, וכשרים הם ומדוע לא נאמין להם?","\u0003אלא\u0004 יש לומר כך: \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' מאיר כ\u0004פי שאמר \u0003רב הונא אמר רב.\u0004 ש\u0003אמר רב הונא אמר רב:\u0004 אם הלווה \u0003מודה בשטר שכתבו — אין\u0004 המלוה \u0003צריך\u0004 עוד \u0003לקיימו\u0004 בבית דין, שכיון שמודה הלווה בעצמו שכתב את השטר — אינו יכול אחר כך לטעון שהשטר הזה מזוייף או פרוע. ואף לענייננו, כיון שאמרו שחתמו על השטר — הרי השטר הוא לגבינו שטר מהימן, ואין כוח בידיהם לפוסלו (תוס').","\u0003גופא\u0004 \u0005[\u0006ל\u0005גופה]\u0006 של הלכה זו שהזכרנו. \u0003אמר רב הונא אמר רב: מודה בשטר שכתבו — אין צריך לקיימו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן\u0004 לרב הונא: \u0003גנובא גנובי\u0004 \u0005[לגנוב\u0006 דברים\u0005]\u0006 \u0003למה לך\u0004 שאתה מסתיר את טעמי דבריך, כגנב זה שבא בסתר. \u0003אי סבירא לך\u0004 \u0005[אם סבור אתה]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר — אימא\u0004 \u0005[אמור]\u0006 במפורש \u0003הלכה כר' מאיר,\u0004 ואל תנסח את הדברים באופן שהקשר עם מחלוקת התנאים בנושא זה אינו ניכר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003ומר, היכי סבירא ליה\u0004 \u0005[ואדוני, איך\u0006 הוא \u0005סבור],\u0006 מה עושים במקרה שבו מודה הלווה בשטר שכתבו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי אתו לקמן לדינא, אמרינן להו\u0004 \u0005[כאשר באים\u0006 מלווים כאלה \u0005לפנינו לדין, אומרים אנו להם]:\u0006 \u0003\"זילו קיימו שטרייכו וחותו לדינא\u0004 \u0005[לכו קיימו\u0006 את \u0005שטריכם ורדו,\u0006 בואו \u0005לדין]\u0006\u0003\",\u0004 שאם יבואו לסמוך רק על הודאת הלווה, יוכל הלווה לטעון שכבר פרע את השטר, מה שלא יוכל לעשות אם יהא השטר מקוים כדין על ידי החותמים.","\u0003אמר רב יהודה אמר רב, האומר\u0004 על שטר: \u0003\"שטר אמנה הוא זה\",\u0004 שטוען שאמנם נכתב השטר כדין, אבל לא היתה כאן הלוואה, אלא שהוא, החתום כלווה, האמין למלוה ומסר לו את השטר, כדי ללוות ממנו בעתיד, או כבטחון, ולא לפורעו — \u0003אינו נאמן.\u0004","ושואלים: \u0003דקאמר מאן\u0004 \u0005[שאומר מי],\u0006 מיהו זה האומר שהיה זה שטר אמנה? \u0003אילימא דקאמר\u0004 \u0005[אם תאמר שאומר]\u0006 ה\u0003לוה\u0004 שהשטר הוא שטר אמנה — \u0003פשיטא, כל כמיניה\u0004 \u0005[פשוט,\u0006 וכי \u0005הכל ביכולתו]?\u0006 וכי יכול הלווה לבוא ולטעון שהשטר אינו שטר אמיתי?! \u0003ואלא\u0004 תאמר \u0003דקאמר\u0004 \u0005[שאומר]\u0006 זאת ה\u0003מלוה — תבוא עליו ברכה,\u0004 שהוא מודה שהשטר הזה לא נועד לפרעון. \u0003אלא\u0004 תאמר \u0003דקאמרי\u0004 \u0005[שאומרים]\u0006 ה\u0003עדים\u0004 שהיה זה שטר אמנה. ונברר: \u0003אי\u0004 \u0005[אם]\u0006 מדובר פה במקרה ש\u0003כתב ידם יוצא ממקום אחר — פשיטא דלא מהימני\u0004 \u0005[פשוט,\u0006 מובן מאליו \u0005שאינם נאמנים],\u0006 שהרי השטר הוא כשטר מקויים. \u0003ואי\u0004 \u0005[ואם]\u0006 במקרה ש\u0003אין כתב ידם יוצא ממקום אחר\u0004 אלא העדים עצמם מקיימים את חתימת ידם שעל השטר, אבל אומרים שהוא שטר אמנה — \u0003אמאי לא מהימני\u0004 \u0005[מדוע אינם נאמנים]?\u0006 הרי הפה שאסר הוא הפה שהתיר!","(סימן לשמות המתרצים שאלה זו \u0003באש\u0004 ר\u0003ב\u0004א, \u0003א\u0004ביי, רב א\u0003ש\u0004י) \u0003אמר רבא: לעולם דקאמר\u0004 \u0005[שאומר]\u0006 זאת ה\u0003לוה, ו\u0004צריכים לפרש זאת על פי דברי \u0003רב הונא.\u0004 ש\u0003אמר רב הונא אמר רב: מודה בשטר שכתבו — אין צריך לקיימו.\u0004 וכאן אמנם מודה הלווה שכתב את השטר והחתים עדים, אבל טוען שהיה זה שטר אמנה. והחידוש בדברי רב יהודה הוא שמכיון שהודה בשטר, אף שמנסה אחר כך לבטל את תוקפו — אינו נאמן.","\u0003אביי אמר: לעולם\u0004 נפרש ש\u0003אמר\u0004 זאת ה\u0003מלוה, וכגון\u0004 במקרה \u0003שחב לאחרים.\u0004 כלומר, המלוה חייב כסף לאחרים ואין בידו מספיק כדי לפרוע את חובותיו אלא על ידי גביית שטר זה, ונמצא שעל ידי הודאתו, שמבטלת את תוקפו של השטר, נמצאים הנושים שלו מפסידים בכך. \u0003וכ\u0004דברי \u0003ר' נתן,\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נתן אומר: מנין ל\u0004אדם שהיה \u0003נושה\u0004 (תובע) \u0003בחבירו מנה\u0004 שחייב לו, \u0003וחבירו בחבירו\u0004 האחר — \u0003מנין שמוציאין מזה\u0004 מן הלווה האחרון \u0003ונותנין לזה,\u0004 למלוה הראשון, ואין צורך לעבור את שלב הביניים של האיש שבאמצע — \u0003תלמוד לומר: \"ונתן לאשר אשם לו\"\u0004 (במדבר ה, ז), ולא נאמר \"ונתן לאשר הלווהו\", שמכאן למדים שאין חובה לשלם דווקא למלווה הישיר, אלא משלם למי שחייבים לו, גם אם הוא עצמו לא הלווה לו את הכסף במישרין, ועכשיו שהמלוה האמצעי הודה שהשטר איננו שטר, נמצא מפסיד לנושים שלו את כספם.","\u0003רב אשי אמר: לעולם\u0004 מדובר באופן \u0003דקאמרי\u0004 \u0005[שאומרים]\u0006 כן ה\u0003עדים. ו\u0004מדובר כאן במקרה ש\u0003אין כתב ידם יוצא ממקום אחר. ודקאמרת אמאי לא מהימני\u0004 \u0005[\u0006ו\u0005מה שאמרת מדוע אינם נאמנים]\u0006 — הרי זה \u0003כ\u0004דברי \u0003רב כהנא.\u0004 ש\u0003אמר רב כהנא: אסור לו לאדם שישהה שטר אמנה בתוך ביתו, משום שנאמר: \"\u0004ו\u0003אל תשכן באהליך עולה\"\u0004 (איוב יא, יד), משום שיש בכך שקר, ועלול להביא לידי עוול כשיבואו לגבות בשטר זה."],["\u0003ואמר רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003מ\u0004דברי \u0003רב כהנא,\u0004 כי \u0003עדים שאמרו \"אמנה היו דברינו\",\u0004 שאמנם חתמנו על השטר, אבל היה זה שטר אמנה — \u0003אין נאמנין. ומאי טעמא\u0004 \u0005[\u0006ו\u0005מה הטעם]?\u0006 — \u0003כיון\u0004 ש\u0003עולה הוא\u0004 שטר אמנה, שאף החזקתו אסורה — על \u0003עולה לא חתמי\u0004 \u0005[אין\u0006 הם \u0005חותמים],\u0006 ואינם יכולים להרשיע את עצמם שחתמו על דבר עבירה.","\u0003אמר ר' יהושע בן לוי: אסור לו לאדם שישהה שטר פרוע בתוך ביתו, משום שנאמר: \"\u0004ו\u0003אל תשכן באהליך עולה\"\u0004 (איוב יא, יד), שאף שהוא עצמו לא יגבה אותו, שמא יתגלגל השטר לידי אחרים ויבואו לגבות בו שלא כדין. \u0003במערבא משמיה\u0004 \u0005[בארץ ישראל, משמו]\u0006 של \u0003רב אמרי\u0004 \u0005[היו אומרים]:\u0006 מה שנאמר \u0003\"אם און בידך הרחיקהו\"\u0004 (איוב יא, יד) — \u0003זה שטר אמנה ושטר פסים\u0004 (שטר בטחון), ומה שנאמר \u0003\"ואל תשכן באהליך עולה\"\u0004 (איוב יא, יד) — \u0003זה שטר פרוע.\u0004","ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 על \u0003שטר פרוע\u0004 שהוא עוולה, \u0003כל שכן\u0004 ש\u0003שטר אמנה\u0004 הוא עוולה ואסור להשהותו, משום שמעיקרו הוא דבר שקר. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 כי \u0003שטר אמנה\u0004 הוא עוולה — \u0003אבל שטר פרוע — לא,\u0004 ושמא אינו סבור שאסור להשהותו, \u0003דזמנין דמשהי ליה אפשיטי דספרא\u0004 \u0005[שפעמים שמשהים אותו\u0006 ואין מחזירים אותו ללווה \u0005בגלל פרוטות,\u0006 מעותיו \u0005של הסופר],\u0006 שהדין הוא שהלווה משלם לסופר את דמי כתיבת השטר. ואם לא שילם בשעתו, המלווה אינו מחזיר לו את השטר עד שישלם גם את דמי כתיבת השטר.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 בדומה לזה בענין השהיית דברים שיכולים להביא לידי מכשול, \u0003ספר\u0004 תורה או נביאים וכתובים, \u0003שאינו מוגה\u0004 ויש בו שגיאות, \u0003אמר ר' אמי: עד שלשים יום מותר לשהותו\u0004 בלי הגהה, \u0003מכאן ואילך אסור לשהותו, משום שנאמר: \"\u0004ו\u0003אל תשכן באהליך עולה\"\u0004 (איוב יא, יד).","\u0003אמר רב נחמן: עדים שאמרו \"אמנה היו דברינו\"\u0004 שהצדדים הסכימו שלא לפרוע שטר זה — \u0003אין נאמנין.\u0004 וכן אם אמרו: \u0003\"מודעא היו דברינו\",\u0004 שהמתחייב בשטר זה הודיע לנו קודם לכן שהוא עושה זאת באונס, ומבטל את תוקפו של השטר — \u0003אין נאמנין.\u0004 ואילו \u0003מר בר רב אשי אמר:\u0004 אם אומרים \u0003\"אמנה היו דברינו\" — אין נאמנין,\u0004 ואם אומרים \u0003\"מודעא היו דברינו\" — נאמנין. מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל? \u0003האי\u0004 \u0005[\u0006שטר \u0005זה]\u0006 שעשו עליו מודעה — הרי \u0003ניתן ליכתב,\u0004 שמותר לכתוב שטר כזה, שכן מחמת אונס הוא כותב. \u0003והאי\u0004 \u0005[וזה]\u0006 שטר אמנה — \u0003לא ניתן ליכתב.\u0004 שהרי אמרנו שאסור לכתוב שטר כגון זה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004 אם אמרו העדים \u0003\"תנאי היו דברינו\" מהו?\u0004 כלומר, שמאשרים את חתימתם, אלא אומרים שהיה עוד תנאי בעל פה שלא נכתב בשטר, האם נאמנים הם? וצדדי השאלה: שכשהעדים אומרים ששטר זה אינו תקף משום שקדמה לכתיבתו \u0003מודעא\u0004 של המתחייב, או ששטר זה \u0003אמנה\u0004 הוא, \u0003היינו טעמא\u0004 \u0005[זה הטעם]\u0006 שאין נאמנים — משום \u0003דקא עקרי ליה לשטרא\u0004 \u0005[ש\u0006הם \u0005עוקרים את השטר]\u0006 הכתוב, \u0003והאי נמי קא עקר לשטרא\u0004 \u0005[וזה גם כן עוקר את השטר],\u0006 שהרי כאשר הם מוסיפים שהיה בו תנאי — אין לשטר תוקף כפי שהוא. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003תנאי מילתא אחריתי היא\u0004 \u0005[דבר אחר הוא]\u0006 ואינו נחשב כערעור עצם תוקפו של השטר אלא כתוספת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003כי אתו לקמן לדינא\u0004 \u0005[כאשר באים\u0006 אנשים \u0005לפנינו לדין],\u0006 במקרה כזה \u0003אמרינן להו\u0004 \u0005[אומרים אנו להם]\u0006 לבעלי השטר: \u0003\"זילו\u0004 \u0005[לכו]\u0006 \u0003קיימו תנאייכו\u0004 \u0005[\u0006את \u0005תנאיכם]\u0006 \u0003וחותו לדינא\u0004 \u0005[ורדו,\u0006 בואו, \u0005לדין]\u0006\u0003\".\u0004 כלומר, קודם צריכים אתם לברר את ענין התנאי, ואם העדים עדים נאמנים הם — קיימו את התנאי, ואם גם אחר קיום התנאי לא יעכב הנתבע ולא יקיים את התחייבותו — בואו לדין.","על בסיס דברים אלה שואלים שאלה נוספת: \u0003עד\u0004 אחד \u0003אומר \"תנאי\u0004 היה בדבר \u0003\", ועד\u0004 אחר \u0003אומר \"אינו תנאי\",\u0004 כלומר, לא היה כל תנאי בדבר, מה הדין? \u0003אמר רב פפא:\u0004 הלא \u0003תרוייהו בשטרא מעליא קא מסהדי\u0004 \u0005[שניהם בשטר מעולה\u0006 הם \u0005מעידים],\u0006 שהרי שניהם מעידים שהשטר הוא שטר בעל תוקף, \u0003והאי דקאמר\u0004 \u0005[וזה שאומר]:\u0006 \u0003\"תנאי\u0004 היה בשטר \u0003\",\u0004 אם כן \u0003הוה ליה חד\u0004 \u0005[הרי הוא\u0006 עד \u0005אחד]\u0006 בלבד הגורע תוקף השטר — \u0003ואין\u0004 תוקף ל\u0003דבריו של אחד במקום שנים.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: אי הכי\u0004 \u0005[אם כך]\u0006 אתה סבור, שתוספת תנאי היא כביטול השטר עצמו, \u0003אפילו תרוייהו נמי\u0004 \u0005[שניהם גם כן]\u0006 אם אומרים שהיה תנאי בדבר לא יהיו נאמנים, שהרי קודם לכן העידו שהשטר היה שטר כשר, וכיצד יכולים הם לעקור את תוקפו של השטר על ידי עדותם האחרת? \u0003אלא, אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003הני למיעקר סהדותייהו קאתו\u0004 \u0005[אלה לעקור את עדותם\u0006 הראשונה הם \u0005באים],\u0006 שאין כאן שתי עדויות נבדלות, שאחת באה אחר השניה, אלא שאותם העדים עצמם עוקרים ומגבילים את תוקף עדותם הראשונה, אם כן \u0003האי נמי למיעקר סהדותיה קאתי\u0004 \u0005[זה גם כן,\u0006 העד האחד, \u0005לעקור את עדותו שלו\u0006 הוא \u0005בא]\u0006 ונמצא שעל השטר הזה אין עדות של שתי חתימות, שהרי חתימה אחת אין העדות עליה שלימה. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע,\u0004 שאפילו עד אחד נאמן לומר שהיה תנאי בדבר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 היו \u0003שנים חתומין על השטר, ומתו, ובאו שנים מן השוק\u0004 (אנשים זרים) \u0003ואמרו: ידענו שכתב ידם הוא, אבל\u0004 יודעים אנו גם כן שבזמן החתימה \u0003אנוסים היו,\u0004 או \u0003קטנים היו,\u0004 או \u0003פסולי עדות היו — הרי אלו\u0004 (השנים המעידים על אמינות החתימות) \u0003נאמנים\u0004 לפסול את השטר, משום שהפה שאסר הוא הפה שהתיר. \u0003ואם יש עדים\u0004 אחרים \u0003שכתב ידם הוא זה, או שהיה כתב ידם\u0004 של עדי החתימה \u0003יוצא ממקום אחר,\u0004 וכיצד — \u0003משטר\u0004 אחר \u0003שקרא עליו ערער\u0004 (שהיה מישהו שערער על מהימנותו) \u0003והוחזק בבית דין,\u0004 שבית דין בדקו והוכיחו שהשטר הזה כתוב וחתום כראוי — \u0003אין אלו\u0004 המעידים לפסול את השטר \u0003נאמנין\u0004 עוד, ואין סומכים על עדותם זו.","ושואלים: אם כאשר היו עדים אחרים המקיימים את השטר או שכתב ידם יוצא ממקום אחר, \u0003ו\u0004כי \u0003מגבינן ביה כבשטרא מעליא\u0004 \u0005[גובים אנו בו,\u0006 בשטר זה, \u0005כבשטר מעולה]?\u0006 \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 הלא \u0003תרי ותרי נינהו\u0004 \u0005[שניים ושניים הם],\u0006 שני עדים החתומים המעידים על כשרות השטר, שחתימותיהם מקויימות, ושני עדים אחרים שאומרים שהשטר פסול, ולכאורה אי אפשר לגבות בו כבשטר כשר!","\u0003אמר רב ששת: זאת אומרת הכחשה תחלת הזמה היא,\u0004 כלומר, דין הכחשת עדים, כשיש עדויות סותרות, נידון כמו בדיני הזמה, והגבלות שיש בדיני הזמה קיימות גם בדיני הכחשת עדים."],["\u0003וכשם שאין מזימין את העדים אלא בפניהם,\u0004 שהרי העדים המזימים באים לחייב את העדים הראשונים בעונשים על ידי עדותם, ואין מעידים להעניש אדם אלא בפניו, \u0003כך אין מכחישין את העדים אלא בפניהם.\u0004 וכיון שהעדים הראשונים החתומים על השטר מתו — אי אפשר להכחיש אותם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: אילו הוו קמן\u0004 \u0005[היו\u0006 העדים הראשונים באים \u0005לפנינו]\u0006 \u0003ו\u0004היו האחרים \u0003מכחישין להו\u0004 \u0005[אותם],\u0006 הלא \u0003הוה\u0004 \u0005[היתה\u0006 זו\u0005]\u0006 \u0003הכחשה ולא הוה\u0004 \u0005[היינו]\u0006 \u0003משגיחין,\u0004 מתחשבים, \u0003בהו\u0004 \u0005[בהם]\u0006 בראשונים, \u0003דהוי לה\u0004 \u0005[שהיתה זאת]\u0006 \u0003עדות מוכחשת,\u0004 כנגד שני העדים האחרים. \u0003השתא דליתנהו\u0004 \u0005[עכשיו שאינם],\u0006 שיש מקום לומר עוד ש\u0003אילו הוו לקמן\u0004 \u0005[היו\u0006 העדים הראשונים \u0005לפנינו]\u0006 \u0003דלמא הוו מודו להו\u0004 \u0005[שמא היו מודים להם\u0006 לאחרונים\u0005],\u0006 \u0003מהימני\u0004 \u0005[נאמנים\u0006 הם\u0005]?!\u0006","\u0003אלא אמר רב נחמן\u0004 במקרה כזה של הכחשה שלא בפניהם אנחנו נוהגים כך: \u0003אוקי תרי להדי תרי\u0004 \u0005[העמד שניים\u0006 עדים \u0005כנגד שניים\u0006 אחרים\u0005]\u0006 והרי זה מצב שקול, \u0003ואוקי ממונא בחזקת מריה\u0004 \u0005[והעמד\u0006 את \u0005הממון בחזקת בעליו]\u0006 המחזיקים בו, \u0003מידי דהוה אנכסי\u0004 \u0005[כפי שהוא\u0006 הדבר בענין \u0005נכסיו]\u0006 של \u0003בר שטיא.\u0004 שאדם אחד שהיה מכונה \u0003בר שטיא\u0004 משום שהיה לעתים משתגע, \u0003זבין נכסי\u0004 \u0005[מכר\u0006 את \u0005נכסיו].\u0006 \u0003אתו בי תרי, אמרי\u0004 \u0005[באו שניים\u0006 ו\u0005אמרו]:\u0006 \u0003כשהוא שוטה זבין\u0004 \u0005[מכר],\u0006 \u0003ואתו בי תרי ואמרי\u0004 \u0005[ובאו שניים\u0006 אחרים ו\u0005אמרו]:\u0006 \u0003כשהוא חלים זבין\u0004 \u0005[בריא מכר].\u0006","\u0003אמר\u0004 על כך \u0003רב אשי: אוקי תרי להדי תרי\u0004 \u0005[העמד שניים כנגד שניים],\u0006 \u0003ואוקי ממונא\u0004 \u0005[והעמד\u0006 את \u0005הממון]\u0006 \u0003בחזקת\u0004 בעליו הראשון \u0003בר שטיא.\u0004 ומעירים על כך: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא דאית ליה\u0004 \u0005[שיש לו,\u0006 לבר שטיא\u0005]\u0006 \u0003חזקה דאבהתיה\u0004 \u0005[של אבותיו]\u0006 שירש נכסים אלה מאבותיו, ולכן הם בחזקתו. \u0003אבל\u0004 אם \u0003לית ליה\u0004 \u0005[אין לו]\u0006 \u0003חזקה דאבהתיה\u0004 \u0005[של אבותיו],\u0006 אלא קנה בעצמו את הנכסים, \u0003אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003כשהוא שוטה זבן\u0004 \u0005[קנה],\u0006 \u0003וכשהוא שוטה זבין\u0004 \u0005[מכר].\u0006 וכין שמעולם לא היתה לו חזקה בנכסים, יישארו אלה בחזקת הקונה.","\u0003אמר ר' אבהו\u0004 שלא כדברי רב ששת: אף ש\u0003אין מזימין את העדים אלא בפניהן\u0004 משום שעל ידי כך מחייבים אותם בעונשים, \u0003ו\u0004אולם \u0003מכחישין את העדים\u0004 אף \u0003שלא בפניהן.\u0004 ומעירים: \u0003והזמה שלא בפניהן,\u0004 כשבאים שני עדים ומעידים, שלא בפני הראשונים, שהיו עימם במקום אחר, \u0003נהי\u0004 \u0005[אם כי]\u0006 ש\u0003הזמה לא הוי\u0004 \u0005[איננה]\u0006 ואין מחייבים אותם עונשים על פי עדות זו, \u0003הכחשה מיהא הויא\u0004 \u0005[מכל מקום הריהי]\u0006 העדות הראשונה מוכחשת על ידי השניה ובטלה עדותם.","א \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שהבאנו קודם: עדים המאשרים את אמינות חתימות עדים החתומים על שטר, אלא שאומרים שבזמן שחתמו אותם עדים על השטר, היו הם קטנים או פסולים — הרי אלו נאמנים לפסול את השטר. אבל \u0003אם יש עדים\u0004 אחרים המעידים \u0003ש\u0004אכן \u0003כתב ידם\u0004 של העדים החתומים בשטר \u0003הוא זה, או שהיה כתב ידם\u0004 של העדים החתומים \u0003יוצא ממקום אחר,\u0004 כגון \u0003משטר שקרא עליו ערער\u0004 (שפקפקו באמינותו) \u0003והוחזק בבית דין\u0004 לאחר בדיקה — \u0003אין\u0004 העדים הראשונים \u0003נאמנין\u0004 לפסול את השטר. ומעירים על כך: משטר ש\u0003קרא עליו ערער — אין\u0004 \u0005[כן],\u0006 אכן, אינם נאמנים, אבל אם \u0003לא קרא עליו ערער — לא,\u0004 אין שטר כזה נחשב כאמיתי ואי אפשר להוכיח ממנו את נכונות חתימתם, והרי \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לר' אסי,\u0004 ש\u0003אמר ר' אסי: אין מקיימין את השטר אלא משטר שקרא עליו ערער והוחזק בבית דין.\u0004","\u0003אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003אין מקיימין את השטר אלא\u0004 כאשר יכולים להשוות את חתימות העדים \u0003משתי כתובות או מ\u0004שטרות מכר של \u0003שתי שדות\u0004 שעדים אלה היו חתומים על השטרות הללו, \u0003והוא,\u0004 לגבי שטרי מכר של שדות, דווקא \u0003שאכלום בעליהן שלש שנים,\u0004 שהם זמן חזקה \u0003ובשופי\u0004 (בשקט), בלא שיצא עירעור על כך. שאז מוכח ששטרות הללו אכן היו כשרים, ואפשר להסתמך על החתימות שבהם.","\u0003אמר רב שימי בר אשי:\u0004 כשמקיימים את החתימות בשטר על ידי השוואה לשטרות אחרים, עושים זאת דווקא \u0003וביוצא מתחת יד אחר,\u0004 ולא משטרות שנמצאים אצל בעל הדין עצמו. \u0003אבל\u0004 אם יוצא \u0003מיד עצמו — לא.\u0004 שואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 שאם יוצא מ\u0003תחת יד עצמו\u0004 ש\u0003לא\u0004 מאמינים \u0005—\u0006 \u0003דלמא זיופי מזייף\u0004 \u0005[שמא זייף]\u0006 את חתימת העדים, שכיון שהיה השטר בידו השווה וזייף את חתימתם. אולם אם כן כשיוצא השטר \u0003מתחת ידי אחר נמי\u0004 \u0005[גם כן]\u0006 יש לחשוש \u0003דלמא אזל וחזא אתא\u0004 \u0005[שמא הלך\u0006 לבעל השטר \u0005וראה\u0006 את החתימות ו\u0005בא\u0006 לביתו\u0005]\u0006 \u0003וזייף!\u0004 ומשיבים: \u0003כולי האי לא מצי מכוין\u0004 \u0005[כל זה\u0006 כך \u0005אינו יכול לכוון]\u0006 שיעשה חתימות זהות רק על פי הזכרון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כותב אדם עדותו\u0004 לעצמו \u0003על השטר\u0004 בכתב, \u0003ומעיד עליה אפילו לאחר כמה שנים. אמר רב הונא: והוא, שזוכרה מעצמו,\u0004 כלומר, רק כאשר העד זוכר את הענין מעצמו, ואינו נזקק לשטר אלא לרענן את זכרונו לגבי פרטים. \u0003ר' יוחנן אמר: אף על פי שאין זוכרה מעצמו\u0004 כלל. \u0003אמר רבה: שמע מינה\u0004 \u0005[למד ממנה]\u0006 \u0003מ\u0004דברי \u0003ר' יוחנן:\u0004 כי \u0003הני בי תרי דידעי סהדותא ומנשי חד מנייהו\u0004 \u0005[שניים שיודעים\u0006 ב\u0005עדות ושכח אחד מהם\u0006 את העדות\u0005],\u0006 \u0003מדכר חד לחבריה\u0004 \u0005[מזכיר אחד לחבירו],\u0006 שהרי אמר ר' יוחנן שגם אם נזכר על ידי אמצעי אחר (כתב), הרי זו עדות כשירה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים: אם בעל הדין \u0003עצמו\u0004 מזכיר לעד, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003רב חביבא אמר: אפילו\u0004 אם מזכירו בעל הדין \u0003עצמו\u0004 — כשר, \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי אמר:\u0004 בעל הדין \u0003עצמו לא.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא כי בעל הדין \u0003עצמו לא,\u0004 שאין העד יכול לסמוך אז על זכרונו שחזר אליו בסיוע בעל הדין, שמא השפיע עליו בעל הדין בדבריו."],["\u0003ואי צורבא מרבנן\u0004 \u0005[ואם תלמיד חכם]\u0006 \u0003הוא\u0004 העד, \u0003אפילו\u0004 שבעל דין \u0003עצמו\u0004 מזכיר לו — נאמן, כי תלמיד חכם מדייק בדברים, ואם לא היה נזכר מעצמו כלל, לא היה מעיד. \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003רב אשי הוה ידיע ליה בסהדותא\u0004 \u0005[היה ידוע לו בעדות]\u0006 בנוגע \u0003לרב כהנא. אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא לרב אשי: \u0003מי דכיר מר האי סהדותא\u0004 \u0005[האם זוכר אדוני עדות זו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא.\u0004 הזכיר לו רב כהנא: \u0003ולאו הכי והכי הוה\u0004 \u0005[ולא כך וכך היה]\u0006 המעשה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003לא ידענא\u0004 \u0005[אינני יודע],\u0006 \u0003לסוף אידכר\u0004 \u0005[לבסוף נזכר]\u0006 \u0003רב אשי\u0004 בעצמו ו\u0003אסהיד ליה\u0004 \u0005[\u0006ו\u0005העיד לו].\u0006 \u0003חזייה\u0004 \u0005[ראהו]\u0006 את \u0003רב כהנא דהוה מחסם\u0004 \u0005[שהיה מהסס]\u0006 ביחס לקבלת עדות זו, שמא דבריו הם שהשפיעו על עדותו של רב אשי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003מי סברת עלך קא סמיכנא\u0004 \u0005[\u0006ו\u0005האם סבור אתה\u0006 ש\u0005עליך אני סומך]?\u0006 \u0003אנא הוא דרמאי אנפשאי ואדכרי\u0004 \u0005[אני הוא שהטלתי\u0006 את הדבר \u0005על עצמי ונזכרתי],\u0006 שלאחר מכן השתדלתי לחשוב שוב בדבר, ונזכרתי בעצמי את פרטי המאורע.","באותו ענין של זכירת עדויות, מוסיפה הגמרא, \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003התלוליות\u0004 (ערימות עפר) \u0003הקרובות בין לעיר ובין לדרך, אחד חדשות ואחד ישנות — טמאות,\u0004 משום החשש שמא נקבר מת תחתיהן. \u0003הרחוקות\u0004 מן העיר, אם היו \u0003חדשות — טהורות,\u0004 שאם אין אנשים זוכרים שנקבר שם אדם — ודאי טהורות הן. אם היו \u0003ישנות — טמאות.\u0004 ומגדירים: \u0003איזוהי\u0004 תלולית \u0003קרובה\u0004 — זו שהיא עד מרחק \u0003חמישים אמה\u0004 מן העיר, \u0003ואיזו היא ישנה\u0004 — שהיתה יותר מ\u0003ששים שנה,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: קרובה\u0004 משמעה \u0003שאין\u0004 תלולית אחרת \u0003קרובה הימנה, ישנה\u0004 היא — \u0003שאין אדם זוכרה,\u0004 ואין לדברים אלה גבול קצוב.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003\"עיר\" ומאי\u0004 \u0005[ומה\u0006 היא\u0005]\u0006 \u0003\"דרך\"\u0004 זו שמדובר בה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003\"עיר\"\u0004 — כוונתו \u0003עיר ממש, \"דרך\"\u0004 — הכוונה \u0003דרך ממש,\u0004 שמדובר פה בכל עיר ובכל דרך. יש לתמוה: \u0003מספיקא מי מחזקינן\u0004 \u0005[מספק האם אנחנו מחזיקים]\u0006 \u0003טומאה\u0004 בארץ ישראל? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש\u0004 בהסבירו כיצד סמכו חכמים על הוכחה קלושה כדי לטהר מקום שהיה בו ספק טומאה בארץ ישראל: \u0003עילה,\u0004 כלומר, איזושהי סיבה ואמתלה \u0003מצאו וטהרו\u0004 את \u0003ארץ ישראל.\u0004 משמע שאין אנו מחזיקים טומאה, אלא להיפך, משתדלים בכל מקרה למצוא דרך לטהר, וכיצד חוששים פה לכל תלולית הקרובה לעיר או לדרך בכל מקום? \u0003אמר ר' זירא: \"עיר\"\u0004 — הכוונה \u0003עיר הסמוכה לבית הקברות, ו\"דרך\"\u0004 — היא \u0003דרך בית הקברות,\u0004 ולכן יש סיבה לחשוש לטומאה המצויה שם.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003דרך בית הקברות,\u0004 אפשר להבין שקבור אדם בתלולית, \u0003דזמנין דמתרמי\u0004 \u0005[שפעמים שמזדמן]\u0006 שצריך לקבור את המת ערב שבת \u0003בין השמשות\u0004 ואין זמן להגיע לבית הקברות ממש \u0003ומקרו קברו\u0004 \u0005[ומזדמנים\u0006 ש\u0005קוברים]\u0006 \u0003בתל. אלא עיר הסמוכה לבית הקברות,\u0004 הלא \u0003כולהי\u0004 \u0005[הכל]\u0006 \u0003לבית הקברות אזלי\u0004 \u0005[הולכים],\u0006 ומדוע שיקברו ליד העיר?","\u0003אמר ר' חנינא: מתוך שהנשים קוברות שם\u0004 ליד העיר את \u0003נפליהן,\u0004 ואין קוברים אותם בציבור, ואשה עצמה הולכת וקוברת שם. \u0003ו\u0004כן \u0003מוכי שחין\u0004 שאבריהם נושרים קוברים שם את \u0003זרועותיהם.\u0004 ועל זה אמרו ש\u0003עד\u0004 מרחק \u0003חמשים אמה\u0004 מן העיר \u0003אזלא איהי לחודה\u0004 \u0005[הולכת היא\u0006 האשה \u0005לבדה]\u0006 וקוברת את הנפל בתלולית. \u0003טפי\u0004 \u0005[\u0006ובמרחק \u0005יותר\u0006 מזה\u0005] —\u0006 \u0003דברא איניש בהדה\u0004 \u0005[\u0006היא \u0005לוקחת אדם\u0006 אחר \u0005איתה],\u0006 משום שחוששת ללכת לבדה, \u0003ו\u0004אז \u0003לבית הקברות אזלא\u0004 \u0005[\u0006היא \u0005הולכת].\u0006 \u0003הלכך\u0004 (על כן), \u0003טומאה בארץ ישראל לא מחזקינן\u0004 \u0005[אין אנו מחזיקים],\u0006 אלא בכגון זה, שיש מקום סביר לחשש.","\u0003אמר רב חסדא: שמע מינה\u0004 \u0005[למד ממנה]\u0006 \u0003מ\u0004דברי \u0003ר' מאיר\u0004 שקבע זמן זה לתלולית ישנה: \u0003האי סהדותא\u0004 \u0005[עדות זו]\u0006 \u0003עד שיתין שנין\u0004 \u0005[ששים שנה]\u0006 — \u0003מידכר\u0004 \u0005[זכורה],\u0006 \u0003טפי\u0004 \u0005[יותר\u0006 מזה\u0005] —\u0006 \u0003לא מידכר\u0004 \u0005[אינה זכורה],\u0006 לכן קבע שיעור זמן זה גם לגבי טומאה. ודוחים: \u0003ולא היא,\u0004 אין הדבר כן, \u0003התם הוא דלא רמיא עליה\u0004 \u0005[שם הוא שאין\u0006 הדבר \u0005מוטל עליו],\u0006 שהרי לא נתבקש אדם מסויים לבוא להעיד, ולכן נשכח הדבר. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 כשמזמינים אדם לעדות, \u0003כיון דרמי עליה\u0004 \u0005[ש\u0006היא \u0005מוטלת עליו],\u0006 \u0003אפילו טובא נמי\u0004 \u0005[הרבה\u0006 זמן, יותר משישים שנה, \u0005גם כן]\u0006 יזכור.","שני עדים החתומים על השטר, \u0003זה,\u0004 עד אחד \u0003אומר: \"\u0004זהו \u0003כתב ידי וזה כתב ידו של חבירי\", וזה,\u0004 העד האחר, \u0003אומר: \"זה כתב ידי וזה כתב ידו של חבירי\" — הרי אלו נאמנין,\u0004 ששניהם מעידים עדות שלימה על שתי החתימות. אם \u0003זה,\u0004 עד אחד, \u0003אומר: \"זה כתב ידי\" וזה,\u0004 העד האחר, \u0003אומר: \"זה כתב ידי\"\u0004 ואין עד אחר המעיד על כתב היד של חבירו — \u0003צריכין לצרף עמהם אחר\u0004 שיעיד על כתב היד של שניהם, שאם לא כן יוצא שכל עד מעיד רק חצי עדות. אלו \u0003דברי רבי. וחכמים אומרים: אינם צריכין לצרף עמהן אחר, אלא נאמן אדם לומר \"זה כתב ידי\",\u0004 ואם היו שני עדים כאלה, זוהי עדות שלימה.","ומסבירים את השיטות: \u0003כשתימצי\u0004 \u0005[כש\u0006תדקדק ו\u0005תמצה]\u0006 \u0003לומר\u0004 את טעמיהם של הדברים, \u0003לדברי רבי\u0004"],["הרי זה משום שלדעתו \u0003על כתב ידן הם מעידים.\u0004 כלומר, עדות זו של העדים היא על אימות חתימתם, ואם כל עד מעיד רק על כתב היד שלו, אין כאן עדות של שני עדים על כל חתימה, ואין בכך כדי לקיים את השטר, אלא אם כן מצטרף לעדות זו עד אחר. \u0003לדברי חכמים,\u0004 הרי זה משום שלדעתם \u0003על מנה שבשטר הם מעידים,\u0004 כלומר, העדים אינם מעידים על אימות חתימתם, אלא על שהם היו נוכחים בשעת מעשה וראו את המאורע, כגון הלוואה של מנה, ולכן יש כאן שני עדים על עצם המעשה, אף על פי שלגבי החתימות יש רק עדות חצויה, ודי בזה כדי לאמת את המעשה עצמו, ואין צורך בעד נוסף לשם כך.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך צריך להבין את הדברים, ומה החידוש בדיוק זה שדייקנו מן השיטות, כאשר אין להבינן אחרת? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003לרבי ספוקי מספקא ליה\u0004 \u0005[מסופק לו\u0006 הדבר\u0005]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003על כתב ידם הם מעידים, או על מנה שבשטר הם מעידים,\u0004 ומשום שהוא חושש שמא העדות היא אכן על כתב ידם, לכן צריך לדעתו לצרף עד נוסף, אחר, על כל חתימה.","\u0003ונפקא מינה\u0004 \u0005[ויוצא מזה]\u0006 הבדל אם בטוח או מסופק הוא בשיטתו, \u0003היכא דמית חד מינייהו\u0004 \u0005[היכן,\u0006 כאשר, \u0005שמת אחד מהם]\u0006 מהעדים החתומים על השטר, \u0003לבעי\u0004 \u0005[שיצטרכו]\u0006 \u0003שנים מן השוק להעיד עליו\u0004 לאשר את חתימת העד שמת, ולא יספיק שיבוא עד אחד בלבד ויצטרף עם העד החי לקיים את החתימה הזו.","ש\u0003אם כן,\u0004 אם יבוא רק עד אחד ויעיד על החתימה הרי \u0003קנפיק נכי ריבעא דממונא אפומא דחד סהדא\u0004 \u0005[יוצא\u0006 הכל, \u0005פחות רבע של הממון, על פיו של עד אחד],\u0006 שכן כשהעדים מעידים על מנה שבשטר, נמצא שמחצית הממון שבשטר נפרעת על פי עדותו של כל אחד מן העדים, אבל כאן שהעד החי מעיד על מחצית הממון בעצמו, וגם על מחצית מן החלק השני של העדות כשמעיד על כתב יד חבירו שמת, נמצא ששלושה רבעים מן הממון יוצאים על פי עד אחד בלבד, והרי אמרה התורה \"על פי שני עדים... יקום דבר\" (דברים יט, טו), שעל פי כל אחד מהעדים יקום חצי דבר ולא יותר, ואם כן, במקרה כזה, כדי לקיים את חתימת העד המת, יצטרכו שני עדים מן השוק.","\u0003ו\u0004מפני שהוא מסופק בדבר, הולך רבי \u0003הכא לחומרא והכא לחומרא\u0004 \u0005[כאן להחמיר וכאן להחמיר],\u0006 שכשני העדים חיים, חוששים שמא באו לאמת את כתב ידם וצריכים לצרף עוד אחד אתם. וכשאחד מת, צריכים שני עדים על כתב ידו, שמא על מנה שבשטר הם מעידים.","על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003רבי מיפשט פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 שהם מעידים על כתב ידם, \u0003בין לקולא\u0004 \u0005[להקל]\u0006 \u0003בין לחומרא\u0004 \u0005[להחמיר].\u0006 ש\u0003אמר רב יהודה אמר רב: שנים החתומין על השטר ומת אחד מהן — צריכין שנים מן השוק להעיד עליו,\u0004 ו\u0003בזו\u0004 שיטת \u0003רבי לקולא\u0004 \u0005[להקל],\u0006 ודי לדעתו בעד אחד שיעיד על שתי החתימות ויצטרף עם העד החי. \u0003ורבנן לחומרא\u0004 \u0005[וחכמים\u0006 דעתם \u0005להחמיר]\u0006 מן הטעם שהזכרנו.","ושואלים למעשה: \u0003ו\u0004לשיטת חכמים \u0003אי ליכא תרי\u0004 \u0005[אם אין שני]\u0006 עדים שיכולים להעיד על שני הכתבים \u0003אלא\u0004 רק \u0003חד\u0004 \u0005[\u0006עד \u0005אחד],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 יעשו\u0005]?\u0006 \u0003אמר אביי: לכתוב חתימת ידיה אחספא\u0004 \u0005[שיכתוב\u0006 העד החי את \u0005חתימת ידו על חרס],\u0006 \u0003ושדי ליה בבי דינא\u0004 \u0005[וישליך,\u0006 יביא \u0005אותו לבית הדין],\u0006 \u0003ומחזקי ליה בי דינא וחזו ליה\u0004 \u0005[ויחזיקו,\u0006 יקיימו, \u0005אותו בית הדין, ורואים אותה]\u0006 אם זו חתימתו, \u0003ולא צריך איהו\u0004 \u0005[יצטרך הוא]\u0006 \u0003לאסהודי אחתימת ידיה\u0004 \u0005[להעיד\u0006 עוד \u0005על חתימת ידו],\u0006 \u0003ואזיל איהו והאי, ומסהדי אאידך\u0004 \u0005[והולך הוא, וזה,\u0006 העד האחר, \u0005ויעידו על\u0006 החתימה \u0005האחרת]\u0006 של העד שמת, שאז מתחלקת העדות היטב בין שני העדים הללו.","ומעירים: \u0003ודוקא\u0004 שיכתוב את חתימתו \u0003אחספא\u0004 \u0005[על חרס],\u0006 \u0003אבל אמגלתא\u0004 \u0005[על מגילה,\u0006 על קלף\u0005]\u0006 \u0003לא\u0004 יכתוב לשם השוואה, ומדוע — \u0003דלמא משכח לה איניש דלא מעלי וכתב עילויה מאי דבעי\u0004 \u0005[שמא ימצא אותה אדם שאינו הגון ויכתוב עליה מה ש\u0006הוא \u0005רוצה],\u0006 שיוסיף ויכתוב שהאיש החתום למטה חייב לו ממון. \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003הוציא עליו כתב ידו שהוא חייב לו,\u0004 אף על פי שאין שני עדים החתומים על כך — הרי זה מחייבו, ו\u0003גובה מנכסים בני חורין.\u0004 שאילו היו חתומים שני עדים, היה יכול להוציא על פיהם גם מנכסים המשועבדים לחוב זה, ומכל מקום מנכסים בני חורין יכול להוציא אפילו בלי עדים, בכתב ידו בלבד. ואם כן חתימת ידו של העד עלולה לחייב אותו, ולכן יכתבנה על חרס שעתיד להישבר ואין דרך לכתוב עליו שטר, ואין לחשוש שיכתבו עליו דברים נוספים.","\u0003אמר רב יהודה אמר שמואל: הלכה כדברי חכמים\u0004 במשנתנו. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הרי זו היא מחלוקת \u0003יחיד ורבים,\u0004 וידוע כי במחלוקת מעין זו \u0003הלכה כרבים!\u0004 ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כלל בידינו ש\u0003הלכה כרבי מחבירו, ו\u0004היינו יכולים לחשוב \u0003אפילו מחביריו,\u0004 ותהא הלכה כמותו אפילו כנגד רבים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הלכה כמותו אלא כנגד יחיד ולא כנגד רבים.","\u0003סימן\u0004 לשמות האמוראים הנזכרים להלן: \u0003נח נד חד\u0004 (ח\u0003נ\u0004נא בר \u0003ח\u0004ייא, הו\u0003נ\u0004א בר יהו\u0003ד\u0004ה, \u0003ח\u0004ייא בר יהו\u0003ד\u0004ה). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חננא בר חייא לרב יהודה, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 שאמר זאת \u0003רב הונא בר יהודה לרב יהודה, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 שאמר זאת \u0003רב חייא בר יהודה לרב יהודה: ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]\u0006 שהלכה כחכמים?","\u0003והא ההוא שטרא דנפיק מבי דינא\u0004 \u0005[והרי אותו שטר שיצא מבית דינו]\u0006 של \u0003מר שמואל והוה כתיב ביה\u0004 \u0005[והיה כתוב בו]\u0006 כך: \u0003מדאתא\u0004 \u0005[מ\u0006כיון \u0005שבא\u0006 לפנינו\u0005]\u0006 \u0003רב ענן בר חייא ואסהיד אחתימות ידיה ואדחד דעמיה\u0004 \u0005[והעיד על חתימת ידו ועל\u0006 חתימתו \u0005של אחד ש\u0006חתם \u0005עמו],\u0006 \u0003ומנו\u0004 \u0005[ומיהו] —\u0006 \u0003רב חנן בר רבה, ומדאתא\u0004 \u0005[ומ\u0006כיון \u0005שבא\u0006 לפנינו\u0005]\u0006 \u0003רב חנן בר רבה ואסהיד אחתימות ידיה ואדחד דעמיה\u0004 \u0005[והעיד על חתימת ידו ועל\u0006 חתימתו \u0005של אחד ש\u0006חתם \u0005עמו],\u0006 \u0003ומנו\u0004 \u0005[ומיהו] —\u0006 \u0003רב ענן בר חייא, אשרנוהי וקימנוהי כדחזי\u0004 \u0005[אשרנוהו וקיימנוהו,\u0006 שטר זה \u0005כראוי].\u0006 ואם סבור שמואל שהלכה כדברי חכמים, די היה שכל אחד יעיד על חתימת ידו בלבד ולשם מה הוצרך להעיד גם על של חבירו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003ההוא שטרא, דיתמי הוה\u0004 \u0005[אותו שטר, של\u0006 טובת \u0005יתומים היה],\u0006 \u0003וחש\u0004 \u0005[וחשש]\u0006 \u0003שמואל לבית דין טועין. וסבר שמואל דלמא איכא דסבירא ליה\u0004 \u0005[שמא יש\u0006 מי \u0005שסבור]:\u0006 בכלל כי \u0003הלכה כרבי מחבירו ולא מחביריו, ו\u0004אולם \u0003בהא\u0004 \u0005[וב\u0006ענין \u0005זה,\u0006 בהלכה זו\u0005]\u0006 הלכה כמותו \u0003אפילו מחביריו,\u0004 ויבוא לפסול את העדות שבה כל עד העיד רק על חתימת ידו, על כן \u0003סבר: אעביד רווחא כי היכי\u0004 \u0005[אעשה\u0006 את הדבר באופן \u0005מרווח כדי]\u0006 ש\u0003לא מפסדי יתמי\u0004 \u0005[יפסידו היתומים],\u0006 כי באופן שכתב, הדבר כשר לכל הדעות.","\u0003אמר רב יהודה אמר שמואל:\u0004 אם היה בא שטר לבית דין, וקיימו אותו בית הדין, ואחר כך הובא שטר זה לגבייה ושוב ערער הלווה וטען שהשטר הוא מזוייף, הרי \u0003עד\u0004 שהיה חתום על השטר מתחילה \u0003ודיין\u0004 שהיה חתום על האישור \u0003מצטרפין\u0004 להעיד על אמיתותו של שטר זה.","\u0003אמר רמי בר חמא: כמה מעליא הא שמעתא\u0004 \u0005[הלכה זו]!\u0006 \u0003אמר רבא: מאי מעליותא\u0004 \u0005[מהי המעלה\u0006 שבהלכה זו\u0005]?\u0006 הרי יש קושי בה: כי \u0003מאי דקא מסהיד סהדא\u0004 \u0005[מה שמעיד העד]\u0006 \u0003לא קא מסהיד דיינא\u0004 \u0005[מעיד הדיין],\u0006 שהרי העד מעיד על חתימת ידו שלו ועל המעשה שראה, \u0003ומאי דקא מסהיד דיינא\u0004 \u0005[ומה שמעיד הדיין]\u0006 \u0003לא קא מסהיד סהדא\u0004 \u0005[מעיד העד],\u0006 שהרי הדיין מעיד שהשטר הזה הובא לפני בית דין ואושר, והעד אינו יכול להעיד על כך, ואם כן אין כאן עדות שלימה כלל!","\u0003אלא כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רמי בר יחזקאל\u0004 מארץ ישראל לבבל, \u0003אמר: לא תציתינהו להני כללי דכייל\u0004 \u0005[אל תקשיבו\u0006 תקבלו, \u0005לאותם כללים שכלל]\u0006 \u0003יהודה אחי משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל,\u0004 ומה שאמר רב יהודה (בר יחזקאל) בשם שמואל שעד ודיין מצטרפים — אין לסמוך על דבריו."],["\u0003איקלע\u0004 \u0005[נזדמן]\u0006 \u0003רבנאי אחוה\u0004 \u0005[אחיו]\u0006 של \u0003ר' חייא בר אבא למזבן שומשמי\u0004 \u0005[למכור שומשומים]\u0006 \u0003ואמר: הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: עד ודיין מצטרפין. אמר אמימר: כמה מעליא\u0004 \u0005[מעולה]\u0006 \u0003הא שמעתא\u0004 \u0005[הלכה זו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: משום דקלסה אבוה דאמך\u0004 \u0005[ששיבח אותה אבי אמך],\u0006 רמי בר חמא, \u0003את נמי מקלסת לה\u0004 \u0005[גם אתה משבח אותה]?!\u0006 \u0003כבר פרכה\u0004 (שבר אותה) \u0003רבא\u0004 את המימרה הזו, והוכיח שאינה נכונה.","\u0003אמר רב ספרא אמר ר' אבא אמר רב יצחק בר שמואל בר מרתא אמר רב הונא, ואמרי ליה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 וממשיכים את מסורת השמועה \u0003אמר רב הונא אמר רב: שלשה\u0004 דיינים \u0003שישבו לקיים את השטר, שנים\u0004 מהם \u0003מכירין\u0004 בעצמם את \u0003חתימות ידי\u0004 ה\u0003עדים, ואחד\u0004 מהם \u0003אינו מכיר. עד שלא חתמו\u0004 שני דיינים אלה לקיים את השטר — שניהם \u0003מעידין בפניו,\u0004 בפני השלישי שאינו מכיר, כעדים המכירים את החתימות, \u0003ו\u0004אף הוא \u0003חותם\u0004 עמהם על סמך עדות זו. אולם \u0003משחתמו\u0004 שני הדיינים — \u0003אין מעידין בפניו וחותם.\u0004 כיון שחתימתם הראשונה לא היתה כהוגן, שהרי לא היה כאן בית דין שאישר את הדברים.","ושואלים: \u0003ומי כתבינן\u0004 \u0005[והאם כותבים אנו]\u0006 אישור לשטר לפני שהכירו כל הדיינים חתימת ידי העדים, ואיך כתבו כאן את האישור? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: האי אשרתא דדייני דניכתב מקמיה דניחוו סהדי אחתימת ידייהו\u0004 \u0005[אישור זה,\u0006 קיום שטר, \u0005של דיינים שנכתב לפני שהראו העדים על חתימת ידם]\u0006 \u0003פסולה,\u0004 ואפילו העידו העדים על חתימתם אחרי כתיבת האישור, \u0003דמתחזי כשקרא\u0004 \u0005[שנראה\u0006 הדבר \u0005כשקר],\u0006 כי כאשר כתבו את מה שכתבו עדיין לא ידעו שהם יכולים לאשר את השטר, ובוודאי \u0003הכא נמי מתחזי כשקרא\u0004 \u0005[כאן גם כן נראה\u0006 הדבר \u0005כשקר],\u0006 שהדיינים לא היו רשאים לכתוב אישור זה לפני שהדיין השלישי יכיר את החתימות!","\u0003אלא אימא\u0004 \u0005[אמור],\u0006 תקן את הדברים בלשון זו: \u0003עד שלא כתבו\u0004 שני הדיינים האחרים את האישור — \u0003מעידין בפניו וחותם, משכתבו — אין מעידין בפניו וחותם,\u0004 שהכתיבה היתה שלא כהוגן.","ומעירים: מהלכה זו שאמר רב הונא \u0003שמע מינה תלת\u0004 \u0005[למד ממנה שלושה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003עד נעשה דיין,\u0004 שהרי שני הדיינים שהכירו חתימת העדים היו גם עדים ובכל זאת יכולים הם לחתום בתורת דיינים, ואין אומרים שהם נחשבים כנוגעים בדבר ופסולים; \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 ש\u0003דיינין המכירין חתימות ידי עדים אינן צריכין\u0004 עדים אחרים \u0003להעיד בפניהם,\u0004 ודי להם בידיעת עצמם; \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 גם ש\u0003דיינין שאין מכירין חתימות ידי עדים — צריכין להעיד בפני כל אחד ואחד\u0004 מהם, ואין אחד מהם יכול לסמוך על ידיעתם של האחרים.","על מסקנות אלו \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: בשלמא\u0004 \u0005[נניח],\u0006 עניין זה ש\u0003עד נעשה דיין,\u0004 אכן \u0003שמעינן מינה\u0004 \u0005[לומדים אנו מכאן],\u0006 \u0003אלא\u0004 ש\u0003דיינין המכירין חתימות ידי עדים אין צריכין להעיד בפניהם\u0004 — אין להוכיח מכאן, כי \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא לך\u0004 \u0005[\u0006יכול אני \u0005לומר לך]\u0006 ש\u0003צריכין\u0004 שיעידו בפניהם, ולא די במה שמכירים הם מעצמם וצריך שתהיה עדות ממש, \u0003ו\u0004אולם \u0003שאני הכא דקא מקיימא הגדה בחד\u0004 \u0005[שונה כאן שמתקיימת הגדת\u0006 עדות \u0005באחד],\u0006 שהרי בבית דין זה היתה כבר הגדת עדות, לפי ששני הדיינים העידו בפני השלישי שלא הכיר את החתימות, ושמא בלא עדות בכלל אכן אין לעשות דין.","\u0003ו\u0004עוד: מה שאמרנו ש\u0003דיינין שאין מכירין חתימות ידי עדים צריכין להעיד בפני כל אחד ואחד, דלמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא לך\u0004 \u0005[\u0006יכול אני \u0005לומר לך]\u0006 שבדרך כלל \u0003אין צריכין\u0004 להעיד בפני כל אחד ואחד, \u0003ושאני הכא דלא קא מקיימא\u0004 \u0005[ושונה כאן שאין מתקיימת]\u0006 \u0003הגדה\u0004 של עדות \u0003כלל\u0004 אם לא יעידו בפניו, אבל אם היתה הגדת עדות מסויימת, שמא הדיין השלישי יכול להצטרף גם בלא לדעת את כל הפרטים, ויכול הוא לסמוך על שני הדיינים האחרים.","מספרים: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' אבא וקאמר לה להא שמעתא\u0004 \u0005[ואמר את המימרה הזו]\u0006 של \u0003עד נעשה דיין, איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב ספרא לר' אבא\u0004 ממה ששנינו במשנה בעניין עדות על חידוש הלבנה: \u0003ראוהו\u0004 את מולד הירח \u0003שלשה, והן\u0004 עצמם \u0003בית דין — יעמדו שנים\u0004 מהם כעדים \u0003ויושיבו\u0004 שניים \u0003מחבריהם אצל היחיד\u0004 (אחד מהם), \u0003ויעידו\u0004 השניים \u0003בפניהם, ויאמרו\u0004 אז הדיינים את הנוסח המקובל לקידוש החודש: \u0003\"מקודש החדש, מקודש\". שאין היחיד נאמן על ידי עצמו\u0004 לקדש החודש, ולכן אינו יכול לקדש לבדו, וצריכים שניים אחרים לבוא ולהצטרף אתו כדיינים. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003עד נעשה דיין — למה לי כולי האי\u0004 \u0005[כל זה]?\u0006 \u0003ליתבו בדוכתייהו וליקדשי\u0004 \u0005[שישבו\u0006 השלושה \u0005במקומם ושיקדשו]\u0006 שהרי הם העדים בדבר, והם עצמם יהיו הדיינים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא: \u0003אף לדידי קשיא לי\u0004 \u0005[גם לי\u0006 היה \u0005קשה\u0006 הדבר\u0005]\u0006 \u0003ושאילתיה\u0004 \u0005[ושאלתי\u0006 אותה\u0005]\u0006 שאלה \u0003לרב יצחק בר שמואל בר מרתא, ורב יצחק\u0004 שאל אותה \u0003לרב הונא, ורב הונא\u0004 שאל אותה \u0003לחייא בר רב, וחייא בר רב\u0004 שאל אותה \u0003לרב, ואמר להו\u0004 \u0005[להם]\u0006 רב בתשובה לשאלה זו: \u0003הנח לעדות החדש\u0004 שהיא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 ובעדות מן התורה מקפידים יותר, \u0003ו\u0004אילו \u0003קיום שטרות\u0004 אינו אלא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 ולכן בענין זה עד נעשה דיין.","\u0003אמר ר' אבא אמר רב הונא אמר רב: שלשה שישבו\u0004 כבית־דין \u0003לקיים את השטר, וקרא ערער\u0004 (ערעור) \u0003על אחד מהן\u0004 שהוא פסול. \u0003עד שלא חתמו\u0004 על האישור — \u0003מעידין עליו\u0004 שני הדיינים האחרים שהוא כשר, \u0003ו\u0004גם הוא \u0003חותם. משחתמו\u0004 כבר — \u0003אין מעידין עליו וחותם.\u0004 שכיון שכבר חתמו, הרי הם נוגעים בעדות, שאינם רוצים להודות שהיה זה מושב בית־דין בלתי ראוי.","ומבררים: \u0003ערער דמאי\u0004 \u0005[ערעור של מה],\u0006 באיזה ערעור על הדיין מדובר כאן? \u0003אי ערער דגזלנותא\u0004 \u0005[אם\u0006 היה זה \u0005ערעור של\u0006 פסול \u0005גזלנות]\u0006 שבאו וטענו כנגדו שהוא גזלן —"],["\u0003תרי ותרי נינהו\u0004 \u0005[שניים ושניים הם]\u0006 ואין שני הדיינים יכולים לבטל לגמרי את העדות הראשונה שפסלה אותו. \u0003אי ערער\u0004 \u0005[אם\u0006 הכוונה \u0005לערעור]\u0006 של \u0003פגם משפחה,\u0004 כגון שטוענים שהוא עבד, ופסול לדון, הרי \u0003גלוי מלתא\u0004 \u0005[דבר]\u0006 \u0003בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004 שעתיד להתברר, ואין צורך לכך בעדות גמורה, ומדוע ייפסלו לאחר שחתמו? ומשיבים: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי המדובר ב\u0003ערער דגזלנותא\u0004 \u0005[ערעור של גזלנות],\u0006 \u0003וקאמרי הני\u0004 \u0005[ואומרים אלה]\u0006 הדיינים: \u0003ידעינן ביה דעבד\u0004 \u0005[יודעים אנו בו שעשה]\u0006 \u0003תשובה\u0004 ומעכשיו כשר הוא, ואין כאן איפוא סתירה בין שתי כיתות העדים.","\u0003אמר ר' זירא: הא מלתא\u0004 \u0005[דבר זה]\u0006 \u0003מר' אבא שמיע לי\u0004 \u0005[שמעתי אותו],\u0006 \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 \u0003ר' אבא\u0004 ש\u0003מן\u0004 העיר \u0003עכו שכחתה\u0004 \u0005[הייתי שוכח אותו],\u0006 שהוא הזכירני הלכה זו. ומהי הלכה זו? \u0003שלשה שישבו\u0004 כבית־דין \u0003לקיים את השטר ומת אחד מהם\u0004 לפני שחתם — \u0003צריכין למיכתב\u0004 \u0005[לכתוב]\u0006 נוסח זה: \u0003\"במותב תלתא הוינא, וחד ליתוהי\u0004 \u0005[במושב שלושה היינו ואחד איננו]\u0006\".","\u0003אמר רב נחמן בר יצחק: ואי כתב ביה\u0004 \u0005[ואם כתב בו]\u0006 בשטר הקיום: \u0003\"שטרא דנן נפק לקדמנא, בי דינא\u0004 \u0005[שטר זה יצא לפנינו, בית הדין]\u0006\u0003\"\u0004\u0005—\u0006 \u0003תו לא צריך\u0004 \u0005[שוב אינו צריך]\u0006 להוסיף ששלושה היו, כי סתם בית דין הוא של שלושה דיינים. ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003בית דין חצוף הוא, וכ\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: שנים שדנו,\u0004 אף שלא נהגו כראוי, מכל מקום \u0003דיניהם דין, אלא שנקרא בית דין חצוף.\u0004 ואם כתוב סתם \"בית דין\", אפשר לחשוב שהיה זה בית דין חצוף!","ומשיבים: \u0003דכתיב ביה\u0004 \u0005[שכתוב בו]:\u0006 \u0003\"\u0004כגון \u0003בי דינא דרבנא\u0004 \u0005[בית הדין של רבינו]\u0006 \u0003אשי\",\u0004 ומן הסתם בית דין כזה נוהג כראוי. ושואלים: \u0003ודלמא רבנן דבי\u0004 \u0005[ושמא חכמים של בית]\u0006 \u0003רב אשי כ\u0004דעת \u0003שמואל סבירא להו\u0004 \u0005[סבורים הם]\u0006 ועשו בית דין חצוף! ומשיבים: \u0003דכתיב ביה\u0004 \u0005[שכתוב בו]:\u0006 \u0003\"ואמר לנא רבנא\u0004 \u0005[לנו רבינו]\u0006 \u0003אשי\",\u0004 שבמקרה כזה ודאי אין לחשוב שעשו שלא כדין.","\u0003האשה שאמרה: \"אשת איש הייתי ו\u0004עכשיו \u0003גרושה אני\" — נאמנת\u0004 להינשא. \u0003שהפה שאסר,\u0004 היא עצמה שאמרה שהיתה נשואה, \u0003הוא\u0004 גם \u0003הפה שהתיר. ואם יש עדים שהיתה אשת איש והיא אומרת: \"גרושה אני\" — אינה נאמנת,\u0004 שכן עדות אחרים היא שאסרתה. וכן אם \u0003אמרה: \"נשביתי\u0004 על ידי גוים, \u0003ו\u0004אף על פי כן עדיין \u0003טהורה אני\",\u0004 שלא נאנסה בהיותה שבויה ומותרת להינשא לכהן — \u0003נאמנת, שהפה שאסר הוא הפה שהתיר. ואם יש עדים שנשבית והיא אומרת: \"טהורה אני\" — אינה נאמנת. ו\u0004אולם \u0003אם\u0004 אמרה \"נשביתי וטהורה אני\" והשיאוה על פי דבריה, ו\u0003משנשאת באו עדים\u0004 שנשבית — \u0003הרי זו לא תצא.\u0004","\u0003אמר רב אסי: מנין ל\u0004הלכה זו, ש\u0003הפה שאסר הוא הפה שהתיר מן התורה? שנאמר: \"את בתי נתתי לאיש הזה לאשה\"\u0004 (דברים כב, טז). כיון שאמר \u0003\"לאיש\" — אסרה\u0004 על כל העולם כולו, שהרי אמר שהשיא אותה ולא פירש למי, ולאחר שאמר \u0003\"הזה\" — התירה\u0004 לבעלה.","ושואלים: לדבר זה \u0003למה לי קרא\u0004 \u0005[כתוב]\u0006 מיוחד ללמד על זה? הלא \u0003סברא היא: הוא אסרה והוא שרי לה\u0004 \u0005[התיר אותה]!\u0006 שהלא דיבורו הוא המקור היחיד לידיעתנו, הן לאסור והן להתיר. \u0003אלא כי איצטריך קרא\u0004 \u0005[כאשר הוצרך כתוב\u0006 זה\u0005]\u0006 של \"לאיש הזה\" הרי זה \u0003ל\u0004כפי שאמר \u0003רב הונא אמר רב.\u0004 ש\u0003אמר רב הונא אמר רב: מנין לאב שנאמן לאסור את בתו\u0004 הקטנה \u0003מן התורה — שנאמר: \"את בתי נתתי לאיש\"\u0004 ומכאן משמע שסומכים על דיבורו בענין זה ונאסרת על כולם. ושואלים: לפי הסברה של רב הונא, המלה \u0003\"הזה\" למה לי?\u0004","ומסבירים: \u0003מיבעי ליה לכדתני\u0004 \u0005[נצרך לו\u0006 הדבר \u0005לכ\u0006 פי \u0005ששנה]\u0006 \u0003ר' יונה. דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' יונה\u0004 ברייתא זו: נאמר בפרשה של מוציא שם רע \u0003\"את בתי נתתי לאיש הזה\"\u0004 ויש להדגיש: \u0003\"הזה\" — ולא ליבם,\u0004 שדין מוציא שם רע הוא דווקא בבעל, ולא ביבם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003האשה שאמרה \"אשת איש אני\" וחזרה ואמרה \"פנויה אני\" — נאמנת.\u0004 ומקשים: \u0003והא שוויה לנפשה\u0004 \u0005[והרי עשתה את עצמה]\u0006 כ\u0003חתיכה דאיסורא\u0004 \u0005[של איסור],\u0006 שכיון שאמרה שהיא אשת איש, נמצא שאסרה את עצמה לכל, וכיצד יכולה היא לחזור ולהתיר איסור זה? ומשיבים: \u0003אמר רבא בר רב הונא: כגון שנתנה אמתלא\u0004 (תירוץ, הסבר) \u0003לדבריה\u0004 מדוע אמרה קודם שאשת איש היתה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אמרה \"אשת איש אני\" וחזרה ואמרה \"פנויה אני\" — אינה נאמנת, ואם נתנה אמתלא לדבריה\u0004 הראשונים — \u0003נאמנת.\u0004","\u0003ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003באשה אחת גדולה\u0004 (חשובה) \u0003שהיתה גדולה בנוי\u0004 (ביופי), \u0003וקפצו עליה\u0004 (חיזרו אחריה) \u0003בני אדם\u0004 רבים \u0003לקדשה. ואמרה להם \"מקודשת אני\u0004 כבר \u0003\". לימים עמדה וקידשה את עצמה. אמרו לה חכמים: מה ראית לעשות כן?\u0004 שהרי אמרת שמקודשת את?! \u0003אמרה להם: בתחלה שבאו עלי\u0004 לשאת אותי \u0003אנשים שאינם מהוגנים — אמרתי \"מקודשת אני\"\u0004 כדי להיפטר מהם, \u0003עכשיו שבאו עלי אנשים מהוגנים — עמדתי וקדשתי את עצמי\u0004 לאחד מהם. ומעירים: \u0003וזו הלכה העלה\u0004 (הביא) \u0003רב אחא שר הבירה לפני חכמים באושא\u0004 (ששם היה מושב הסנהדרין) \u0003ואמרו: אם נתנה אמתלא לדבריה — נאמנת.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003שמואל מרב:\u0004 אשה ש\u0003אמרה\u0004 לבעלה \u0003\"טמאה אני\"\u0004 בנדה, \u0003וחזרה ואמרה \"טהורה אני\" מהו?\u0004 האם סומכים על דבריה האחרונים, או שמא נאמר שעשתה עצמה כחתיכת איסור? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף בזו, אם נתנה\u0004"],["\u0003אמתלא לדבריה — נאמנת.\u0004 ומספרים: \u0003תנא מיניה\u0004 \u0005[שנה ממנו]\u0006 וחזר על הלכה זו \u0003ארבעים זימנין\u0004 \u0005[פעמים]\u0006 כדי לזוכרה. ומוסיפים: \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 למרות שלמד ממנו, \u0003לא עבד\u0004 \u0005[עשה]\u0006 \u0003שמואל עובדא בנפשיה\u0004 \u0005[מעשה בעצמו]\u0006 כשאירע לו דבר כזה עם אשתו, ולא סמך על היתר זה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שנים,\u0004 שני עדים, \u0003אומרים: \"מת\u0004 הבעל \u0003\", ושנים,\u0004 אחרים, \u0003אומרים: \"לא מת\".\u0004 או, \u0003שנים אומרים: \"נתגרשה\u0004 אשה זו \u0003\", ושנים אומרים: \"לא נתגרשה\" — הרי זו לא תנשא,\u0004 שהרי אין לנו עדות ברורה להתירה. \u0003ואם נשאת\u0004 כבר — \u0003לא תצא. ר' מנחם בר יוסי אומר: תצא.\u0004 הוסיף ו\u0003אמר ר' מנחם בר יוסי: אימתי אני אומר תצא — בזמן שבאו עדים\u0004 האוסרים אותה, \u0003ואחר כך נשאת, אבל\u0004 אם \u0003נשאת ואחר כך באו עדים — לא תצא,\u0004 שאין מוציאים אותה מבעלה רק משום הספק.","ושואלים לעצם הענין: \u0003מכדי תרי ותרי נינהו\u0004 \u0005[הרי שניים ושניים הם]\u0006 וכיצד יכול האיש שנשאה להשאיר אותה אצלו, הלא \u0003הבא עליה באשם תלוי קאי\u0004 \u0005[עומד],\u0006 שהרי ספק הוא אם האשה הזו היא אשת איש, ואם יבוא עליה יתחייב באשם תלוי, כדין כל העושה דבר שהוא ספק איסור שחייבים עליו כרת אם עשאוהו במזיד! \u0003אמר רב ששת: כגון שנשאת לאחד מעדיה\u0004 שאמרו שהיא מותרת, והוא הרי בטוח בהתירה, ולגביו אין כאן ספק. ושואלים: הלא \u0003היא גופה\u0004 \u0005[עצמה]\u0006 \u0003ב\u0004קרבן \u0003אשם תלוי קימא\u0004 \u0005[עומדת]\u0006 שהרי היא איננה יודעת מה הן העובדות, ושמא לא מת בעלה! ומשיבים: \u0003באומרת: \"ברי\u0004 \u0005[ברור]\u0006 \u0003לי\u0004 הדבר שמת \u0003\"\u0004.","\u0003אמר ר' יוחנן, שנים אומרים: \"מת\"\u0004 בעלה של אשה זו, \u0003ושנים אומרים: \"לא מת\" — הרי זו לא תנשא, ואם נשאת — לא תצא. שנים אומרים: \"נתגרשה\", ושנים אומרים: \"לא נתגרשה\" — הרי זו לא תנשא, ואם נשאת — תצא.\u0004","ושואלים: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 ה\u0005התחלה ו\u0006ב\u0005מה שונה הסוף]\u0006 שבמקרה הראשון אם נישאת — לא תצא, ובשני — תצא? \u0003אמר אביי: תרגמה\u0004 \u0005[הסבר אותה]\u0006 \u0003בעד אחד,\u0004 לא היו שתי דעות של שני עדים המכחישות זו את זו, אלא כל אחת מן העדויות היתה בעד אחד. וכך יש להבין את הדברים: ש\u0003עד אחד\u0004 ה\u0003אומר \"מת\",\u0004 הרי \u0003הימנוהו רבנן כבי תרי\u0004 \u0005[האמינו לו חכמים כשניים],\u0006 שעד אחד נאמן להעיד שמת הבעל כדי שתנשא אשתו. \u0003וכ\u0004דברי \u0003עולא.\u0004 ש\u0003אמר עולא: כל מקום שהאמינה תורה עד אחד,\u0004 כגון בעדות שמת הבעל — \u0003הרי כאן שנים,\u0004 שעדות זו נחשבת כעדות גמורה של שני עדים, \u0003ו\u0004אם כן \u0003האי דקאמר\u0004 \u0005[וזה,\u0006 העד האחר, \u0005שאמר]:\u0006 \u0003\"לא מת\" — הוה ליה חד\u0004 \u0005[הרי הוא\u0006 רק \u0005אחד],\u0006 שהרי על עדות כזו לא האמינו חכמים לעד אחד כשנים \u0003ואין דבריו של\u0004 עד \u0003אחד\u0004 מתקבלים \u0003במקום\u0004 (כנגד) \u0003שנים\u0004 ולכך לא תצא.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, שעדות העד המתיר נחשבת כעדות שנים, ואין עד אחד יכול לסותרה, אם כן \u0003אפילו לכתחלה נמי\u0004 \u0005[גם כן]\u0006 תינשא! ומשיבים: הטעם שלא תינשא לכתחילה הוא \u0003משום\u0004 הדברים שאמר \u0003רב אסי.\u0004 ש\u0003אמר רב אסי:\u0004 בכל מקרה של ספק, כגון זה, יש לקרוא עליו את הכתוב: \u0003\"הסר ממך עקשות פה ולזות שפתים הרחק ממך\"\u0004 (משלי ד, כד), שגם אם אין הדבר אסור מן הדין, אבל יש בו טעם לפגם.","ואילו ב\u0003סיפא\u0004 \u0005[\u0006ב\u0005סופה],\u0006 בענין גרושין, אם \u0003עד אחד אומר: \"נתגרשה\" ועד אחד אומר: \"לא נתגרשה\"\u0004 הלא \u0003תרוייהו\u0004 \u0005[שניהם]\u0006 \u0003באשת איש קמסהדי\u0004 \u0005[הם מעידים],\u0006 שלדברי שניהם היתה אשת איש, \u0003ו\u0004אם כן \u0003האי דקאמר\u0004 \u0005[זה שאומר]\u0006 ש\u0003נתגרשה\u0004 וכבר אינה אשת איש, \u0003הוה ליה חד\u0004 \u0005[הרי הוא אחד]\u0006 \u0003ואין דבריו של אחד במקום שנים,\u0004 ולכן, אפילו אם נישאת — תצא. זהו תירוצו של אביי.","\u0003רבא אמר: לעולם\u0004 תפרש \u0003תרי ותרי נינהו\u0004 \u0005[שניים ושניים הם],\u0006 כפשטות דברי ר' יוחנן. \u0003ו\u0004אולם \u0003ראה\u0004 (קיבל, הסכים) \u0003ר' יוחנן\u0004 את \u0003דבריו של ר' מנחם בר יוסי בגרושין, ולא ראה\u0004 את דבריו \u0003במיתה.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל? ומסבירים: לענין \u0003מיתה\u0004 אפשר יותר לסמוך על האשה, שהרי אם יתברר שהבעל חי ויחזור לכאן \u0003אינה יכולה מכחשתו\u0004 לומר שאינו חי, ולכן יש לסמוך גם עליה שהיא מדקדקת בבירור טיב העדות. ואילו ב\u0003גרושין\u0004 חוששים שמא אפילו כשיבוא הבעל ויאמר שלא גירש אותה — \u0003יכולה מכחשתו,\u0004 ואם תתיר לה להינשא, היא לא תדקדק בטיב העדות, שכן היא אומרת לעצמה: אנשא על פי עדות זו ואם לבסוף יבוא בעלי ויאמר שלא גרשני — אכחישנו. ולכן קנסו אותה שתצא.","ושואלים: \u0003ומי חציפה כולי האי\u0004 \u0005[והאם חצופה\u0006 אשה \u0005כל כך]\u0006 שתשקר לבעלה בפניו ותאמר שגירש אותה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב המנונא: האשה שאמרה לבעלה \"גרשתני\"\u0004 — הרי היא \u0003נאמנת.\u0004 ומדוע? — \u0003חזקה\u0004 היא: \u0003אין אשה מעיזה פניה בפני בעלה!\u0004 ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאינה מעיזה פניה אמורים דווקא \u0003היכא דליכא\u0004 \u0005[היכן שאין]\u0006 \u0003עדים דקא מסייעי\u0004 \u0005[שמסייעים]\u0006 \u0003לה\u0004 לדבריה, \u0003אבל היכא דאיכא\u0004 \u0005[היכן שיש]\u0006 \u0003עדים דקא מסייעי\u0004 \u0005[שמסייעים]\u0006 \u0003לה — מעיזה ומעיזה.\u0004","\u0003רב אסי אמר,\u0004 יש להסביר את דברי ר' יוחנן באופן אחר: \u0003כגון דאמרי\u0004 \u0005[שאומרים]\u0006 ה\u0003עדים: \"עכשיו מת\",\u0004 או שאומרים: \u0003\"עכשיו גירשה\".\u0004 והטעם לחלק בין מיתה לגירושין הוא כך: \u0003מיתה ליכא לברורה\u0004 \u0005[אין\u0006 אפשרות \u0005לבררה],\u0006 שאין דרך לברר עתה את הדבר, ולכן לכתחילה לא תינשא, ואם נישאה, לא תצא. \u0003גירושין איכא לברורה\u0004 \u0005[יש\u0006 דרך \u0005לברר],\u0006 \u0003דאמרינן לה\u0004 \u0005[שאומרים אנו לה]\u0006 לאשה: \u0003אם איתא דהכי הוה\u0004 \u0005[אם\u0006 יש בדברייך \u0005שכך היה]\u0006 שגירשך, \u0003אחזי לן\u0004 \u0005[הראי לנו]\u0006 את \u0003גיטיך,\u0004 כי מאחר שהעדים מעידים שהיה הדבר עכשיו, אין מסתבר שאיבדה את הגט, ויש להניח שהעדים שאמרו שנתגרשה הם עדי שקר, ולכן תצא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שנים אומרים: \"נתקדשה\u0004 אשה זו \u0003\"\u0004\u0003ושנים אומרים: \"לא נתקדשה\" — הרי זו לא תנשא\u0004 לאחר, \u0003ואם נשאת — לא תצא. שנים אומרים: \"נתגרשה\" ושנים אומרים: \"לא נתגרשה\" — הרי זו לא תנשא, ואם נשאת\u0004 בכל זאת — \u0003תצא.\u0004"],["\u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה\u0006 ה\u0005התחלה\u0006 בדין קידושין \u0005ומה שונה\u0006 ה\u0005סוף,\u0006 בגירושין\u0005],\u0006 שיש הבדל בדיניהם?","\u0003אמר אביי: תרגמה\u0004 \u0005[הסבר אותה]\u0006 שאין ההכחשה בין שתי כתות של עדים, כמשמעות הברייתא, אלא \u0003בעד אחד,\u0004 כיצד? \u0003עד אחד אומר \"נתקדשה\" ועד אחד אומר \"לא נתקדשה\"\u0004 — הלא \u0003תרוייהו\u0004 \u0005[שניהם]\u0006 \u0003בפנויה קמסהדי\u0004 \u0005[הם מעידים],\u0006 שלדברי שניהם היתה קודם פנויה, \u0003והאי דקאמר\u0004 \u0005[וזה שאומר]\u0006 \u0003\"נתקדשה\", הוה ליה חד\u0004 \u0005[הרי הוא אחד],\u0006 \u0003ואין דבריו של אחד במקום\u0004 (כנגד) \u0003שנים,\u0004 ולכן בטלה עדותו, ואם נישאה, לא תצא.","\u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף,\u0006 בגירושין\u0005]\u0006 \u0003עד אחד אומר \"נתגרשה\" ועד אחד אומר \"לא נתגרשה\" תרוייהו\u0004 \u0005[שניהם]\u0006 \u0003באשת איש קמסהדי\u0004 \u0005[הם מעידים],\u0006 שלדברי שניהם היתה נשואה, \u0003והאי דקאמר\u0004 \u0005[וזה שאומר]\u0006 \u0003\"נתגרשה\" הוה ליה חד\u0004 \u0005[הרי הוא אחד],\u0006 \u0003ואין דבריו של אחד במקום שנים\u0004 ולכן תצא.","\u0003רב אשי אמר: לעולם\u0004 מדובר כמשמעות הלשון ב\u0003תרי ותרי\u0004 \u0005[\u0006ב\u0005שניים ושניים],\u0006 \u0003ואיפוך\u0004 \u0005[והפוך]\u0006 את הדינים בראש ובסוף. ובאופן זה: \u0003שנים אומרים \"ראינוה שנתקדשה\", ושנים אומרים \"לא ראינוה שנתקדשה\" — הרי זו לא תנשא, ואם נשאת — תצא.\u0004","ותוהים: אם במקרה כזה מדובר, הרי \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 מובן מאליו שתצא משום ש\u0003\"לא ראינוה\" אינה ראיה,\u0004 ואין כאן עדות כלל להתירה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא \u0003דדיירי\u0004 \u0005[\u0006כאשר \u0005גרים]\u0006 האשה והעדים \u0003בחצר אחד. מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אם איתא\u0004 \u0005[יש]\u0006 אמת בדבר ש\u0003נתקדשה — קלא אית לה למילתא\u0004 \u0005[קול יש לו לדבר],\u0006 והשכנים היו יודעים, בדבר ואם לא ראו שנתקדשה — משמע שלא היה כן, וכשאומרים \"לא ראינוהו שנתקדשה\" הרי זה כאילו אומרים בבירור \"לא נתקדשה\", על כן \u0003קא משמע לן דעבדי אינשי דמקדשי בצנעא\u0004 \u0005[השמיע לנו שעשויים אנשים שמקדשים בצינעה]\u0006 בלא שידעו על כך אחרים ואפילו אלו הגרים סמוך להם.","\u0003סיפא\u0004 \u0005[\u0006ב\u0005סופה]\u0006 של הברייתא מדובר כאשר \u0003שנים אומרים \"ראינוה שנתגרשה\", ושנים אומרים \"לא ראינוה שנתגרשה\" — הרי זו לא תנשא, ואם נשאת — לא תצא.\u0004 ושואלים שוב: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 שהרי אף כאן לא היתה עדות ממשית שלא נתגרשה. ומשיבים: \u0003אף על גב דדיירי\u0004 \u0005[אף על פי ש\u0006האשה והעדים \u0005גרים]\u0006 \u0003בחצר אחד,\u0004 ואם אמת היה הדבר היו אמורים העדים לדעת מכך, ומכיון שאומרים \"לא ראינוה שהתגרשה\" כאילו אמרו \"לא נתגרשה\", מכל מקום אין זו נחשבת כעדות. ושואלים: \u0003היינו הך\u0004 \u0005[זו היא זו]\u0006 הרי העקרון בהלכה זו שהגרים סמוך לא בקיאים במתרחש, הוא כמו ההלכה הקודמת, ולא נוסף שום חידוש על ידי הלכה זו!","ומסבירים: יש בכך חידוש מסויים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קדושין הוא דעבידי אינשי דמקדשי בצנעא\u0004 \u0005[שעשויים אנשים שיקדשו בצינעה]\u0006 ואינם עושים זאת בפרסום, \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003גירושין אם איתא דאיגרשא\u0004 \u0005[יש\u0006 אמת בדבר \u0005שנתגרשה] —\u0006 \u0003קלא אית לה למילתא\u0004 \u0005[קול,\u0006 פירסום, \u0005יש לו לדבר]\u0006 שכרגיל גירושין באים לאחר קטטות, ומסתבר שהכל יודעים על כך, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דעבידי אינשי דמקדשי ודמגרשי בצנעא\u0004 \u0005[שעשויים אנשים שיקדשו ויגרשו בצינעה]\u0006 ואין להביא ראייה ממה שלא ראו.","שנינו במשנה: \u0003ואם משנשאת באו עדים — לא תצא.\u0004 מאחר שהמשנה מדברת בשתי הלכות, בגרושה ובשבויה, לא ברור למה מתייחס משפט אחרון זה. ואכן נחלקו בדבר; \u0003ר' אושעיא מתני לה ארישא\u0004 \u0005[היה שונה אותה על ראש]\u0006 המשנה, באשה שטוענת שנישאה ונתגרשה, \u0003רבה בר אבין מתני לה אסיפא\u0004 \u0005[היה שונה אותה על סופה]\u0006 באשה שאומרת שנשבתה וטהורה היא.","ומעירים: \u0003מאן דמתני לה ארישא\u0004 \u0005[מי ששונה אותה,\u0006 את ההלכה הזו, \u0005על ראשה\u0006 של המשנה\u0005]\u0006 בענין גירושין — \u0003כל שכן\u0004 שהוא שונה אותה \u0003אסיפא\u0004 \u0005[על סופה]\u0006 בענין שבויה, שכן \u0003בשבויה הקילו\u0004 בכלל, שהרי אין איסורה אלא מפני חשש וספק בלבד. \u0003ומאן דמתני לה אסיפא\u0004 \u0005[ו\u0006אולם \u0005מי ששונה אותה על הסוף\u0006 בשבויה\u0005],\u0006 \u0003אבל ארישא\u0004 \u0005[על ראשה\u0006 של המשנה\u0005]\u0006 — \u0003לא.\u0004","ומציעים הסבר לשיטות אלה: \u0003לימא\u0004 \u0005[\u0006שמא \u0005נאמר]\u0006 ש\u0003ב\u0004דברי \u0003רב המנונא קמיפלגי\u0004 \u0005[הם חלוקים],\u0006 \u0003דמאן דמתני לה ארישא\u0004 \u0005[שמי ששונה אותה על ראש\u0006 המשנה\u0005]\u0006 וסבור שבדיעבד אם נישאה לא תצא, \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את דברי \u0003רב המנונא,\u0004 האומר שאשה האומרת לבעלה \"גירשתני\" — נאמנת, שאין אשה מעיזה פניה בפני בעלה לומר שגירש אותה אילולי היה נכון הדבר, ולכן סבור הוא שאף במקרה זה יש בעצם להאמין לה שהיא גרושה. \u0003ומאן דמתני לה אסיפא\u0004 \u0005[ומי ששונה אותה על הסוף]\u0006 ומתיר בשבויה לאחר שנישאה, אך סבור שמחמירים בגרושה, \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003רב המנונא.\u0004","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא אית להו\u0004 \u0005[הכל יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003רב המנונא. והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה\u0006 הם \u0005חלוקים]\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 האוסר בגרושה, \u0005סבור]:\u0006 \u0003כי איתמר\u0004 \u0005[כאשר נאמרו]\u0006 דברי \u0003רב המנונא\u0004 הוא שדווקא כאשר אומרת לו \u0003בפניו,\u0004 שאז אינה מעיזה, \u0003אבל\u0004 כשאומרת \u0003שלא בפניו\u0004 שנתגרשה — \u0003מעיזה. ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר: שלא בפניו נמי\u0004 \u0005[גם כן]\u0006 \u0003אינה מעיזה,\u0004 ולכן יש לסמוך על טענתה שהיא גרושה.","עוד שנינו במשנה: \u0003ואם משנשאת באו עדים\u0004 — לא תצא. \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל: לא\u0004 תפרש \u0003\"נשאת\" נשאת ממש, אלא\u0004 הכוונה היא: \u0003כיון שהתירוה לינשא, אף על פי ש\u0004עדיין \u0003לא נשאת\u0004 — הרי זו מותרת להינשא. ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"לא תצא\" קתני\u0004 \u0005[שנה],\u0006 ואין לשון יציאה אלא במי שכבר נישאה! ומסבירים: יש לפרש זאת כלשון מושאלת, והכוונה היא: \u0003לא תצא מהתירה הראשון\u0004 שהותרה לפני שבאו העדים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003אמרה: \"נשביתי וטהורה אני ויש לי עדים שטהורה אני\"\u0004 שהיו איתה כל אותו זמן — \u0003אין אומרים: נמתין עד שיבאו עדים\u0004 אלה ויתברר הדבר היטב, \u0003אלא מתירין אותה\u0004 להינשא \u0003מיד. התירוה לינשא ואחר כך באו עדים\u0004 שהיו איתה, \u0003ואמרו: לא ידענו\u0004 אם נטמאה או לא — \u0003הרי זו לא תצא,\u0004 שהרי הותרה על פי דבריה הראשונים ולא על סמך דברי העדים. \u0003ואם באו עדי טומאה,\u0004 שראו שנבעלה לשובים, אם נישאה זו לכהן, \u0003אפילו יש לה כמה בנים\u0004 — הרי זו \u0003תצא,\u0004 שהרי היא אסורה לכהן.","מסופר: \u0003הני שבוייתא דאתיין\u0004 \u0005[אותן שבויות שבאו]\u0006 \u0003ל\u0004עיר \u0003נהרדעא\u0004 על ידי שוביהן, כדי שיפדו אותן תושבי העיר. \u0003אותיב אבוה\u0004 \u0005[הושיב אביו]\u0006 של \u0003שמואל נטורי בהדייהו\u0004 \u0005[שומרים עליהן]\u0006 שישמרו שלא יתייחדו אתן גברים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל:\u0004 מה טעם יש בשמירה זו? \u0003ועד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003מאן נטרינהו\u0004 \u0005[מי שמר אותן]?\u0006 ואם יש לחשוש להן — כבר היה מקום שייטמאו בזמן השבי. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אילו בנתך הווין\u0004 \u0005[בנותיך היו\u0006 אלה\u0005]\u0006 \u0003מי הוית\u0004 \u0005[האם היית]\u0006 \u0003מזלזל בהו כולי האי\u0004 \u0005[בהן כל כך]?\u0006 וכיון שיצאו מן השבי צריך לנהוג בהן כבבנות ישראל כשירות ולדאוג להן שיהיו בצניעות.","ומעירים, \u0003הואי\u0004 \u0005[היה]\u0006 דבר זה שאמר אביו של שמואל: \u0003\"כשגגה שיצא מלפני השליט\"\u0004 (קהלת י, ה), וכך אירע באמת, \u0003ואישתביין בנתיה\u0004 \u0005[ונשבו בנותיו]\u0006 של \u0003מר שמואל ואסקינהו לארעא דישראל\u0004 \u0005[והעלו אותן\u0006 השובים \u0005לארץ ישראל]\u0006 ורצו למוכרן או להפדותן. מה עשו הבנות לפני שנפדו — \u0003אוקמן לשבויינהו מאבראי\u0004 \u0005[העמידו את שוביהן מבחוץ],\u0006 ביקשו שלא יכנסו אתן פנימה, \u0003ועיילי לבי מדרשא\u0004 \u0005[ונכנסו לבית המדרש]\u0006 של \u0003ר' חנינא. הא\u0004 \u0005[זו\u0006 אחת מהן\u0005]\u0006 \u0003אמרה: \"נשביתי וטהורה אני\", והא\u0004 \u0005[וזו,\u0006 השניה\u0005]\u0006 \u0003אמרה: \"נשביתי וטהורה אני\".\u0004 מכיון ששמעו זאת מפיהן, \u0003שרינהו\u0004 \u0005[התירו אותן]\u0006 להינשא אפילו לכהן.","\u0003סוף עול אתו שבויינהו\u0004 \u0005[לבסוף,\u0006 לאחר מכן, \u0005נכנסו\u0006 ו\u0005באו שוביהן]\u0006 וידעו כולם שהן שבויות, אלא כיון שבאו הבנות קודם והעידו על עצמן, ולא ראו בבית המדרש קודם לכן את השובים, נמצא שהוא כפי הדין כשבאו עדים לאחר מכן שלא תצא, והן נאמנות. \u0003אמר ר' חנינא:\u0004 מתוך מעשיהן רואים כי \u0003בנן דמוריין אינון\u0004 \u0005[בנות של\u0006 אנשים גדולים, \u0005מורי הוראה, הן],\u0006 שידעו לעשות באופן זה, כדי להשאר בחזקת טהרה. ומספרים: שבאמת לבסוף \u0003איגלאי מילתא דבנתיה\u0004 \u0005[נתגלה הדבר שבנותיו]\u0006 של \u0003מר שמואל הווין\u0004 \u0005[היו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חנינא לרב שמן בר אבא\u0004 הכהן: \u0003פוק איטפל\u0004 \u0005[לך טפל]\u0006 \u0003בקרובותיך,\u0004 בנות שמואל שנשבו, ושא אחת מהן, שהרי הן קרובות שלך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב שמן \u0003לר' חנינא: והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003עדים במדינת הים\u0004 שידעו עוד קודם לכן שנשבו! אמר לו ר' חנינא: \u0003השתא מיהת ליתנהו קמן\u0004 \u0005[עכשיו על כל פנים אינם לפנינו]\u0006 ואין אנחנו צריכים לחשוש לעדותם. ובפתגם אמר לו: \u0003עדים בצד\u0004 שהוא \u0003אסתן\u0004 (צפון), באיזה מקום רחוק, \u0003ותאסר\u0004 האשה בגללם? ומדייקים בדבריו של ר' חנינא: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003לא אתו\u0004 \u0005[באו]\u0006 \u0003עדים\u0004 כדי להעיד עליהן, \u0003הא אתו\u0004 \u0005[הרי\u0006 אם היו \u0005באים]\u0006 \u0003עדים, מיתסרא\u0004 \u0005[\u0006היו \u0005נאסרות]?\u0006","\u0003והאמר אבוה\u0004 \u0005[והרי אמר אביו]\u0006 של \u0003שמואל: כיון שהתירוה לינשא, אף על פי שלא נשאת,\u0004 ובאו עדים אחר כך והעידו שנשבתה — הרי היא מותרת! \u0003אמר רב אשי: עדי טומאה איתמר\u0004 \u0005[נאמר],\u0006 שחשש שמא יבואו עדים ויעידו שנטמאו בזמן שהיו שבויות."],["\u0003שתי נשים שנשבו,\u0004 ויש עדים על כך, \u0003זאת,\u0004 אחת מהן, \u0003אומרת: \"נשביתי וטהורה אני\", וזאת אומרת: \"נשביתי וטהורה אני\" — אינן נאמנות. ובזמן שהן מעידות זו את זו,\u0004 שכל אחת אומרת על חברתה שהיא טהורה — \u0003הרי אלו נאמנות.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 שתי שבויות, שאחת מהן אמרה: \u0003\"אני טמאה וחברתי טהורה\"\u0004 — הרי היא \u0003נאמנת\u0004 לגמרי. אמרה: \u0003\"אני טהורה וחברתי טמאה\" — אינה נאמנת,\u0004 לא על עצמה ולא על חברתה. אמרה: \u0003\"אני וחברתי טמאה\" — נאמנת\u0004 בעדותה \u0003על עצמה ואינה נאמנת על חברתה. \"אני וחברתי טהורה\" — נאמנת על חברתה ואינה נאמנת על עצמה.\u0004","ומבררים את הברייתא, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 האומרת \u0003\"אני טהורה וחברתי טמאה\" — אינה נאמנת.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דליכא\u0004 \u0005[אם שאין]\u0006 \u0003עדים\u0004 שנשבו, \u0003על עצמה אמאי לא מהימנא\u0004 \u0005[מדוע אינה נאמנת]?\u0006 הלא בעצם \u0003\"נשביתי וטהורה אני\" קאמרה\u0004 \u0005[\u0006היא \u0005אומרת]\u0006 ויש להאמין לה, שהפה שאסר הוא הפה שהתיר! \u0003אלא פשיטא דאיכא\u0004 \u0005[פשוט שיש]\u0006 \u0003עדים\u0004 שנשבו, ולכן אינה נאמנת אף לגבי עצמה.","\u0003אימא מציעתא\u0004 \u0005[אמור\u0006 את \u0005האמצע]\u0006 של הברייתא הזאת: האומרת \u0003\"אני וחברתי טמאה\" — נאמנת על עצמה ואינה נאמנת על חברתה. ואי דאיכא\u0004 \u0005[ואם שיש]\u0006 \u0003עדים\u0004 שנשבו — \u0003אמאי לא מהימנא\u0004 \u0005[מדוע אינה נאמנת]\u0006 לגבי חברתה לומר שנטמאה בשבייה, הלא משעה שנשבית שוב אין לה כבר חזקת כשרות? \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן במקרה \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003עדים\u0004 ולכן אינה נאמנת לומר על חברתה, באין עדים אחרים, שנשבתה ונטמאה.","אם כך \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא: האומרת \u0003\"אני וחברתי טהורה\" — נאמנת על חברתה ואינה נאמנת על עצמה. ואי\u0004 \u0005[ואם]\u0006 מדובר כאן \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003עדים\u0004 שנשבו — על \u0003עצמה אמאי לא מהימנא\u0004 \u0005[מדוע אינה נאמנת]?\u0006 \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדים,\u0004","ואם כן יש להסביר הברייתא הזו בצורה תמוהה: \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 מדובר \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדים,\u0004 ואילו \u0003מציעתא דליכא\u0004 \u0005[אמצעה שאין]\u0006 \u0003עדים! אמר אביי: אין\u0004 \u0005[כן],\u0006 אף שהדבר אינו רגיל, יש לפרש כך: \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה] —\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדים, מציעתא\u0004 \u0005[\u0006ו\u0005אמצעה] —\u0006 \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003עדים.\u0004","\u0003רב פפא אמר:\u0004 אפשר לפרש כי כל הברייתא \u0003כולה\u0004 עוסקת באופן \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדים, ו\u0004אולם \u0003איכא\u0004 \u0005[ויש]\u0006 \u0003עד אחד דקא אפיך\u0004 \u0005[שהופך],\u0006 שאומר בניגוד לדברי האשה המעידה. כיצד? \u0003אמרה: \"אני טמאה וחברתי טהורה\" ואמר לה עד אחד: \"את טהורה וחברתך טמאה\".\u0004 הרי אז, \u0003איהי\u0004 \u0005[היא]\u0006 בעדותה לגבי עצמה, \u0003שויתא לנפשה חתיכה דאיסורא\u0004 \u0005[עשתה את עצמה חתיכת איסור]\u0006 שאף שאמר העד שהיא טהורה, מכל מקום כיון שהודתה שהיא טמאה — הרי היא אוסרת את עצמה. ואילו \u0003חברתה — משתריא אפומא דידה\u0004 \u0005[מותרת על פיה שלה],\u0006 שהרי היא מעידה עליה שהיא טהורה ולענין זה נאמנת גם אשה, למרות שיש מי שמכחיש אותה.","ואם אמרה: \u0003\"אני טהורה וחברתי טמאה\" ואמר לה עד אחד: \"את טמאה וחברתך טהורה\", איהי\u0004 \u0005[היא],\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדים\u0004 שמעידים שנשבית — \u0003לאו כל כמינה\u0004 \u0005[אין ביכולתה]\u0006 להתיר את עצמה בדבריה בלבד, ואילו \u0003חברתה — משתריא אפומא\u0004 \u0005[מותרת על פי]\u0006 ה\u0003עד.\u0004","אמרה: \u0003\"אני וחברתי טמאה\", ואמר לה עד אחד: \"את וחברתך טהורה\", איהי שויתא לנפשה חתיכה דאיסורה\u0004 \u0005[היא עשתה את עצמה חתיכת איסור],\u0006 וטמאה, ואילו \u0003חברתא\u0004 \u0005[החברה]\u0006 \u0003משתריא אפומא\u0004 \u0005[מותרת על פי]\u0006 ה\u0003עד,\u0004 שעד אחד נאמן בשבויה למרות ההכחשה, ושואלים: אם הדברים מוסברים באופן זה, \u0003הא תו\u0004 \u0005[\u0006הלכה \u0005זו,\u0006 שני המקרים האחרונים, \u0005עוד]\u0006 \u0003למה לי? היינו רישא\u0004 \u0005[הרי היא\u0006 ההלכה \u0005שבראש],\u0006 ומה החידוש בשני המקרים האחרים? שהרי משני המקרים הראשונים כבר למדנו את העקרונות — שאם אומרת על עצמה שנטמאה, היא נאסרת משום \"חתיכה דאיסורא\", ושעדות עד אחר לטהרת חברתה מתקבלת למרות שהוכחשה!","ומסבירים את המקרה בו היא אומרת ששתיהן טמאות, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני תרוייהו\u0004 \u0005[אלו שתיהן]\u0006 באמת \u0003טהורות נינהו\u0004 \u0005[הן],\u0006 וכדברי העד, \u0003והאי דקאמרה הכי\u0004 \u0005[וזו ש\u0006היא \u0005אומרת כך]\u0006 ששתיהן טמאות — משום \u0003\"תמת נפשי עם פלשתים\"\u0004 (שופטים טז, ל) \u0003היא דקא עבדה\u0004 \u0005[שעושה],\u0006 כלומר, שרוצה לקלקל לחברתה, וכדי שיאמינו לה אומרת גם על עצמה שטמאה היא, ונאמר שאינה נאמנת אף על עצמה שטמאה היא, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין מתחשבים בחשש זה.","ובמקרה השני כשאומרת \u0003\"אני וחברתי טהורה\" ואמר לה עד אחד \"את וחברתך טמאה\", איהי\u0004 \u0005[היא]\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדים\u0004 שנשבית — \u0003לאו כל כמינה\u0004 \u0005[אין\u0006 זה \u0005ביכולתה]\u0006 לטהר את עצמה. \u0003חברתה משתריא אפומא דידה\u0004 \u0005[מותרת על פיה שלה].\u0006 ושואלים: \u0003הא תו\u0004 \u0005[\u0006הלכה \u0005זו עוד]\u0006 \u0003למה לי? היינו רישא דרישא\u0004 \u0005[הרי זו התחלה של ההתחלה],\u0006 שהרי שם כבר למדנו שחברתה טהורה על פיה למרות שהעד מכחישה, ומה מחדש כאן?","ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כי מהימנא\u0004 \u0005[כאשר היא נאמנת]\u0006 הרי זה \u0003במקום דפסלה נפשה\u0004 \u0005[ש\u0006היא \u0005פוסלת את עצמה],\u0006 \u0003אבל במקום דמכשרא נפשה\u0004 \u0005[שמכשירה\u0006 גם \u0005את עצמה]\u0006 \u0003אימא לא מהימנא\u0004 \u0005[אמור\u0006 ש\u0005אינה נאמנת]\u0006 גם על חברתה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו בזה דנים בעדות לגופה, ואין חוששים.","\u0003וכן שני אנשים\u0004 שאין משפחתם ידועה לנו, \u0003זה אומר \"כהן אני\" וזה אומר \"כהן אני\" — אינן נאמנין\u0004 ואינם מאכילים אותם תרומה, \u0003ובזמן שהן מעידין זה את זה,\u0004 שכל אחד מעיד על חבירו שהוא כהן — \u0003הרי אלו נאמנין. ר' יהודה\u0004 חולק ו\u0003אומר: אין מעלין לכהונה על פי עד אחד,\u0004 אלא צריכים שני עדים לכך. \u0003אמר ר' אלעזר: אימתי\u0004 אין סומכים על עד אחד — \u0003במקום שיש עוררין\u0004 על כך שהוא כהן. \u0003אבל במקום שאין עוררין\u0004 — \u0003מעלין לכהונה על פי עד אחד. רבן שמעון בן גמליאל אומר משום ר' שמעון בן הסגן: מעלין לכהונה על פי עד אחד.\u0004","\u0003כל הני\u0004 \u0005[אלה]\u0006 \u0003למה לי,\u0004 כלומר, מדוע צריך לפרט במשניות שבפרקנו את המקרים השונים כאשר כולן מבוססות על כלל אחד שהפה שאסר הוא הפה שהתיר! ומשיבים: \u0003צריכי\u0004 \u0005[צריכים]\u0006 כל אלה להיאמר, \u0003דאי תנא\u0004 \u0005[שאילו היה שונה]\u0006 רק את המקרה שבו \u0003מודה ר' יהושע\u0004 במי שאמר לחבירו שהשדה היה שייך לאביו והוא קנה אותו ממנו, אפשר היה לחשוב שרק \u0003משום דאיכא דררא דממונא\u0004 \u0005[שיש גרר של ממון],\u0006 שמכיון שיש לו כאן הפסד ממון במה שהוא מודה בתחילת דבריו ששל אביו של התובע היה, אנו מאמינים לו שקנה מאביו, משום שלא היה מספר דבר זה אם לא היה אמת, \u0003אבל\u0004 במקרה של \u0003עדים,\u0004 שאומרים שחתימתם היתה פסולה, \u0003דליכא דררא דממונא\u0004 \u0005[שאין\u0006 כאן \u0005גרר של ממון],\u0006 שהרי אין הם עצמם מפסידים דבר בהודאתם, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נאמין להם במה שחוזרים ואומרים אנוסים היינו אלא רק לתחילת דבריהם שמעידים על אמינות חתימתם.","\u0003ואי תנא\u0004 \u0005[ואם\u0006 היה \u0005שונה]\u0006 במקרה של ה\u0003עדים\u0004 היינו אומרים שהם נאמנים \u0003משום דלעלמא\u0004 \u0005[ש\u0006עדותם מכוונת \u0005לעולם],\u0006 שהם מעידים עבור אחרים, \u0003אבל איהו, דלנפשיה\u0004 \u0005[הוא,\u0006 שמעיד על דבר \u0005ש\u0006נוגע \u0005לעצמו],\u0006 שאומר שלקח את השדה מן האב,"],["\u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ויהא נאמן במה שחוזר ואומר \"לקחתיה ממנו\".","ועוד: \u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואם\u0006 היה \u0005משמיע לנו\u0006 את \u0005שני\u0006 המקרים \u0005הללו\u0006 בלבד\u0005],\u0006 הייתי אומר שנאמנים הם אף במה שהם מסייגים את עדותם \u0003משום\u0004 שהם עניינים \u0003דממונא\u0004 \u0005[של ממון],\u0006 \u0003אבל אשת איש\u0004 האומרת שהיא גרושה כעת, שהוא ענין \u0003דאיסורא\u0004 \u0005[של איסור]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יאמינו לה במה שאומרת \"נתגרשתי\", ולכן הוצרך להשמיענו גם בזה.","ושואלים: הדין של \u0003\"נשביתי וטהורה אני\" למה לי?\u0004 והרי אין כאן שום חידוש! ומשיבים: \u0003משום דקא בעי למיתני\u0004 \u0005[שרצה לשנות]\u0006 את ההמשך: \u0003\"ואם משנשאת באו עדים — הרי זו לא תצא\",\u0004 משום כך הוזכר גם דין זה לגופו.","ושואלים: \u0003הניחא למאן דמתני לה אסיפא\u0004 \u0005[זה נוח למי ששונה אותה,\u0006 את ההלכה הזו \u0005על הסוף],\u0006 על המקרה של שבויה, \u0003אלא למאן דמתני לה ארישא\u0004 \u0005[למי ששונה אותה על ההתחלה]\u0006 וסבור שהלכה זו אמורה גם במי שאמרה שהיתה אשת איש ונתגרשה — אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שלפי זה, הדין של שבויה (שאיסורה לכהן הוא קל מאיסור אשת איש) הוא מיותר, ובודאי נאמנת! ומשיבים: \u0003משום דקא בעי למיתני\u0004 \u0005[שרוצה לשנות]\u0006 אחר כך את הדין של \u0003\"שתי נשים שנשבו\",\u0004 היה צריך להקדים את עיקר ההלכה באשה שאומרת \"נשביתי\" על אף שנאמנותה ברורה.","ושואלים: \u0003ו\u0004הלכה זו של \u0003\"שתי נשים שנשבו\" למה לי?\u0004 מה החידוש בו יותר מבאשה אחת שנשבתה ומעידה על עצמה בלבד? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003ניחוש\u0004 \u0005[נחשוש]\u0006 \u0003לגומלין,\u0004 שמא מה שמעידות זו על זו הוא משום הסכם גומלין, שכל אחת מעידה על חברתה בתנאי שחברתה תעיד כן אף עליה, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אנו חוששים לכך.","ושואלים: והדין של \u0003\"וכן שני אנשים\"\u0004 המעידים על כהונתם \u0003למה לי?\u0004 הרי בכך אין חידוש, שהרי כבר למדנו שנשים המעידות זו על זו נאמנות! ומסבירים: \u0003משום דקא בעי למיתני\u0004 \u0005[שרוצה לשנות]\u0006 בהמשך \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003ר' יהודה ורבנן\u0004 \u0005[וחכמים]\u0006 אם עד אחד נאמן לחזקת כהונה, לכך הזכיר קודם לכן הלכה זו ביחס לנאמנות אדם על עצמו לענין כהונה.","ומעתה באים לדון בגוף ההלכה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אדם שאמר \u0003\"אני כהן וחברי כהן\"\u0004 — הרי הוא \u0003נאמן\u0004 על חבירו \u0003להאכילו בתרומה,\u0004 שנותנים לחבירו תרומה מכח עדות זאת, \u0003ו\u0004אולם \u0003אינו נאמן להשיאו אשה\u0004 מיוחסת, שייחשב כהן לענין יוחסין, \u0003עד שיהו שלשה\u0004 עדים, כלומר, שצריך עוד עד אחד שיעיד על כך ששניהם כהנים, חוץ משניהם, כדי שיהיו \u0003שנים מעידין על זה ושנים מעידין על זה. ר' יהודה אומר: אף אינו נאמן להאכילו בתרומה עד שיהו שלשה\u0004 אנשים, כדי שיהיו בסך הכל \u0003שנים מעידין על זה ושנים מעידין על זה.\u0004","ומבררים את הסברות: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 כי \u0003ר' יהודה חייש\u0004 \u0005[חושש]\u0006 \u0003לגומלין,\u0004 שכל אחד מהם מעיד על כך שחבירו כהן כדי שבתמורה יעיד לו חבירו כמו כן ובאמת הם משקרים, \u0003ורבנן לא חיישי\u0004 \u0005[ו\u0006כי \u0005חכמים אינם חוששים]\u0006 \u0003לגומלין? והא איפכא שמעינן להו\u0004 \u0005[והרי היפך\u0006 הדברים \u0005שמענו אותם\u0006 אומרים\u0005],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003החמרין\u0004 שמובילים על גבי חמוריהם תבואה \u0003שנכנסו לעיר, ואמר אחד מהן:\u0004 התבואה \u0003שלי חדש,\u0004 כלומר, מיבול שנה זו ואינה מובחרת כל כך, \u0003ושל חברי ישן,\u0004 ומשתמרת היטב. או שאמר: היבול \u0003שלי אינו מתוקן\u0004 (אינו מעושר), \u0003ושל חברי מתוקן — אינו נאמן.\u0004 ולכאורה הטעם הוא מפני שהחמרים הינם בדרך כלל עמי הארץ ואינם נאמנים על המעשר, ואף על פי שאומר על שלו שאינו מתוקן, מכל מקום חוששים אנו לגומלין, שמא אומרים כך במקום זה, ובמקום אחר יהפכו דבריהם, ויעיד השני שתבואת חבירו היא המובחרת. ו\u0003ר' יהודה אומר: נאמן.\u0004 ואם כן רואים שר' יהודה אינו חושש לגומלין!","\u0003אמר רב אדא בר אהבה אמר רב: מוחלפת השיטה.\u0004 כלומר, צריך להחליף את דעות החולקים באחת המשניות, שלשיטה אחת חוששים לגומלין ולשיטה אחרת אין חוששים. \u0003אביי אמר: לעולם לא תיפוך\u0004 \u0005[אל תהפוך]\u0006 ומה שסומך ר' יהודה על החמרים בענין דמאי הוא משום ש\u0003ב\u0004דיני \u0003דמאי הקילו\u0004 חכמים, מפני שאנו מניחים כי \u0003רוב עמי הארץ מעשרים הן.\u0004 ותקנת חכמים שיעשרו את הדמאי היא רק מפני חשש רחוק, ולכן יש לסמוך על עדות כל שהיא כדי להתיר, אבל למעשה חושש ר' יהודה לגומלין.","\u0003אמר רבא:\u0004 וכי מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה קשיא\u0004 \u0005[קשה],\u0006 ואילו \u0003דרבנן אדרבנן לא קשיא\u0004 \u0005[\u0006מדברי \u0005חכמים על\u0006 דברי \u0005חכמים אינו קשה]?\u0006 הרי יש סתירה גם בשיטת חכמים, שהרי אף שיטתם הפוכה! \u0003אלא\u0004 כך צריך לומר: מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כדשנינן\u0004 \u0005[כפי שתירצנו],\u0006 שר' יהודה מיקל בדמאי. ואילו \u0003דרבנן אדרבנן לא קשיא\u0004 \u0005[מדברי חכמים על דברי חכמים אינו קשה]\u0006 מטעם אחר; אכן חכמים אינם חוששים לגומלין, אך במקרה של החמרים מדובר \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003ר' חמא בר עוקבא\u0004 לגבי נושא אחר, ששם מדובר \u0003ב\u0004אופן \u0003שכלי אומנותו בידו\u0004 של האיש מוכר התבואה,"],["\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר שהחמר השני בא גם הוא \u0003ב\u0004אופן \u0003שכלי אומנותו\u0004 (של מוכר תבואה) \u0003בידו,\u0004 שניכרים הדברים שגם הוא בא למכור את תבואתו, ואף שמגנה את תבואתו, כיון שנראים הדברים שכוונתו בסופו של דבר למכור את תבואתו, וגם הוא משבח את תבואתו של חבירו — יש לחשוש לגומלין, שבעיר אחרת הם הופכים את הדברים, וחבירו משבח את תבואתו שלו, אבל כשאין ראיה לדבר, אין חכמים חוששים לגומלין.","ומעירים: \u0003והיכא אתמר\u0004 \u0005[והיכן,\u0006 על מה \u0005נאמר]\u0006 התירוץ של \u0003ר' חמא בר עוקבא — אהא\u0004 \u0005[על זו],\u0006 \u0003דתנן\u0004 \u0005[ששנינו]:\u0006 \u0003הקדר\u0004 שהוא חבר ועושה כליו בטהרה \u0003שהניח קדירותיו וירד לשתות מים מן היאור,\u0004 ויש לחשוש שבינתיים נגעו אנשים טמאים בקדירות — הקדירות \u0003הפנימיות טהורות, והחיצונות טמאות.\u0004","ושאלו, \u0003והתניא\u0004 \u0005[והרי\u0006 \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003אלו ואלו,\u0004 הפנימיות והחיצוניות \u0003טמאות! אמר ר' חמא בר עוקבא:\u0004 שם באותה ברייתא המטמאת את הכל, מדובר \u0003בשכלי אומנותו\u0004 של הקדר \u0003בידו,\u0004 ומזה רואים הכל שהוא רוצה למכור עתה את הקדירות, ו\u0003מפני שיד הכל ממשמשת בהן,\u0004 שבאים לבדוק הקדירות לפני קנייתן, יש לחשוש שבין הנכנסים לבדוק את הקדירות היה גם אדם טמא.","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 עוד ברייתא\u0005]\u0006 האומרת: \u0003אלו ואלו טהורות! אמר ר' חמא בר עוקבא:\u0004 שם מדובר \u0003בשאין כלי אומנותו בידו\u0004 שניכר שאינו עסוק עתה במכירה, וכיון שכך אין אנשים זרים נוגעים בהן כלל.","ושואלים: אם כן, \u0003ואלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הפנימיות טהורות והחיצונות טמאות. היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה]?\u0006 שהרי כפי שאמרנו אם כלי אומנותו בידו — הכל טמא, ואם אינם בידו — הכל טהור!","ומשיבים: מדובר במקרה שאין כלי אומנותו בידו, אלא \u0003דסמיכא\u0004 \u0005[שסמוך]\u0006 המקום שבו הניח את הקדירות \u0003לרשות הרבים, ומשום חיפופי\u0004 (צידי) \u0003רשות הרבים.\u0004 שסמוך לרשות הרבים יש מקום שבו מניחים המוכרים את סחורתם, ופעמים שיש אנשים רבים ברשות הרבים ונדחקים ונכנסים לצדדים, ותוך כדי הילוכם נגעו בקדירות החיצוניות. אבל למקום הקדירות הפנימיות אין נכנסים, שהרי לא גילה שדעתו למכור אותן. עד כאן תירוץ אחד לסתירה שבין מחלוקת ר' יהודה וחכמים בדיני חזקת כהונה ובדיני חמרים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי מחלוקת \u0003ר' יהודה ורבנן\u0004 \u0005[וחכמים]\u0006 אינה בשאלה אם חוששים לגומלין, אלא \u0003ב\u0004שאלה האם \u0003מעלין מתרומה ליוחסין קמיפלגי\u0004 \u0005[חלוקים]\u0006 הם. שלדעת ר' יהודה כל מי שאוכל בתרומה מעלים אותו על סמך זה לכהונה גם לענין יחוס, ולכן נחוצה לדעת ר' יהודה עדות גמורה גם לגבי תרומה. ואילו חכמים סבורים שאין מעלים מתרומה ליוחסין, ומשום כך לגבי תרומה די בעדות כלשהי, ולגבי יוחסין יצטרכו עדות שלימה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 \u0003מהו להעלות משטרות ליוחסין?\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דכתיב ביה\u0004 \u0005[אם נאמר שכתוב בו,\u0006 בשטר\u0005]\u0006 \u0003\"אני פלוני כהן חתמתי עד\"\u0004 — אולם במקרה כזה \u0003מאן קא מסהיד עילויה\u0004 \u0005[מי מעיד עליו]\u0006 שהוא כהן? הלא הוא עצמו כתב מה שכתב, ואין כאן עדות כלל!","ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דכתיב ביה\u0004 \u0005[שכתוב בו]\u0006 בשטר \u0003\"אני פלוני כהן לויתי מנה מפלוני\" וחתימו סהדי\u0004 \u0005[וחתמו עדים],\u0006 והשאלה היא \u0003מאי\u0004 \u0005[מה]?\u0006 האם על ה\u0003מנה,\u0004 הכסף \u0003שבשטר קא מסהדי\u0004 \u0005[הם\u0006 \u0005מעידים],\u0006 שאין עדותם אלא על עיקר הדבר — על ההלוואה שהיתה שם, \u0003או דלמא אכולה מילתא קא מסהדי\u0004 \u0005[שמא על כל הדבר הם\u0006 \u0005מעידים]\u0006 ומאשרים כל פרט הכתוב בשטר, ואם כן בין השאר הם מעידים גם שהוא כהן. להלכה נחלקו בכך החכמים \u0003רב הונא ורב חסדא; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מעלין\u0004 משטרות ליוחסין, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אין מעלין.\u0004","כיוצא בזה \u0003איבעיא להו\u0004 \u0005[נשאלה להם]:\u0006 \u0003מהו להעלות מנשיאות כפים ליוחסין?\u0004 שאם ראו אדם שנושא את כפיו ומברך את הציבור בבית הכנסת ככהן, האם אפשר לסמוך על כך גם לגבי יוחסין? ומעירים: \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003מעלין מתרומה ליוחסין, ותיבעי למאן דאמר\u0004 \u0005[ותישאל\u0006 גם \u0005ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אין מעלין.\u0004","ומסבירים: \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מעלין\u0004 מתרומה ליוחסין, שכן אפשר לומר: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים ב\u0003תרומה,\u0004 כי אכילת תרומה על ידי זר (שאינו כהן) \u0003עון מיתה היא\u0004 שעונשה מיתה בידי שמים, ואין לחשוד באדם שיעבור עבירה חמורה זו, ולכן נראה שהוא אכן כהן, \u0003אבל נשיאות כפים,\u0004 ש\u0003איסור עשה,\u0004 שזר הנושא את כפיו אינו עובר אלא באיסור עשה, שהרי חובת הכהנים לשאת כפיהם בברכה נאמרה כמצוות עשה, ומכלל העשה נובע גם איסור לזרים לעשות כן, \u0003לא,\u0004 אין אנשים מקפידים כל כך, ויש לחשוש שמא בשל קולתו היחסית של הדבר, יבוא לרמות וישא כפיו אף שאינו כהן, ולכן לא אף יש לחשוש לכך ולא להעלותו על סמך זה ליוחסין. \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה],\u0006 שמאחר שיש בכך עבירה, אין לחשוד באדם שעובר עבירה, ובודאי יש לומר שכהן הוא.","וכן מצד שני \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אין מעלין\u0004 מתרומה ליוחסין, שאפשר לומר: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא ב\u0003תרומה דמיתאכלא בצנעא\u0004 \u0005[שנאכלת בצינעה],\u0006 שייתכן שאדם זה אינו כהן, אבל כיון שהוא עושה את הדבר בצינעה — אינו מתבייש בכך, \u0003אבל נשיאות כפים\u0004 שהיא נעשית \u0003בפרהסיא, אי לאו\u0004 \u0005[אם לא]\u0006 \u0003כהן הוא — כולי האי לא מחציף אינש נפשיה\u0004 \u0005[כל כך אין אדם מחציף עצמו]\u0006 לעבור עבירה בפני הרבים, ואם נשא כפיו משמע שכהן הוא. \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה],\u0006 שאם אדם עובר עבירה אינו מקפיד אם זה בצינעה או ברבים, וגם כאן אין לסמוך על מעשהו, כשם שאין סומכים על אכילת תרומה.","ואף בכך נחלקו להלכה \u0003רב חסדא ור' אבינא; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מעלין\u0004 מנשיאות כפים ליוחסין, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אין מעלין.\u0004 ובאותה שאלה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרבא: מהו להעלות מנשיאות כפים ליוחסין? אמר ליה\u0004 \u0005[לו]\u0006 רבא: דבר זה הוא \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 \u0003רב חסדא ור' אבינא.\u0004","וחזר ושאל רב נחמן בר יצחק: \u0003הלכתא מאי\u0004 \u0005[\u0006ו\u0005הלכה מה\u0006 היא\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא מתניתא ידענא\u0004 \u0005[אני משנה,\u0006 ברייתא, \u0005יודע אני]\u0006 ועליה אני סומך; \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: גדולה\u0004 היא ה\u0003חזקה\u0004 שסומכים עליה, ואין משנים ממנה. \u0003שנאמר: \"ומבני הכהנים בני חביה בני הקוץ בני ברזלי אשר לקח מבנות ברזלי הגלעדי אשה ויקרא על שמם. אלה בקשו כתבם המתיחשים ולא נמצאו ויגאלו מן הכהנה. ויאמר התרשתא להם אשר לא יאכלו מקדש הקדשים עד עמד כהן לאורים ולתמים\"\u0004 (עזרא ב, סא-סג). שמאחר ובגולה נישאו חלק מן הכהנים לבנות הגויים והיו בניהם חללים, לכן משחזרו לארץ והוקם בית המקדש השני, היו צריכים כל הכהנים להוכיח את ייחוסם כדי שיוכלו לשרת בו. ואותם כהנים שלא היה ברשותם אפשרות להוכיח, נדחו מן הכהונה. ונחמיה הוא שמצא פתרון חלקי לבעייתם.","ומפרש ר' יוסי את דבריו: \u0003אמר להם\u0004 נחמיה לאותם כהנים מסופקים: \u0003הרי אתם בחזקתכם. במה הייתם אוכלים בגולה\u0004 כשהייתם בבבל — \u0003בקדשי הגבול,\u0004 כלומר, בתרומה, \u0003אף כאן\u0004 תמשיכו לאכול \u0003בקדשי הגבול.\u0004 אבל לא תאכלו בקדשי הקדשים, כלומר, מן הקרבנות, שהרי לכך אין לכם חזקה, שהרי לא אכלתם קרבנות בגולה. ומכאן נלמד לענייננו, \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003מעלין מנשיאות כפים ליוחסין, הני\u0004 \u0005[\u0006הכהנים \u0005הללו]\u0006 \u0003כיון דפרסי ידייהו\u0004 \u0005[ש\u0006הם \u0005פורסים\u0006 את \u0005כפיהם]\u0006 בברכה — \u0003אתי לאסוקינהו\u0004 \u0005[יבואו להעלותם]\u0006 גם ליוחסין!","ודוחים: \u0003שאני הכא דריע חזקייהו\u0004 \u0005[שונה כאן שהורעה חזקתם],\u0006 שכיון שרואים שאינם אוכלים בקדשי המזבח כשאר הכהנים, יודעים בהם שאינם כהנים ודאיים. ומוסיפים: \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך],\u0006 שסומכים על טעם זה שהורעה חזקתם, אזי הרי \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003מעלין מתרומה ליוחסין\u0004 אפשר היה להקשות עליו מכאן: \u0003כיון דאכלי\u0004 \u0005[ש\u0006הם \u0005אוכלים]\u0006 \u0003בתרומה — אתי לאסוקינהו\u0004 \u0005[יבואו להעלותם]\u0006 ליוחסין! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מפני שיש לומר שאין לחשוש לדבר \u0003משום דריע חזקייהו\u0004 \u0005[שהורעה חזקתם]\u0006 מתוך שאינם אוכלים בקדשי קדשים, והכל יודעים בהם שאינם כהנים ודאיים. ולכן אין ללמוד מכאן הלכה לזמן הזה, כאשר כל הכהנים אוכלים רק בתרומה, שאז יתכן שמעלים מתרומה ליוחסין."],["\u0003ו\u0004שואלים: \u0003אלא,\u0004 לפי מה שהסברנו, \u0003מאי\u0004 \u0005[מה]\u0006 המשמעות של \u0003גדולה חזקה?\u0004 שהרי נשארו כהנים אלה בחזקתם, כפי שהיו, ולא למדנו כל דבר חדש בדבר תוקפה של חזקה! ומשיבים: יש חידוש בדבר, כי החזקה הועילה להם, שהרי \u0003מעיקרא אכול\u0004 \u0005[בתחילה אכלו]\u0006 \u0003בתרומה דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 שבבבל אין תרומה מדברי תורה כי אם מדברי סופרים בלבד, ואילו \u0003השתא אכול\u0004 \u0005[עכשיו,\u0006 בבואם לארץ ישראל, הם \u0005אוכלים]\u0006 \u0003בתרומה דאורייתא\u0004 \u0005[שמן התורה].\u0006","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 \u0003בתרומה דרבנן\u0004 \u0005[שמדברי סופרים]\u0006 \u0003אכול\u0004 \u0005[\u0006הם \u0005אוכלים],\u0006 וכגון תרומת פירות האילן והירק שאף בארץ ישראל אינה אלא מדברי סופרים, ואולם \u0003בתרומה דאורייתא\u0004 \u0005[שמן התורה],\u0006 וכגון דגן תירוש ויצהר, שבארץ ישראל היא מן התורה, \u0003לא אכול\u0004 \u0005[אינם אוכלים].\u0006 \u0003ו\u0004אולם \u0003כי מסקינן\u0004 \u0005[כאשר אנו מעלים]\u0006 \u0003מתרומה ליוחסין\u0004 — הרי זה דווקא במי שאוכל \u0003בתרומה דאורייתא\u0004 \u0005[שמן התורה],\u0006 אבל האוכלים רק \u0003בתרומה דרבנן\u0004 \u0005[שמדברי סופרים] —\u0006 \u0003לא מסקינן\u0004 \u0005[אין מעלים].\u0006 \u0003ו\u0004שואלים: \u0003אלא\u0004 אם כן, כיון שלא השתנה דינם כלל, \u0003מאי\u0004 \u0005[מה]\u0006 המשמעות של \u0003גדולה חזקה,\u0004 המורה על כך שלכאורה היה מקום לבטל את חזקתם? ומסבירים: \u0003דאף על גב דאיכא למיגזר\u0004 \u0005[שאף על פי שיש\u0006 מקום \u0005לגזור]\u0006 ולאסור עליהם בארץ ישראל גם בתרומה שמדברי סופרים \u0003משום תרומה דאורייתא\u0004 \u0005[שמן התורה] —\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 ומשאירים אותם בחזקתם.","על הסבר זה מקשים מצד אחר: \u0003ו\u0004האם \u0003בתרומה דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003לא אכול\u0004 \u0005[אכלו]?\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אשר לא יאכלו מקדש הקדשים\"\u0004 (עזרא ב, סג), ונדייק: \u0003מקדש הקדשים הוא\u0004 ש\u0003לא אכול\u0004 \u0005[אכלו],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בתרומה דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003אכול\u0004 \u0005[אכלו]!\u0006","ודוחים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך כוונת הכתוב: \u0003לא\u0004 אכלו \u0003במידי דאיקרי\u0004 \u0005[בדבר שנקרא]\u0006 \u0003\"קדש\",\u0004 כלומר, בתרומה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכל זר לא יאכל קדש\"\u0004 (ויקרא כב, י), ששם מדובר בתרומה, \u0003ולא במידי דאיקרי\u0004 \u0005[בדבר שנקרא]\u0006 \u0003\"קדשים\",\u0004 כלומר, מן הקרבנות, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובת כהן כי תהיה לאיש זר היא בתרומת הקדשים לא תאכל\"\u0004 (ויקרא כב, יב) \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 מה שנאמר \"בתרומת הקדשים\", משמעו — \u0003במורם מן הקדשים,\u0004 במה שנותנים למשפחות הכהנים מן הקרבנות (לחמי־תודה וחזה ושוק) — \u0003לא תאכל\u0004 בת כהן שנישאה לזר. ומכל מקום אי אפשר לפתור מתוך ברייתא זו את הבעיה, האם מעלים מנשיאת כפים ליוחסין.","ומציעים הוכחה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לכך ממה ששנינו: \u0003חזקה לכהונה\u0004 מהי? — \u0003נשיאות כפים בבבל,\u0004 שהרואה אדם הנושא את כפיו בבבל, נאמן להעיד עליו בכל מקום שהוא כהן, \u0003ו\u0004כן \u0003אכילת חלה בסוריא, וחילוק מתנות\u0004 כהונה (זרוע לחיים וקיבה) \u0003בכרכין. קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 ש\u0003נשיאות כפים\u0004 היא חזקה לכהונה, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 אפילו \u0003ל\u0004ענין \u0003יוחסין?\u0004 ודוחים: \u0003לא,\u0004 הכוונה היא שהיא חזקה להעלותו \u0003ל\u0004אכילת \u0003תרומה.\u0004","ומקשים: \u0003והא דומיא\u0004 \u0005[והרי\u0006 ב\u0005דומה]\u0006 ל\u0003אכילת חלה קתני\u0004 \u0005[שנה]\u0006 שם, ואם כן יש לומר \u0003מה אכילת חלה\u0004 היא חזקה כדי להעלותם \u0003ליוחסין — אף נשיאות כפים\u0004 בוודאי הכוונה שהיא חזקה \u0003ליוחסין!\u0004 ודוחים: \u0003לא, אכילת חלה גופה\u0004 היא ראיה \u0003ל\u0004אכילת \u0003תרומה\u0004 בלבד, אבל לא ליוחסין. כי \u0003קסבר\u0004 \u0005[סבור]\u0006 חכם זה שחובת הפרשת \u0003חלה בזמן הזה\u0004 היא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003ותרומה\u0004 אף בזמן הזה היא אכן \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ו\u0004משמיעה לנו הברייתא ש\u0003מסקינן\u0004 \u0005[מעלים]\u0006 \u0003מ\u0004אכילת \u0003חלה דרבנן\u0004 \u0005[ש\u0006היא \u0005מדברי סופרים]\u0006 \u0003ל\u0004אכילת \u0003תרומה דאורייתא\u0004 \u0005[ש\u0006היא \u0005מן התורה].\u0006 \u0003וכדאפיך להו\u0004 \u0005[וכפי שהפך להם]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבנן\u0004 \u0005[לחכמים]\u0006 כאשר יבואר בהמשך, שהעלה סברה זו שחיוב הפרשת חלה בזמן הזה הוא רק מדברי סופרים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003חזקה לכהונה — נשיאות כפים וחילוק גרנות\u0004 של תרומה \u0003בארץ ישראל. ובסוריא ובכל מקום\u0004 בחוץ לארץ \u0003ששלוחי ראש חודש מגיעין\u0004 לשם, שהיו באים שלוחי בית הדין הגדול להודיע מתי התקדש החודש, והיה שם בית דין שקיבל את עדותם, — שם \u0003נשיאות כפים\u0004 היא \u0003ראיה,\u0004 משום שבית הדין היה בודק את אלה שנשאו כפיהם בתורת כהנים. \u0003אבל לא חילוק\u0004 תרומה ב\u0003גרנות,\u0004 שמפני שהפרשת תרומה במקומות אלו אינה מדין תורה, אין מדקדקים בה.","\u0003ובבל\u0004 דינה \u0003כסוריא.\u0004 משום שיש בה בתי דינים חשובים המדקדקים בכך. \u0003רבן שמעון בן גמליאל אומר: אף אלכסנדריא של מצרים בראשונה\u0004 היה דינה כסוריה \u0003מפני שבית דין\u0004 היו \u0003קבועין שם\u0004 ומשגיחים שיעשו הכל כהלכה.","\u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 שם ש\u0003נשיאות כפים\u0004 היא חזקה לכהונה, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 להעלות \u0003ליוחסין?\u0004 ודוחים: \u0003לא,\u0004 הכוונה היא \u0003ל\u0004היתר אכילת \u0003חלה\u0004 המופרשת מן העיסה, למי שנושא את כפיו. ומקשים: \u0003הא דומיא\u0004 \u0005[הרי\u0006 ב\u0005דומה]\u0006 ל\u0003חילוק גרנות קתני\u0004 \u0005[שנה]\u0006 ו\u0003מה חילוק גרנות\u0004 בארץ ישראל הוא ראיה \u0003ל\u0004ענין \u0003יוחסין — אף נשיאות כפים\u0004 היא לכאורה ראיה \u0003ליוחסין!\u0004 ודוחים: \u0003לא, חילוק גרנות גופה\u0004 היא ראיה \u0003לחלה.\u0004 ואפשר לומר כי \u0003קסבר\u0004 \u0005[סבור]\u0006 תנא זה ש\u0003תרומה בזמן הזה\u0004 אף בארץ ישראל היא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003וחלה\u0004 היא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ו\u0004משמיע לנו ש\u0003מסקינן\u0004 \u0005[\u0006ש\u0005אנו מעלים]\u0006 \u0003מתרומה דרבנן\u0004 \u0005[שמדברי סופרים]\u0006 \u0003לחלה דאורייתא\u0004 \u0005[שמדברי תורה].\u0006","חילוקי הדעות בשאלה אם תרומה או חלה הן חיוב מן התורה בזמן הזה באים לידי ביטוי במעשה הבא; \u0003וכדאשכחינהו\u0004 \u0005[וכפי שמצא אותם]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבנן\u0004 \u0005[את החכמים]\u0006 שסבורים כן, ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: אשכחתינהו לרבנן בבי\u0004 \u0005[מצאתי את החכמים בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב דיתבי וקאמרי\u0004 \u0005[שיושבים ואומרים]\u0006 כך: \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003תרומה בזמן הזה\u0004 היא \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 מכל מקום חובת הפרשת \u0003חלה\u0004 היא \u0003דאורייתא\u0004 \u0005[מן התורה].\u0006 וראיה לדבר \u0003שהרי\u0004 במשך \u0003שבע\u0004 השנים \u0003שכיבשו\u0004 ישראל את הארץ בימי יהושע \u0003ושבע\u0004 השנים \u0003שחילקו\u0004 אותה — \u0003נתחייבו בחלה,\u0004 למרות שעדיין \u0003לא נתחייבו בתרומה.\u0004 ואף בזמן הזה, גם כאשר בטל דין תרומה מארץ ישראל — מצות הפרשה חלה קיימת.","\u0003ואמינא להו אנא\u0004 \u0005[ואמרתי להם אני]:\u0006 \u0003אדרבה\u0004 (להיפך), \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003תרומה בזמן הזה\u0004 היא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003חלה\u0004 היא לכל הדעות \u0003דרבנן\u0004 \u0005[מדברי סופרים].\u0006 וראיה לדבר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"בבאכם אל הארץ...\u0004 ראשית עריסותכם חלה תרימו תרומה\u0003\"\u0004 (במדבר טו, יח. במדבר טו, כ), ונדייק: \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"בבאכם\", יכול\u0004 שהכוונה היא \u0003משנכנסו לה\u0004 לארץ \u0003שנים ושלשה מרגלים,\u0004 שכבר מזמן זה תחול חובת הפרשת חלה — \u0003תלמוד לומר: \"בבאכם\"\u0004 ויש לדייק: \u0003בביאת כולכם אמרתי, ולא בביאת מקצתכם.\u0004 הרי שחובת הפרשת חלה מן התורה תלויה בביאת כל ישראל לארץ, \u0003וכי אסקינהו\u0004 \u0005[וכאשר העלה אותם]\u0006 \u0003עזרא\u0004 בראשית ימי בית שני,"],["\u0003לאו כולהו סלוק\u0004 \u0005[לא כולם עלו],\u0006 וכיון שרוב ישראל לא עלו לארץ — לא חלה עליהם חובת הפרשת חלה מן התורה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003חזקה לכהונה — נשיאות כפים, וחילוק גרנות, ועדות.\u0004 ותחילה מבררים את הלשון: וכי \u0003עדות חזקה היא?\u0004 הלא עדות היא עצמה הוכחה, וגדולה מחזקה! \u0003אלא לאו הכי קאמר\u0004 \u0005[\u0006האם \u0005לא כך אמר],\u0006 כך יש להבין את הדברים: \u0003נשיאות כפים\u0004 הריהי \u0003כי\u0004 \u0005[כמו]\u0006 \u0003עדות, מה עדות\u0004 לכהונה מועילה להעלותו גם \u0003ליוחסין, אף נשיאות כפים\u0004 היא חזקה \u0003ליוחסין!\u0004 ודוחים: \u0003לא,\u0004 אפשר לפרש באופן אחר: \"עדות חזקה\" הכוונה ל\u0003עדות הבאה מכח חזקה\u0004 כשמעידים על אדם שיש לו חזקת כהונה לדבר מסויים — הרי היא עצמה \u0003כחזקה.\u0004 ואין צורך שיוחזק הדבר בפני בית דין.","וכמסופר: \u0003כי ההוא דאתא לקמיה\u0004 \u0005[כמו\u0006 אותו מעשה ב\u0005אחד שבא לפני]\u0006 \u0003ר' אמי\u0004 להעיד, \u0003אמר ליה\u0004 \u0005[לו]\u0006 בעדותו: \u0003מוחזקני בזה,\u0004 באדם פלוני, \u0003שהוא כהן. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מה ראית?\u0004 כלומר, כיצד יודע אתה שהוא כהן? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שקרא ראשון בבית הכנסת,\u0004 כדרך שקורא כהן. שאל אותו ר' אמי: כשקרא ראשון, האם היה זה \u0003בחזקת שהוא כהן, או בחזקת שהוא גדול?\u0004 מפני שהיה נהוג שלא רק הכהן קורא ראשון, אלא גם הגדול שבמתפללים קורא ראשון. אמר לו האיש: יש לי ראיה שקרא ככהן, משום \u0003שקרא אחריו לוי\u0004 ואם לא היה הראשון כהן אין מעלים לוי אחריו. \u0003והעלהו ר' אמי לכהונה על פיו\u0004 של עד זה, אף שלא העיד ממש שידוע לו שאותו אדם ממשפחת כהנים.","כיוצא בזה מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[אחד שבא לפני]\u0006 \u0003ר' יהושע בן לוי\u0004 להעיד. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מוחזקני ב\u0004אדם \u0003זה שהוא לוי. אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע בן לוי: \u0003מה ראית?\u0004 על מה סומך אתה בדבריך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שקרא שני בבית הכנסת.\u0004 ושאל אותו ר' יהושע בן לוי: האם קרא שני \u0003בחזקת שהוא לוי, או בחזקת שהוא גדול?\u0004 שכאשר אין כהן בבית הכנסת קוראים לתורה לפי סדר גדולתם וחשיבותם של האנשים, ושמא היה הוא השני בחשיבות בבית הכנסת? אמר לו: \u0003שקרא לפניו כהן.\u0004 והעולה שני לאחר כהן הוא בודאי לוי. \u0003והעלהו ר' יהושע בן לוי ללויה על פיו.\u0004","ועוד מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[אחד שבא לפני]\u0006 \u0003ריש לקיש\u0004 להעיד, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מוחזקני ב\u0004אדם \u0003זה שהוא כהן. אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003מה ראית?\u0004 על מה סומך אתה בדבריך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 ראיתי \u0003שקרא ראשון בבית הכנסת. אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: האם \u0003ראיתיו\u0004 (ראית אותו) \u0003שחילק\u0004 תרומה \u0003על הגרנות?\u0004 וכל עוד אין עדות שקיבל תרומה בגורן אין זו ראיה לכהונה. \u0003אמר לו ר' אלעזר: ואם אין שם גורן\u0004 באותו מקום, ולא הלך לחלוק, האם \u0003בטלה\u0004 בשל כך \u0003כהונה?\u0004 ולכן די בראיה שקרא ראשון.","\u0003זימנין הוו יתבי קמיה\u0004 \u0005[פעם\u0006 אחרת \u0005היו יושבים\u0006 ר' אלעזר וריש לקיש \u0005לפני]\u0006 \u0003ר' יוחנן, אתא כי הא מעשה לקמיה\u0004 \u0005[בא מעשה כגון זה לפניו],\u0006 לפני ר' יוחנן, שהעיד אדם על חבירו שהוא כהן, לאחר שראה שקרא ראשון בבית הכנסת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש:\u0004 האם \u0003ראיתיו שחילק\u0004 תרומה \u0003על הגורן? אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן\u0004 לריש לקיש: \u0003ואם אין שם גורן\u0004 וכי \u0003בטלה\u0004 בשל כך \u0003כהונה?\u0004 ומעירים: \u0003הדר חזייה\u0004 \u0005[פנה\u0006 ריש לקיש ו\u0005הסתכל]\u0006 \u0003לר' אלעזר בישות\u0004 \u0005[\u0006בעין \u0005רעה],\u0006 משום שהבין שר' אלעזר אמר בשעתו דברים ששמע מר' יוחנן, וכך \u0003אמר\u0004 ריש לקיש לר' אלעזר: \u0003שמעת מילי דבר נפחא\u0004 \u0005[שמעת דברים של בן הנפח,\u0006 מר' יוחנן בן נפחא\u0005],\u0006 \u0003ולא אמרת לן משמיה\u0004 \u0005[לנו משמו]?\u0006 שאילו היית אומר בשמו, הייתי מקבל את דבריך בשעתם.","מסופר: \u0003רבי ור' חייא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003העלה בן על פי\u0004 עדות \u0003אביו לכהונה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003העלה אח על פי\u0004 עדות \u0003אחיו ללויה\u0004 ולא היה ברור מי מהם עשה איזה מעשה.","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003רבי\u0004 הוא ש\u0003העלה בן על פי אביו לכהונה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שבא\u0004 אדם \u0003ואמר\u0004 על אחד: \u0003בני זה, וכהן הוא\u0004 — הרי הוא \u0003נאמן להאכילו בתרומה,\u0004 אבל \u0003אינו נאמן להשיאו אשה\u0004 מיוחסת, שאין סומכים על עדותו לענייני יוחסין, אלו \u0003דברי רבי. אמר לו ר' חייא: אם אתה מאמינו\u0004 לאב המעיד על בנו \u0003להאכילו בתרומה — תאמינו\u0004 גם כן לענין \u0003להשיאו אשה, ואם אי\u0004 (אין) \u0003אתה מאמינו להשיאו אשה — לא תאמינו\u0004 גם \u0003לאכול בתרומה!\u0004","\u0003אמר לו\u0004 רבי: \u0003אני מאמינו להאכילו בתרומה\u0004 — משום \u0003ש\u0004הרי \u0003בידו להאכילו בתרומה,\u0004 שהרי אם רוצה הוא להאכיל את בנו בתרומה יכול הוא עצמו לעשות זאת, ועל דבר שבידו של אדם — מאמינים לו, \u0003ואיני מאמינו להשיאו אשה — ש\u0004הרי \u0003אין בידו להשיאו אשה,\u0004 שהרי לא בו תלוי הדבר, ואין הוא נאמן להעיד על בנו בכך. ולמדנו מכאן שרבי העלה בן על ידי עדות אביו לכהונה. ומסכמים: אכן, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שכך היה המעשה שרבי הוא שהעלה את הבן לכהונה על פי עדות אביו. \u0003ומ\u0004כיון ש\u0003רבי\u0004 הוא ש\u0003העלה בן על פי אביו לכהונה\u0004 — אם כן צריך לומר כי \u0003ר' חייא\u0004 הוא ש\u0003העלה אח על פי אחיו ללויה.\u0004","ושואלים: \u0003ור' חייא מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003בן\u0004 ש\u0003לא\u0004 סומכים על עדות אביו — משום ש\u0003קרוב הוא אצל אביו,\u0004 ואין האב יכול להעיד על בנו — והרי \u0003אח נמי\u0004 \u0005[גם כן]\u0006 הלא \u0003קרוב הוא אצל אחיו,\u0004 ומדוע סמך על עדות האח ולא סמך על האב? שאם אינו סומך על עדות קרובים — הרי בשניהם קיים אותו חשש?!"]]};
